const EMBEDDED_PASS_ERROR_DISPLAY_LIMIT: usize = 32;

#[derive(Debug)]
struct EmbeddedIdentityHiveCandidate {
    entry_id: i64,
    source_job_id: i64,
    logical_path: String,
    name: String,
}

#[derive(Debug)]
struct DerivedIdentityEntry {
    logical_path: String,
    display_name: String,
    metadata: serde_json::Value,
}

/// Extracts identity and network metadata from allocated SAM, SOFTWARE, and
/// SYSTEM hives plus high-confidence WLAN profiles and credential-store
/// locations. Plaintext WLAN key material is retained only when it is already
/// present in the structured profile; encrypted blobs are never mislabeled as
/// decoded passwords.
pub fn parse_identity_artifacts(case_path: &Path, evidence_id: i64) -> Result<IdentityParseResult> {
    let candidates = {
        let conn = open_existing_case(case_path)?;
        let case_id = active_case_id(&conn)?;
        ensure_evidence_source(&conn, case_id, evidence_id)?;
        let mut stmt = conn.prepare(
            "SELECT id, discovered_by_job_id, logical_path, name
             FROM filesystem_entries
             WHERE case_id = ?1 AND evidence_id = ?2 AND entry_kind = 'file'
               AND is_deleted = 0 AND lower(name) IN ('sam', 'software', 'system')
               AND (lower(replace(logical_path, '\\', '/')) LIKE '%/windows/system32/config/%'
                    OR lower(replace(logical_path, '\\', '/')) LIKE '%/winnt/system32/config/%')
             ORDER BY CASE lower(name) WHEN 'sam' THEN 0 ELSE 1 END, id",
        )?;
        let rows = stmt.query_map(params![case_id, evidence_id], |row| {
            Ok(EmbeddedIdentityHiveCandidate {
                entry_id: row.get(0)?,
                source_job_id: row.get(1)?,
                logical_path: row.get(2)?,
                name: row.get(3)?,
            })
        })?;
        rows.collect::<std::result::Result<Vec<_>, _>>()?
    };

    let mut result = IdentityParseResult {
        evidence_id,
        hives_found: candidates.len(),
        hives_parsed: 0,
        local_accounts_indexed: 0,
        domain_accounts_indexed: 0,
        user_profiles_indexed: 0,
        browser_accounts_indexed: 0,
        host_identities_indexed: 0,
        network_artifacts_indexed: 0,
        wifi_profiles_indexed: 0,
        credential_stores_indexed: 0,
        plaintext_secrets_indexed: 0,
        parse_error_count: 0,
        parse_errors: Vec::new(),
        parse_errors_omitted: 0,
        truncated: false,
        status: "completed".to_string(),
    };
    progress::progress_set_unit("hives");
    progress::progress_set_total(Some(candidates.len() as u64));
    let mut read_session = EvidenceReadSession::open(case_path)?;
    for candidate in &candidates {
        progress::progress_current(candidate.logical_path.clone());
        match parse_one_identity_hive(case_path, &mut read_session, evidence_id, candidate) {
            Ok((local_accounts, domain_accounts, profiles, hosts, networks)) => {
                result.hives_parsed += 1;
                result.local_accounts_indexed += local_accounts;
                result.domain_accounts_indexed += domain_accounts;
                result.user_profiles_indexed += profiles;
                result.host_identities_indexed += hosts;
                result.network_artifacts_indexed += networks;
            }
            Err(err) => {
                result.parse_error_count = result.parse_error_count.saturating_add(1);
                let message = format!(
                    "{} (entry {}): {err:#}",
                    candidate.logical_path, candidate.entry_id
                );
                progress::progress_diagnostic(
                    progress::JobDiagnosticKind::ParserDiagnostic,
                    message.clone(),
                );
                if result.parse_errors.len() < EMBEDDED_PASS_ERROR_DISPLAY_LIMIT {
                    result.parse_errors.push(message);
                } else {
                    result.parse_errors_omitted = result.parse_errors_omitted.saturating_add(1);
                }
                progress::progress_error(Some(candidate.logical_path.clone()));
                progress::progress_skip(Some(candidate.logical_path.clone()));
            }
        }
        progress::progress_advance(candidate.logical_path.clone());
    }
    progress::progress_set_total(None);
    progress::progress_set_unit("identity artifacts");
    result.browser_accounts_indexed = derive_browser_account_identities(case_path, evidence_id)?;
    let (wifi_profiles, wifi_errors) =
        derive_wifi_profiles(case_path, &mut read_session, evidence_id)?;
    result.wifi_profiles_indexed = wifi_profiles;
    for error in wifi_errors {
        result.parse_error_count = result.parse_error_count.saturating_add(1);
        progress::progress_diagnostic(progress::JobDiagnosticKind::ParserDiagnostic, error.clone());
        if result.parse_errors.len() < EMBEDDED_PASS_ERROR_DISPLAY_LIMIT {
            result.parse_errors.push(error);
        } else {
            result.parse_errors_omitted = result.parse_errors_omitted.saturating_add(1);
        }
    }
    result.credential_stores_indexed = derive_credential_store_leads(case_path, evidence_id)?;
    let (plaintext_secrets, secret_errors) =
        derive_plaintext_secret_leads(case_path, &mut read_session, evidence_id)?;
    result.plaintext_secrets_indexed = plaintext_secrets;
    for error in secret_errors {
        result.parse_error_count = result.parse_error_count.saturating_add(1);
        progress::progress_diagnostic(progress::JobDiagnosticKind::ParserDiagnostic, error.clone());
        if result.parse_errors.len() < EMBEDDED_PASS_ERROR_DISPLAY_LIMIT {
            result.parse_errors.push(error);
        } else {
            result.parse_errors_omitted = result.parse_errors_omitted.saturating_add(1);
        }
    }
    result.truncated = result.parse_error_count > 0;
    result.status = if result.truncated {
        progress::progress_truncated(format!(
            "{} identity hive(s) could not be parsed; {} diagnostic(s) omitted",
            result.parse_error_count, result.parse_errors_omitted
        ));
        "truncated".to_string()
    } else {
        "completed".to_string()
    };
    Ok(result)
}

fn derive_browser_account_identities(case_path: &Path, evidence_id: i64) -> Result<usize> {
    let mut conn = open_existing_case(case_path)?;
    let case_id = active_case_id(&conn)?;
    let source_rows = {
        let mut stmt = conn.prepare(
            "SELECT id, discovered_by_job_id, logical_path, metadata_json
             FROM filesystem_entries
             WHERE case_id = ?1 AND evidence_id = ?2
               AND json_extract(metadata_json, '$.artifact_kind') = 'browser_login'
             ORDER BY id",
        )?;
        let rows = stmt.query_map(params![case_id, evidence_id], |row| {
            Ok((
                row.get::<_, i64>(0)?,
                row.get::<_, i64>(1)?,
                row.get::<_, String>(2)?,
                row.get::<_, String>(3)?,
            ))
        })?;
        rows.collect::<std::result::Result<Vec<_>, _>>()?
    };
    let tx = conn.transaction_with_behavior(TransactionBehavior::Immediate)?;
    tx.execute(
        "DELETE FROM filesystem_entries
         WHERE case_id = ?1 AND evidence_id = ?2
           AND json_extract(metadata_json, '$.artifact_kind') = 'browser_account'",
        params![case_id, evidence_id],
    )?;
    let mut seen = HashSet::new();
    let mut indexed = 0_usize;
    for (source_entry_id, source_job_id, source_path, metadata_text) in source_rows {
        let source: serde_json::Value = serde_json::from_str(&metadata_text).unwrap_or_default();
        let username = source["username"]
            .as_str()
            .map(str::trim)
            .filter(|value| !value.is_empty());
        let Some(username) = username else { continue };
        let host = source["host"]
            .as_str()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .unwrap_or("unknown service");
        let browser_family = source["browser_family"].as_str().unwrap_or("browser");
        let dedupe_key = format!(
            "{}\u{1f}{}\u{1f}{}",
            browser_family.to_ascii_lowercase(),
            host.to_ascii_lowercase(),
            username.to_ascii_lowercase()
        );
        if !seen.insert(dedupe_key) {
            continue;
        }
        let display_name = format!("{username} @ {host}");
        let logical_path = format!(
            "/Parsed identities/Browser accounts/{}/{:08}-{}.record",
            sanitize_logical_segment(browser_family),
            source_entry_id,
            sanitize_logical_segment(&display_name)
        );
        let mut metadata = serde_json::json!({
            "artifact_kind": "browser_account",
            "account_identifier": username,
            "account_service": host,
            "browser_family": browser_family,
            "identity_source": "saved browser login metadata",
            "identity_confidence": "high",
            "date_created_utc": source["date_created_utc"],
            "date_last_used_utc": source["date_last_used_utc"],
            "times_used": source["times_used"],
            "secrets_accessed": false,
            "secret_scope_note": "this derived identity row contains username and service only; the source browser-login record retains any available password ciphertext separately",
            "derived_from_entry_id": source_entry_id,
            "source_artifact_path": source_path,
        });
        add_entry_category(&mut metadata, &logical_path, &display_name, "record");
        upsert_filesystem_entry(
            &tx,
            case_id,
            evidence_id,
            &logical_path,
            &display_name,
            "record",
            None,
            &metadata.to_string(),
            source_job_id,
        )?;
        indexed += 1;
    }
    tx.commit()?;
    Ok(indexed)
}

fn parse_one_identity_hive(
    case_path: &Path,
    read_session: &mut EvidenceReadSession,
    evidence_id: i64,
    candidate: &EmbeddedIdentityHiveCandidate,
) -> Result<(usize, usize, usize, usize, usize)> {
    let nonce = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos();
    // Keep evidence-controlled names out of host paths. A crafted raw filename
    // must never introduce separators or parent components into a staging path.
    let staging_path = std::env::temp_dir().join(format!(
        "kdft-identity-hive-{}-{}-{nonce}.hive",
        std::process::id(),
        candidate.entry_id
    ));
    let parsed = (|| -> Result<_> {
        recover_filesystem_entry_in_session(
            read_session,
            RecoverEntryOptions {
                entry_id: candidate.entry_id,
                output_path: staging_path.clone(),
            },
        )
        .with_context(|| {
            format!(
                "exporting embedded identity hive {}",
                candidate.logical_path
            )
        })?;
        collect_registry_hive_import(&staging_path, &candidate.name, usize::MAX)
    })();
    let cleanup = match fs::remove_file(&staging_path) {
        Ok(()) => Ok(()),
        Err(error) if error.kind() == io::ErrorKind::NotFound => Ok(()),
        Err(error) => Err(error)
            .with_context(|| format!("removing staged identity hive {}", staging_path.display())),
    };
    let import = parsed?;
    cleanup?;

    let hive_name = candidate.name.to_ascii_lowercase();
    let mut derived = Vec::new();
    if hive_name == "sam" {
        for entry in &import.entries {
            if entry.metadata["artifact_kind"] != "registry_key" {
                continue;
            }
            let key_path = entry.metadata["registry_key_path"]
                .as_str()
                .unwrap_or("")
                .replace('\\', "/")
                .to_ascii_lowercase();
            if !key_path.contains("/domains/account/users/names/") {
                continue;
            }
            let username = entry.display_name.trim();
            if username.is_empty() || username.eq_ignore_ascii_case("names") {
                continue;
            }
            let logical_path = format!(
                "/Parsed identities/Windows local accounts/{:08}-{}.record",
                candidate.entry_id,
                sanitize_logical_segment(username)
            );
            let mut metadata = serde_json::json!({
                "artifact_kind": "windows_local_account",
                "account_name": username,
                "account_scope": "local Windows account",
                "identity_source": "SAM\\Domains\\Account\\Users\\Names",
                "registry_key_path": entry.metadata["registry_key_path"],
                "registry_key_last_write_utc": entry.metadata["registry_key_last_write_utc"],
                "artifact_time_utc": entry.metadata["registry_key_last_write_utc"],
                "identity_confidence": "high",
                "secrets_accessed": false,
                "secret_scope_note": "identity metadata only; password hashes and credential material were not read",
                "derived_from_entry_id": candidate.entry_id,
                "source_artifact_path": candidate.logical_path,
                "identity_parser": REGISTRY_PARSER_NAME,
            });
            add_entry_category(&mut metadata, &logical_path, username, "record");
            derived.push(DerivedIdentityEntry {
                logical_path,
                display_name: username.to_string(),
                metadata,
            });
        }
    } else if hive_name == "software" {
        for entry in &import.entries {
            if entry.metadata["artifact_kind"] != "registry_value"
                || !entry.display_name.eq_ignore_ascii_case("ProfileImagePath")
            {
                continue;
            }
            let key_path = entry.metadata["registry_key_path"]
                .as_str()
                .unwrap_or("")
                .replace('\\', "/");
            let key_path_lower = key_path.to_ascii_lowercase();
            if !key_path_lower.contains("/microsoft/windows nt/currentversion/profilelist/") {
                continue;
            }
            let sid = key_path.rsplit('/').next().unwrap_or("").trim();
            let profile_path = entry.metadata["registry_value_data"]
                .as_str()
                .unwrap_or("")
                .trim();
            if sid.is_empty() || profile_path.is_empty() {
                continue;
            }
            let profile_name = profile_path
                .trim_end_matches(['/', '\\'])
                .rsplit(['/', '\\'])
                .next()
                .unwrap_or("")
                .trim();
            let display_name = if profile_name.is_empty() {
                sid.to_string()
            } else {
                format!("{profile_name} ({sid})")
            };
            let logical_path = format!(
                "/Parsed identities/Windows user profiles/{:08}-{}.record",
                candidate.entry_id,
                sanitize_logical_segment(sid)
            );
            let mut metadata = serde_json::json!({
                "artifact_kind": "windows_user_profile",
                "profile_sid": sid,
                "profile_path": profile_path,
                "profile_name": profile_name,
                "identity_source": "SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\ProfileList",
                "registry_key_path": entry.metadata["registry_key_path"],
                "registry_key_last_write_utc": entry.metadata["registry_key_last_write_utc"],
                "artifact_time_utc": entry.metadata["registry_key_last_write_utc"],
                "identity_confidence": "high",
                "secrets_accessed": false,
                "secret_scope_note": "identity metadata only; credential material was not read",
                "derived_from_entry_id": candidate.entry_id,
                "source_artifact_path": candidate.logical_path,
                "identity_parser": REGISTRY_PARSER_NAME,
            });
            add_entry_category(&mut metadata, &logical_path, &display_name, "record");
            derived.push(DerivedIdentityEntry {
                logical_path,
                display_name,
                metadata,
            });
        }
    }

    let observations = import
        .entries
        .iter()
        .filter(|entry| entry.metadata["artifact_kind"] == "registry_value")
        .filter_map(|entry| {
            let key_path = entry.metadata["registry_key_path"].as_str()?.to_string();
            let value_data = entry.metadata["registry_value_data"].as_str()?.to_string();
            Some(identity_network::RegistryObservation {
                key_path,
                value_name: entry.display_name.clone(),
                value_data,
                last_write_utc: entry.metadata["registry_key_last_write_utc"]
                    .as_str()
                    .map(str::to_string),
            })
        })
        .collect::<Vec<_>>();
    for (ordinal, lead) in identity_network::derive_registry_leads(&hive_name, &observations)
        .into_iter()
        .enumerate()
    {
        let family = if lead.artifact_kind == "host_identity" {
            "Hosts and computer names"
        } else {
            "IP and network configuration"
        };
        let logical_path = format!(
            "/Parsed identities/{family}/{:08}-{:06}-{}.record",
            candidate.entry_id,
            ordinal,
            sanitize_logical_segment(&lead.label)
        );
        let mut metadata = serde_json::to_value(&lead)
            .context("serializing structured Registry identity/network lead")?;
        metadata["source_artifact_path"] = serde_json::json!(candidate.logical_path);
        metadata["derived_from_entry_id"] = serde_json::json!(candidate.entry_id);
        metadata["identity_parser"] = serde_json::json!(REGISTRY_PARSER_NAME);
        metadata["structured_source"] = serde_json::json!(true);
        add_entry_category(&mut metadata, &logical_path, &lead.label, "record");
        derived.push(DerivedIdentityEntry {
            logical_path,
            display_name: lead.label,
            metadata,
        });
    }
    for (ordinal, account) in
        identity_network::derive_registry_domain_accounts(&hive_name, &observations)
            .into_iter()
            .enumerate()
    {
        let display_name = account.qualified_account.clone();
        let logical_path = format!(
            "/Parsed identities/Windows configured domain accounts/{:08}-{:06}-{}.record",
            candidate.entry_id,
            ordinal,
            sanitize_logical_segment(&display_name)
        );
        let mut metadata = serde_json::to_value(&account)
            .context("serializing configured Windows domain account")?;
        metadata["artifact_kind"] = serde_json::json!("windows_domain_account");
        metadata["account_scope"] = serde_json::json!("configured Windows domain logon");
        metadata["identity_confidence"] = serde_json::json!("medium");
        metadata["domain_membership_proven"] = serde_json::json!(false);
        metadata["scope_note"] = serde_json::json!(
            "Winlogon contains an explicit domain/user pair; this does not by itself prove current Active Directory membership"
        );
        metadata["source_artifact_path"] = serde_json::json!(candidate.logical_path);
        metadata["derived_from_entry_id"] = serde_json::json!(candidate.entry_id);
        metadata["identity_parser"] = serde_json::json!(REGISTRY_PARSER_NAME);
        metadata["structured_source"] = serde_json::json!(true);
        add_entry_category(&mut metadata, &logical_path, &display_name, "record");
        derived.push(DerivedIdentityEntry {
            logical_path,
            display_name,
            metadata,
        });
    }

    let local_accounts = derived
        .iter()
        .filter(|entry| entry.metadata["artifact_kind"] == "windows_local_account")
        .count();
    let domain_accounts = derived
        .iter()
        .filter(|entry| entry.metadata["artifact_kind"] == "windows_domain_account")
        .count();
    let profiles = derived
        .iter()
        .filter(|entry| entry.metadata["artifact_kind"] == "windows_user_profile")
        .count();
    let hosts = derived
        .iter()
        .filter(|entry| entry.metadata["artifact_kind"] == "host_identity")
        .count();
    let networks = derived
        .iter()
        .filter(|entry| entry.metadata["artifact_kind"] == "network_configuration")
        .count();
    let mut conn = open_existing_case(case_path)?;
    let case_id = active_case_id(&conn)?;
    let tx = conn.transaction_with_behavior(TransactionBehavior::Immediate)?;
    tx.execute(
        "DELETE FROM filesystem_entries
         WHERE case_id = ?1 AND evidence_id = ?2
           AND json_extract(metadata_json, '$.derived_from_entry_id') = ?3
           AND json_extract(metadata_json, '$.artifact_kind') IN (
               'windows_local_account','windows_domain_account','windows_user_profile',
               'host_identity','network_configuration'
           )",
        params![case_id, evidence_id, candidate.entry_id],
    )?;
    for entry in derived {
        upsert_filesystem_entry(
            &tx,
            case_id,
            evidence_id,
            &entry.logical_path,
            &entry.display_name,
            "record",
            None,
            &entry.metadata.to_string(),
            candidate.source_job_id,
        )?;
    }
    tx.commit()?;
    Ok((local_accounts, domain_accounts, profiles, hosts, networks))
}

#[derive(Debug)]
struct EmbeddedWifiProfileCandidate {
    entry_id: i64,
    source_job_id: i64,
    logical_path: String,
    name: String,
}

fn derive_wifi_profiles(
    case_path: &Path,
    read_session: &mut EvidenceReadSession,
    evidence_id: i64,
) -> Result<(usize, Vec<String>)> {
    let candidates = {
        let conn = open_existing_case(case_path)?;
        let case_id = active_case_id(&conn)?;
        let mut stmt = conn.prepare(
            "SELECT id, discovered_by_job_id, logical_path, name
             FROM filesystem_entries
             WHERE case_id = ?1 AND evidence_id = ?2
               AND entry_kind = 'file' AND is_deleted = 0
               AND lower(name) LIKE '%.xml'
               AND lower(replace(COALESCE(
                   NULLIF(json_extract(metadata_json, '$.source_path_exact'), ''),
                   NULLIF(json_extract(metadata_json, '$.ntfs_path'), ''),
                   logical_path
               ), '\\', '/')) LIKE '%/programdata/microsoft/wlansvc/profiles/interfaces/%'
             ORDER BY id",
        )?;
        let rows = stmt.query_map(params![case_id, evidence_id], |row| {
            Ok(EmbeddedWifiProfileCandidate {
                entry_id: row.get(0)?,
                source_job_id: row.get(1)?,
                logical_path: row.get(2)?,
                name: row.get(3)?,
            })
        })?;
        rows.collect::<std::result::Result<Vec<_>, _>>()?
    };

    let mut derived = Vec::new();
    let mut errors = Vec::new();
    for candidate in candidates {
        let nonce = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default()
            .as_nanos();
        let staging_path = std::env::temp_dir().join(format!(
            "kdft-wifi-profile-{}-{}-{nonce}.xml",
            std::process::id(),
            candidate.entry_id
        ));
        let parsed = (|| -> Result<identity_network::WifiProfile> {
            recover_filesystem_entry_in_session(
                read_session,
                RecoverEntryOptions {
                    entry_id: candidate.entry_id,
                    output_path: staging_path.clone(),
                },
            )
            .with_context(|| format!("recovering WLAN profile {}", candidate.logical_path))?;
            let bytes = fs::read(&staging_path).with_context(|| {
                format!("reading recovered WLAN profile {}", candidate.logical_path)
            })?;
            identity_network::parse_wifi_profile_xml(&bytes)
                .with_context(|| format!("parsing WLAN profile {}", candidate.logical_path))
        })();
        let cleanup_error = if staging_path.exists() {
            fs::remove_file(&staging_path).err()
        } else {
            None
        };
        if let Some(error) = cleanup_error {
            errors.push(format!(
                "{}: parsed staging file could not be removed: {error}",
                candidate.logical_path
            ));
        }
        let profile = match parsed {
            Ok(profile) => profile,
            Err(error) => {
                errors.push(format!("{}: {error:#}", candidate.logical_path));
                continue;
            }
        };
        let display_name = profile
            .ssid
            .as_deref()
            .or(profile.profile_name.as_deref())
            .unwrap_or(&candidate.name)
            .to_string();
        let logical_path = format!(
            "/Parsed identities/Wi-Fi profiles/{:08}-{}.record",
            candidate.entry_id,
            sanitize_logical_segment(&display_name)
        );
        let key_is_protected = profile
            .key_protected
            .as_deref()
            .is_some_and(|value| value.eq_ignore_ascii_case("true"));
        let key_material = profile.key_material.clone();
        let sensitive_value_present = key_material.is_some();
        let mut metadata = serde_json::json!({
            "artifact_kind": "wifi_profile",
            "profile_name": profile.profile_name,
            "ssid": profile.ssid,
            "authentication": profile.authentication,
            "encryption": profile.encryption,
            "key_type": profile.key_type,
            "key_material_protected": key_is_protected,
            "wifi_key_plaintext": if key_is_protected { None } else { key_material.clone() },
            "wifi_key_encrypted": if key_is_protected { key_material } else { None },
            "sensitive_value_present": sensitive_value_present,
            "source_artifact_path": candidate.logical_path,
            "derived_from_entry_id": candidate.entry_id,
            "structured_source": true,
            "parser": "kdft-wlan-profile-xml-v1",
        });
        add_entry_category(&mut metadata, &logical_path, &display_name, "record");
        derived.push((
            candidate.source_job_id,
            DerivedIdentityEntry {
                logical_path,
                display_name,
                metadata,
            },
        ));
    }

    let mut conn = open_existing_case(case_path)?;
    let case_id = active_case_id(&conn)?;
    let tx = conn.transaction_with_behavior(TransactionBehavior::Immediate)?;
    for (source_job_id, entry) in &derived {
        upsert_filesystem_entry(
            &tx,
            case_id,
            evidence_id,
            &entry.logical_path,
            &entry.display_name,
            "record",
            None,
            &entry.metadata.to_string(),
            *source_job_id,
        )?;
    }
    tx.commit()?;
    Ok((derived.len(), errors))
}

fn derive_credential_store_leads(case_path: &Path, evidence_id: i64) -> Result<usize> {
    let candidates = {
        let conn = open_existing_case(case_path)?;
        let case_id = active_case_id(&conn)?;
        let mut stmt = conn.prepare(
            "SELECT id, discovered_by_job_id, name,
                    COALESCE(
                        NULLIF(json_extract(metadata_json, '$.source_path_exact'), ''),
                        NULLIF(json_extract(metadata_json, '$.ntfs_path'), ''),
                        logical_path
                    )
             FROM filesystem_entries
             WHERE case_id = ?1 AND evidence_id = ?2
               AND entry_kind = 'file' AND is_deleted = 0
               AND (
                   lower(name) IN (
                       'sam','security','ntds.dit','login data','logins.json','key4.db','key3.db',
                       'id_rsa','id_dsa','id_ecdsa','id_ed25519','credentials',
                       'accesstokens.json','azureprofile.json','msal_token_cache.json'
                   )
                   OR lower(name) LIKE '%.kdbx'
                   OR lower(name) LIKE '%.psafe3'
                   OR lower(name) LIKE '%.vcrd'
                   OR lower(name) LIKE '%.vpol'
                   OR lower(replace(logical_path, '\\', '/')) LIKE '%/microsoft/credentials/%'
                   OR lower(replace(logical_path, '\\', '/')) LIKE '%/microsoft/vault/%'
                   OR lower(replace(logical_path, '\\', '/')) LIKE '%/microsoft/protect/%'
                   OR lower(replace(logical_path, '\\', '/')) LIKE '%/.ssh/%'
                   OR lower(replace(logical_path, '\\', '/')) LIKE '%/.aws/credentials'
               )
             ORDER BY id",
        )?;
        let rows = stmt.query_map(params![case_id, evidence_id], |row| {
            Ok((
                row.get::<_, i64>(0)?,
                row.get::<_, i64>(1)?,
                row.get::<_, String>(2)?,
                row.get::<_, String>(3)?,
            ))
        })?;
        rows.collect::<std::result::Result<Vec<_>, _>>()?
    };

    let mut conn = open_existing_case(case_path)?;
    let case_id = active_case_id(&conn)?;
    let tx = conn.transaction_with_behavior(TransactionBehavior::Immediate)?;
    let mut indexed = 0_usize;
    for (entry_id, source_job_id, name, exact_path) in candidates {
        let Some(store_type) = identity_network::known_credential_store_type(&exact_path, &name)
        else {
            continue;
        };
        let derived_path = format!(
            "/Parsed identities/Credential stores/{entry_id:08}-{}.record",
            sanitize_logical_segment(&name)
        );
        let mut metadata = serde_json::json!({
            "artifact_kind": "credential_store",
            "credential_store_type": store_type,
            "source_artifact_path": exact_path,
            "source_entry_id": entry_id,
            "derived_from_entry_id": entry_id,
            "contains_sensitive_material": true,
            "values_extracted": false,
            "encrypted_material_not_presented_as_plaintext": true,
            "parser": "kdft-known-credential-stores-v1",
        });
        add_entry_category(&mut metadata, &derived_path, &name, "record");
        upsert_filesystem_entry(
            &tx,
            case_id,
            evidence_id,
            &derived_path,
            &format!("{store_type}: {name}"),
            "record",
            None,
            &metadata.to_string(),
            source_job_id,
        )?;
        indexed = indexed.saturating_add(1);
    }
    tx.commit()?;
    Ok(indexed)
}

#[derive(Debug)]
struct PlaintextSecretCandidate {
    entry_id: i64,
    source_job_id: i64,
    logical_path: String,
    exact_path: String,
    name: String,
    size_bytes: Option<i64>,
}

fn derive_plaintext_secret_leads(
    case_path: &Path,
    read_session: &mut EvidenceReadSession,
    evidence_id: i64,
) -> Result<(usize, Vec<String>)> {
    const MAX_PLAINTEXT_SECRET_SOURCE_BYTES: i64 = 8 * 1024 * 1024;
    let candidates = {
        let conn = open_existing_case(case_path)?;
        let case_id = active_case_id(&conn)?;
        let mut statement = conn.prepare(
            "SELECT id, discovered_by_job_id, logical_path, name, size_bytes,
                    COALESCE(
                        NULLIF(json_extract(metadata_json, '$.source_path_exact'), ''),
                        NULLIF(json_extract(metadata_json, '$.ntfs_path'), ''),
                        NULLIF(json_extract(metadata_json, '$.fat_path'), ''),
                        NULLIF(json_extract(metadata_json, '$.ext_path'), ''),
                        NULLIF(json_extract(metadata_json, '$.local_relative_path'), ''),
                        logical_path
                    )
             FROM filesystem_entries
             WHERE case_id = ?1 AND evidence_id = ?2
               AND entry_kind = 'file' AND is_deleted = 0
               AND COALESCE(size_bytes, 0) <= ?3
               AND (
                   lower(name) = '.env' OR lower(name) LIKE '.env.%'
                   OR lower(name) IN (
                       '.git-credentials','.netrc','.npmrc','.pypirc','pip.conf',
                       'unattend.xml','autounattend.xml','accesstokens.json',
                       'application_default_credentials.json','msal_token_cache.json',
                       'credentials','config.json','config','secrets.json'
                   )
               )
             ORDER BY id",
        )?;
        let rows = statement.query_map(
            params![case_id, evidence_id, MAX_PLAINTEXT_SECRET_SOURCE_BYTES],
            |row| {
                Ok(PlaintextSecretCandidate {
                    entry_id: row.get(0)?,
                    source_job_id: row.get(1)?,
                    logical_path: row.get(2)?,
                    name: row.get(3)?,
                    size_bytes: row.get(4)?,
                    exact_path: row.get(5)?,
                })
            },
        )?;
        rows.collect::<std::result::Result<Vec<_>, _>>()?
            .into_iter()
            .filter(|candidate| {
                identity_network::known_plaintext_secret_source(
                    &candidate.exact_path,
                    &candidate.name,
                )
            })
            .collect::<Vec<_>>()
    };

    let mut indexed = 0_usize;
    let mut errors = Vec::new();
    for candidate in candidates {
        let nonce = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default()
            .as_nanos();
        let staging_path = std::env::temp_dir().join(format!(
            "kdft-secret-source-{}-{}-{nonce}.txt",
            std::process::id(),
            candidate.entry_id
        ));
        let parsed = (|| -> Result<Vec<identity_network::PlaintextSecretLead>> {
            recover_filesystem_entry_in_session(
                read_session,
                RecoverEntryOptions {
                    entry_id: candidate.entry_id,
                    output_path: staging_path.clone(),
                },
            )
            .with_context(|| {
                format!(
                    "recovering structured secret source {}",
                    candidate.exact_path
                )
            })?;
            let bytes = fs::read(&staging_path).with_context(|| {
                format!("reading structured secret source {}", candidate.exact_path)
            })?;
            Ok(identity_network::parse_plaintext_secret_leads(
                &candidate.exact_path,
                &candidate.name,
                &bytes,
            ))
        })();
        let cleanup_error = if staging_path.exists() {
            fs::remove_file(&staging_path).err()
        } else {
            None
        };
        let leads = match parsed {
            Ok(leads) => leads,
            Err(error) => {
                errors.push(format!("{}: {error:#}", candidate.exact_path));
                continue;
            }
        };
        if let Some(error) = cleanup_error {
            errors.push(format!(
                "{}: parsed secret-source staging file could not be removed: {error}",
                candidate.exact_path
            ));
        }
        let mut conn = open_existing_case(case_path)?;
        let case_id = active_case_id(&conn)?;
        let tx = conn.transaction_with_behavior(TransactionBehavior::Immediate)?;
        tx.execute(
            "DELETE FROM filesystem_entries
             WHERE case_id = ?1 AND evidence_id = ?2
               AND json_extract(metadata_json, '$.artifact_kind') = 'plaintext_secret'
               AND json_extract(metadata_json, '$.derived_from_entry_id') = ?3",
            params![case_id, evidence_id, candidate.entry_id],
        )?;
        for (ordinal, lead) in leads.into_iter().enumerate() {
            let display_name = format!("{} ({})", lead.key, candidate.name);
            let logical_path = format!(
                "/Parsed identities/Recovered secrets/{:08}-{ordinal:06}-{}.record",
                candidate.entry_id,
                sanitize_logical_segment(&lead.key)
            );
            let mut metadata = serde_json::json!({
                "artifact_kind": "plaintext_secret",
                "secret_key": lead.key,
                "secret_value": lead.value,
                "secret_source_location": lead.source_location,
                "secret_source_format": lead.source_format,
                "sensitive_value_present": true,
                "secret_interpretation": "plaintext value recovered from an exact structured configuration field",
                "source_artifact_path": candidate.exact_path,
                "source_logical_path": candidate.logical_path,
                "source_size_bytes": candidate.size_bytes,
                "derived_from_entry_id": candidate.entry_id,
                "parser": "kdft-structured-secret-sources-v1",
                "structured_source": true,
            });
            add_entry_category(&mut metadata, &logical_path, &display_name, "record");
            upsert_filesystem_entry(
                &tx,
                case_id,
                evidence_id,
                &logical_path,
                &display_name,
                "record",
                None,
                &metadata.to_string(),
                candidate.source_job_id,
            )?;
            indexed = indexed.saturating_add(1);
        }
        tx.commit()?;
    }
    Ok((indexed, errors))
}

