const CATEGORY_ENTRY_PAGE_LIMIT: usize = 1_000;

/// Exact per-category entry counts computed in SQLite from the stored
/// `category_main` / `category_sub` metadata stamped at process time. Entries
/// processed before category stamping existed land in the "Uncategorized"
/// bucket. This scans every row's metadata_json, so callers should cache the
/// result on large cases (see `max_filesystem_entry_id`).
pub fn category_entry_counts(case_path: &Path) -> Result<Vec<CategoryCount>> {
    let conn = open_existing_case(case_path)?;
    let mut stmt = conn.prepare(
        "SELECT COALESCE(json_extract(metadata_json, '$.category_main'), 'Uncategorized'),
                COALESCE(json_extract(metadata_json, '$.category_sub'), ''),
                COUNT(*)
         FROM filesystem_entries
         WHERE entry_kind != 'directory'
           AND COALESCE(json_extract(metadata_json, '$.category_hidden'), 0) <> 1
           AND COALESCE(json_extract(metadata_json, '$.artifact_kind'), '')
               NOT IN ('filesystem_parser_error', 'filesystem_parser_summary')
           AND NOT (
               COALESCE(json_extract(metadata_json, '$.category_main'), '') = 'Operating System'
               AND COALESCE(json_extract(metadata_json, '$.category_sub'), '') = 'System files'
           )
         GROUP BY 1, 2
         ORDER BY 1, 2",
    )?;
    let rows = stmt.query_map([], |row| {
        Ok(CategoryCount {
            main: row.get(0)?,
            sub: row.get(1)?,
            count: row.get(2)?,
        })
    })?;
    rows.collect::<std::result::Result<Vec<_>, _>>()
        .context("counting entries per category")
}

/// Lists one bounded page of entries in a category directly from the case
/// database. This uses the same stored category semantics as
/// `category_entry_counts`: directory rows are excluded, missing main category
/// values are grouped as "Uncategorized", and missing subcategories are "".
pub fn list_entries_by_category(
    case_path: &Path,
    evidence_id: Option<i64>,
    category_main: &str,
    category_sub: Option<&str>,
    limit: usize,
    offset: usize,
) -> Result<CategoryEntryPage> {
    list_entries_by_category_filtered(
        case_path,
        evidence_id,
        category_main,
        category_sub,
        &CategoryEntryFilters::default(),
        None,
        limit,
        offset,
    )
}

/// Lists a stable keyset page from the complete category result set. Filters
/// run in SQLite before LIMIT is applied, so an extension/name match cannot be
/// hidden merely because it occurs after the browser's currently loaded page.
/// `offset` is retained only for older API callers; the UI uses `after` so deep
/// scrolling does not become progressively slower on very large categories.
pub fn list_entries_by_category_filtered(
    case_path: &Path,
    evidence_id: Option<i64>,
    category_main: &str,
    category_sub: Option<&str>,
    filters: &CategoryEntryFilters,
    after: Option<&CategoryEntryCursor>,
    limit: usize,
    offset: usize,
) -> Result<CategoryEntryPage> {
    let conn = open_existing_case(case_path)?;
    let case_id = active_case_id(&conn)?;
    if let Some(evidence_id) = evidence_id {
        ensure_evidence_source(&conn, case_id, evidence_id)?;
    }
    let category_main = category_main.trim();
    let category_sub = category_sub.map(str::trim);
    let limit = limit.clamp(1, CATEGORY_ENTRY_PAGE_LIMIT);
    let fetch_limit = i64::try_from(limit.saturating_add(1)).unwrap_or(i64::MAX);
    let effective_offset = if after.is_some() { 0 } else { offset };
    let offset_i64 = i64::try_from(effective_offset).unwrap_or(i64::MAX);
    let name_filter = filters
        .name
        .as_deref()
        .map(str::trim)
        .unwrap_or("")
        .to_lowercase();
    let extension_filter = filters
        .extension
        .as_deref()
        .map(str::trim)
        .unwrap_or("")
        .trim_start_matches('.')
        .to_lowercase();
    let type_filter = filters
        .entry_type
        .as_deref()
        .map(str::trim)
        .unwrap_or("")
        .to_lowercase();
    let flags_filter = filters
        .flags
        .as_deref()
        .map(str::trim)
        .unwrap_or("")
        .to_lowercase();
    let sha256_filter = filters
        .sha256
        .as_deref()
        .map(str::trim)
        .unwrap_or("")
        .to_lowercase();
    let date_active = i64::from(
        filters
            .from_utc
            .as_deref()
            .is_some_and(|value| !value.trim().is_empty())
            || filters
                .to_utc
                .as_deref()
                .is_some_and(|value| !value.trim().is_empty()),
    );
    let from_utc = filters
        .from_utc
        .as_deref()
        .filter(|value| !value.trim().is_empty())
        .unwrap_or("0000-01-01T00:00:00Z");
    let to_utc = filters
        .to_utc
        .as_deref()
        .filter(|value| !value.trim().is_empty())
        .unwrap_or("9999-12-31T23:59:59.999Z");
    let after_path = after.map(|cursor| cursor.logical_path.as_str());
    let after_id = after.map(|cursor| cursor.id);

    let total_in_category: i64 = conn
        .query_row(
            "SELECT COUNT(*)
             FROM filesystem_entries
             WHERE case_id = ?1
               AND (?2 IS NULL OR evidence_id = ?2)
                AND entry_kind != 'directory'
                AND COALESCE(json_extract(metadata_json, '$.category_hidden'), 0) <> 1
                AND COALESCE(json_extract(metadata_json, '$.artifact_kind'), '')
                    NOT IN ('filesystem_parser_error', 'filesystem_parser_summary')
                AND NOT (
                   COALESCE(json_extract(metadata_json, '$.category_main'), '') = 'Operating System'
                   AND COALESCE(json_extract(metadata_json, '$.category_sub'), '') = 'System files'
               )
               AND (?3 = '' OR COALESCE(json_extract(metadata_json, '$.category_main'), 'Uncategorized') = ?3)
               AND (?4 IS NULL OR COALESCE(json_extract(metadata_json, '$.category_sub'), '') = ?4)",
            params![case_id, evidence_id, category_main, category_sub],
            |row| row.get(0),
        )
        .context("counting entries in category")?;

    let filtered_predicate = format!(
        "AND (:name_filter = '' OR instr(lower(name), :name_filter) > 0 OR instr(lower(logical_path), :name_filter) > 0)
         AND (:extension_filter = ''
              OR instr(lower(COALESCE(json_extract(metadata_json, '$.file_extension'), '')), :extension_filter) > 0
              OR instr(lower(name), '.' || :extension_filter) > 0)
         AND (:type_filter = ''
              OR instr(lower(entry_kind), :type_filter) > 0
              OR instr(lower(COALESCE(json_extract(metadata_json, '$.artifact_kind'), '')), :type_filter) > 0
              OR instr(lower(COALESCE(json_extract(metadata_json, '$.category_detail'), '')), :type_filter) > 0)
         AND (:flags_filter = '' OR instr(lower(metadata_json), :flags_filter) > 0)
         AND (:sha256_filter = '' OR instr(lower(COALESCE(json_extract(metadata_json, '$.file_sha256'), '')), :sha256_filter) > 0)
         AND (:date_active = 0 OR ({date_range}))",
        date_range = timeline_time_range_sql_clause()
    );

    let filtered_count_sql = format!(
        "SELECT COUNT(*)
         FROM filesystem_entries
         WHERE case_id = :case_id
           AND (:evidence_id IS NULL OR evidence_id = :evidence_id)
           AND entry_kind != 'directory'
           AND COALESCE(json_extract(metadata_json, '$.category_hidden'), 0) <> 1
           AND COALESCE(json_extract(metadata_json, '$.artifact_kind'), '')
               NOT IN ('filesystem_parser_error', 'filesystem_parser_summary')
           AND NOT (
               COALESCE(json_extract(metadata_json, '$.category_main'), '') = 'Operating System'
               AND COALESCE(json_extract(metadata_json, '$.category_sub'), '') = 'System files'
           )
           AND (:category_main = '' OR COALESCE(json_extract(metadata_json, '$.category_main'), 'Uncategorized') = :category_main)
           AND (:category_sub IS NULL OR COALESCE(json_extract(metadata_json, '$.category_sub'), '') = :category_sub)
           {filtered_predicate}"
    );
    let total_matching: i64 = conn
        .query_row(
            &filtered_count_sql,
            named_params! {
                ":case_id": case_id,
                ":evidence_id": evidence_id,
                ":category_main": category_main,
                ":category_sub": category_sub,
                ":name_filter": name_filter,
                ":extension_filter": extension_filter,
                ":type_filter": type_filter,
                ":flags_filter": flags_filter,
                ":sha256_filter": sha256_filter,
                ":date_active": date_active,
                ":from": from_utc,
                ":to": to_utc,
            },
            |row| row.get(0),
        )
        .context("counting filtered entries in category")?;

    let page_sql = format!(
        "SELECT id, case_id, evidence_id, parent_id, logical_path, name, entry_kind,
                size_bytes, is_deleted, metadata_json, discovered_by_job_id
         FROM filesystem_entries
         WHERE case_id = :case_id
           AND (:evidence_id IS NULL OR evidence_id = :evidence_id)
           AND entry_kind != 'directory'
           AND COALESCE(json_extract(metadata_json, '$.category_hidden'), 0) <> 1
           AND COALESCE(json_extract(metadata_json, '$.artifact_kind'), '')
               NOT IN ('filesystem_parser_error', 'filesystem_parser_summary')
           AND NOT (
               COALESCE(json_extract(metadata_json, '$.category_main'), '') = 'Operating System'
               AND COALESCE(json_extract(metadata_json, '$.category_sub'), '') = 'System files'
           )
           AND (:category_main = '' OR COALESCE(json_extract(metadata_json, '$.category_main'), 'Uncategorized') = :category_main)
           AND (:category_sub IS NULL OR COALESCE(json_extract(metadata_json, '$.category_sub'), '') = :category_sub)
           {filtered_predicate}
           AND (:after_path IS NULL
                OR logical_path > :after_path
                OR (logical_path = :after_path AND id > :after_id))
         ORDER BY logical_path, id
         LIMIT :fetch_limit OFFSET :offset"
    );
    let mut stmt = conn.prepare(&page_sql)?;
    let rows = stmt.query_map(
        named_params! {
            ":case_id": case_id,
            ":evidence_id": evidence_id,
            ":category_main": category_main,
            ":category_sub": category_sub,
            ":name_filter": name_filter,
            ":extension_filter": extension_filter,
            ":type_filter": type_filter,
            ":flags_filter": flags_filter,
            ":sha256_filter": sha256_filter,
            ":date_active": date_active,
            ":from": from_utc,
            ":to": to_utc,
            ":after_path": after_path,
            ":after_id": after_id,
            ":fetch_limit": fetch_limit,
            ":offset": offset_i64,
        },
        |row| {
            Ok(RawFilesystemEntry {
                id: row.get(0)?,
                case_id: row.get(1)?,
                evidence_id: row.get(2)?,
                parent_id: row.get(3)?,
                logical_path: row.get(4)?,
                name: row.get(5)?,
                entry_kind: row.get(6)?,
                size_bytes: row.get(7)?,
                is_deleted: row.get::<_, i64>(8)? != 0,
                metadata_json: row.get(9)?,
                discovered_by_job_id: row.get(10)?,
            })
        },
    )?;
    let mut entries = rows
        .collect::<std::result::Result<Vec<_>, _>>()
        .context("listing entries by category")?
        .into_iter()
        .map(filesystem_entry_from_raw)
        .collect::<Result<Vec<_>>>()?;
    let has_more = entries.len() > limit;
    if has_more {
        entries.truncate(limit);
    }
    let next_cursor = if has_more {
        entries.last().map(|last| CategoryEntryCursor {
            logical_path: last.logical_path.clone(),
            id: last.id,
        })
    } else {
        None
    };

    Ok(CategoryEntryPage {
        entries,
        total_in_category,
        total_matching,
        limit,
        offset: effective_offset,
        next_cursor,
    })
}

