fn has_chromium_blockfile_cache_layout(path: &Path) -> bool {
    path.join("index").is_file()
        && (0..=3).any(|index| path.join(format!("data_{index}")).is_file())
}

fn process_chromium_blockfile_cache_evidence(
    conn: &Connection,
    case_id: i64,
    evidence: &EvidenceForProcessing,
    job_id: i64,
    max_entries: usize,
) -> Result<(usize, bool)> {
    let path = PathBuf::from(&evidence.source_path);
    if !path.is_dir() {
        bail!(
            "Chrome cache evidence path is no longer a directory: {}",
            path.display()
        );
    }
    let max_entries = chrome_cache_effective_max_entries(max_entries);
    match collect_chromium_blockfile_cache_import(&path, &evidence.display_name, max_entries) {
        Ok(import_data) => {
            persist_chromium_blockfile_cache_import(conn, case_id, evidence, job_id, import_data)
        }
        Err(err) => persist_unsupported_chromium_blockfile_cache_status(
            conn,
            case_id,
            evidence,
            job_id,
            &format!(
                "Chrome blockfile cache was detected, but the parser could not read it: {err}"
            ),
        ),
    }
}

fn persist_unsupported_chromium_blockfile_cache_status(
    conn: &Connection,
    case_id: i64,
    evidence: &EvidenceForProcessing,
    job_id: i64,
    reason: &str,
) -> Result<(usize, bool)> {
    conn.execute(
        "DELETE FROM filesystem_entries WHERE case_id = ?1 AND evidence_id = ?2",
        params![case_id, evidence.id],
    )?;
    let logical_path = chrome_cache_root_logical_path(&evidence.display_name);
    let mut metadata = serde_json::json!({
        "artifact_kind": "browser_cache_store",
        "browser_family": "chromium",
        "browser_cache_format": "blockfile",
        "browser_cache_parser": CHROME_CACHE_PARSER_NAME,
        "browser_cache_parser_status": "unsupported",
        "browser_cache_parser_error": reason,
        "browser_cache_parser_scope": chrome_cache_parser_scope_text(),
        "source_artifact": "Chrome Cache",
        "source_artifact_path": evidence.source_path,
    });
    add_entry_category(
        &mut metadata,
        &logical_path,
        &evidence.display_name,
        "directory",
    );
    upsert_filesystem_entry(
        conn,
        case_id,
        evidence.id,
        &logical_path,
        &evidence.display_name,
        "directory",
        None,
        &metadata.to_string(),
        job_id,
    )?;
    Ok((1, false))
}

fn persist_chromium_blockfile_cache_import(
    conn: &Connection,
    case_id: i64,
    evidence: &EvidenceForProcessing,
    job_id: i64,
    mut import_data: ChromeCacheImportData,
) -> Result<(usize, bool)> {
    conn.execute(
        "DELETE FROM filesystem_entries WHERE case_id = ?1 AND evidence_id = ?2",
        params![case_id, evidence.id],
    )?;
    if let Some(root) = import_data
        .entries
        .iter_mut()
        .find(|entry| entry.logical_path == import_data.root_logical_path)
    {
        if let Some(object) = root.metadata.as_object_mut() {
            object.insert(
                "browser_cache_entries_indexed".to_string(),
                serde_json::json!(import_data.cache_entries_indexed),
            );
            object.insert(
                "browser_cache_entries_seen".to_string(),
                serde_json::json!(import_data.cache_entries_seen),
            );
            object.insert(
                "browser_cache_truncated".to_string(),
                serde_json::json!(import_data.truncated),
            );
            if !import_data.parser_errors.is_empty() {
                object.insert(
                    "browser_cache_parser_errors".to_string(),
                    serde_json::json!(import_data.parser_errors),
                );
            }
        }
    }
    let entries_indexed = import_data.entries.len();
    for entry in import_data.entries {
        upsert_filesystem_entry_with_content(
            conn,
            case_id,
            evidence.id,
            &entry.logical_path,
            &entry.display_name,
            entry.entry_kind,
            entry.size_bytes,
            &entry.metadata.to_string(),
            job_id,
            entry.content_head.as_deref(),
        )?;
    }
    Ok((entries_indexed, import_data.truncated))
}

fn collect_chromium_blockfile_cache_import(
    path: &Path,
    display_name: &str,
    max_entries: usize,
) -> Result<ChromeCacheImportData> {
    let root_logical_path = chrome_cache_root_logical_path(display_name);
    let mut collector = ChromeCacheImportCollector {
        entries: Vec::new(),
        cache_entries_indexed: 0,
        cache_entries_seen: 0,
        parser_errors: Vec::new(),
        truncated: false,
        max_entries,
        root_logical_path: root_logical_path.clone(),
        source_path: path.to_string_lossy().into_owned(),
        cache_display_name: display_name.to_string(),
        used_paths: HashSet::new(),
    };
    collector.push_cache_root()?;
    if !collector.truncated {
        // chrome-cache-parser 0.2.5 is not defensive against malformed/corrupt index files: a
        // bogus `table_len` in the index header causes an out-of-range slice index PANIC inside
        // the crate's own `addresses()` (verified: `range end index 368 out of range for slice of
        // length 27` against a hand-crafted garbage index). Forensic input is inherently
        // untrusted - a truncated/corrupted real Cache directory is common, not an edge case -
        // so a third-party parser panic here must not be allowed to take down the whole process.
        // catch_unwind converts it into the same graceful "unsupported" fallback used for every
        // other parser error in this codebase.
        // Deliberately NOT touching the global panic hook here to silence the printed
        // backtrace (std::panic::set_hook/take_hook are process-wide, and this server spawns a
        // real OS thread per request - crates/kdft-ui/src/main.rs uses std::thread::spawn - so
        // swapping the hook around this call would race with a panic on any OTHER concurrently
        // handled request). The stderr backtrace this produces on a malformed cache is noisy but
        // harmless; catch_unwind below is what actually matters for correctness/safety.
        let walk_result =
            std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| -> Result<()> {
                let cache = ChromeCache::from_path(path.to_path_buf()).with_context(|| {
                    format!("opening Chrome blockfile cache {}", path.display())
                })?;
                let entries = cache
                    .entries()
                    .with_context(|| format!("reading Chrome cache index {}", path.display()))?;
                for (entry_index, lazy_entry) in entries.enumerate() {
                    if collector.truncated {
                        break;
                    }
                    collector.cache_entries_seen = collector.cache_entries_seen.saturating_add(1);
                    match parse_chromium_blockfile_cache_entry(entry_index, lazy_entry) {
                        Ok(parsed) => collector.push_cache_entry(parsed)?,
                        Err(err) => {
                            collector.note_parser_error(format!("entry {entry_index}: {err}"))
                        }
                    }
                }
                Ok(())
            }));
        match walk_result {
            Ok(Ok(())) => {}
            Ok(Err(err)) => return Err(err),
            Err(panic_payload) => {
                bail!(
                    "Chrome cache parser panicked while reading the cache index/entries: {}",
                    chrome_cache_panic_message(&panic_payload)
                );
            }
        }
    }
    Ok(ChromeCacheImportData {
        entries: collector.entries,
        cache_entries_indexed: collector.cache_entries_indexed,
        cache_entries_seen: collector.cache_entries_seen,
        parser_errors: collector.parser_errors,
        truncated: collector.truncated,
        root_logical_path,
    })
}

fn chrome_cache_panic_message(payload: &(dyn std::any::Any + Send)) -> String {
    if let Some(message) = payload.downcast_ref::<&str>() {
        (*message).to_string()
    } else if let Some(message) = payload.downcast_ref::<String>() {
        message.clone()
    } else {
        "unknown panic (no string payload)".to_string()
    }
}

struct ChromeCacheImportCollector {
    entries: Vec<ChromeCacheImportEntry>,
    cache_entries_indexed: usize,
    cache_entries_seen: usize,
    parser_errors: Vec<String>,
    truncated: bool,
    max_entries: usize,
    root_logical_path: String,
    source_path: String,
    cache_display_name: String,
    used_paths: HashSet<String>,
}

impl ChromeCacheImportCollector {
    fn should_stop_before_push(&mut self) -> bool {
        if self.entries.len() >= self.max_entries {
            self.truncated = true;
            true
        } else {
            false
        }
    }

    fn note_parser_error(&mut self, error: String) {
        if self.parser_errors.len() < CHROME_CACHE_PARSER_ERROR_LIMIT {
            self.parser_errors.push(error);
        }
    }

    fn push_cache_root(&mut self) -> Result<()> {
        if self.should_stop_before_push() {
            return Ok(());
        }
        self.used_paths.insert(self.root_logical_path.clone());
        let mut metadata = serde_json::json!({
            "artifact_kind": "browser_cache_store",
            "browser_family": "chromium",
            "browser_cache_format": "blockfile",
            "browser_cache_parser": CHROME_CACHE_PARSER_NAME,
            "browser_cache_parser_status": "parsed",
            "browser_cache_parser_scope": chrome_cache_parser_scope_text(),
            "browser_cache_deleted_recovery": "not attempted",
            "browser_cache_body_decompression": "not attempted",
            "source_artifact": "Chrome Cache",
            "source_artifact_path": self.source_path.as_str(),
        });
        add_entry_category(
            &mut metadata,
            &self.root_logical_path,
            &self.cache_display_name,
            "directory",
        );
        self.entries.push(ChromeCacheImportEntry {
            logical_path: self.root_logical_path.clone(),
            display_name: self.cache_display_name.clone(),
            entry_kind: "directory",
            size_bytes: None,
            metadata,
            content_head: None,
        });
        Ok(())
    }

    fn push_cache_entry(&mut self, parsed: ChromeCacheParsedEntry) -> Result<()> {
        if self.should_stop_before_push() {
            return Ok(());
        }
        let key = parsed.cache_key.trim();
        let url = (!key.is_empty()).then(|| key.to_string());
        let host = url
            .as_deref()
            .map(host_from_url)
            .unwrap_or_else(|| "unknown-host".to_string());
        let display_name = url
            .as_deref()
            .filter(|value| !value.trim().is_empty())
            .unwrap_or("Chrome cache entry")
            .chars()
            .take(180)
            .collect::<String>();
        let hash_hex = format!("0x{:08X}", parsed.hash);
        let logical_path = chrome_cache_entry_logical_path(
            &self.root_logical_path,
            &host,
            &hash_hex,
            parsed.entry_index,
            &mut self.used_paths,
        );
        let http = parse_chrome_cache_http_metadata(&parsed.header_bytes);
        let content_type = chrome_cache_header_value(&http.headers, "content-type");
        let last_modified = chrome_cache_header_value(&http.headers, "last-modified");
        let expires = chrome_cache_header_value(&http.headers, "expires");
        let cache_control = chrome_cache_header_value(&http.headers, "cache-control");
        let content_encoding = chrome_cache_header_value(&http.headers, "content-encoding");
        let search_text = format!("{} {}", key, host);
        let mut metadata = serde_json::json!({
            "artifact_kind": "browser_cache_entry",
            "browser_family": "chromium",
            "browser_cache_format": "blockfile",
            "browser_cache_parser": CHROME_CACHE_PARSER_NAME,
            "browser_cache_parser_status": "parsed",
            "browser_cache_parser_scope": chrome_cache_parser_scope_text(),
            "browser_cache_deleted_recovery": "not attempted",
            "browser_cache_body_decompression": "not attempted",
            "cache_key": url.clone(),
            "url": url,
            "host": host,
            "cache_entry_index": parsed.entry_index,
            "cache_entry_hash": hash_hex,
            "cache_entry_state": parsed.state,
            "cache_reuse_count": parsed.reuse_count,
            "cache_refetch_count": parsed.refetch_count,
            "cache_stream_sizes": parsed.stream_sizes,
            "cache_header_stream_size": parsed.stream_sizes[0],
            "cache_body_stream_index": parsed.body_stream_index,
            "cache_body_size_bytes": parsed.body_size,
            "created_utc": parsed.creation_time_utc.clone(),
            "creation_utc": parsed.creation_time_utc,
            "http_status_line": http.status_line,
            "http_status_code": http.status_code,
            "http_headers": http.headers,
            "content_type": content_type,
            "content_encoding": content_encoding,
            "last_modified": last_modified,
            "expires": expires,
            "cache_control": cache_control,
            "source_artifact": "Chrome Cache",
            "source_artifact_path": self.source_path.as_str(),
            "search_text": search_text,
        });
        if !parsed.stream_errors.is_empty() {
            if let Some(object) = metadata.as_object_mut() {
                object.insert(
                    "browser_cache_stream_errors".to_string(),
                    serde_json::json!(parsed.stream_errors),
                );
            }
        }
        add_entry_category(&mut metadata, &logical_path, &display_name, "record");
        self.entries.push(ChromeCacheImportEntry {
            logical_path,
            display_name,
            entry_kind: "record",
            size_bytes: parsed.body_size.and_then(|size| i64::try_from(size).ok()),
            metadata,
            content_head: parsed.body_head,
        });
        self.cache_entries_indexed += 1;
        Ok(())
    }
}

fn parse_chromium_blockfile_cache_entry(
    entry_index: usize,
    lazy_entry: LazyBlockFileCacheEntry,
) -> Result<ChromeCacheParsedEntry> {
    let (cache_key, hash, state, reuse_count, refetch_count, creation_time_utc, stream_sizes) = {
        let entry = lazy_entry.get().context("reading blockfile cache entry")?;
        (
            entry.key.to_string(),
            entry.hash,
            chrome_cache_entry_state_label(entry.state.kind()).to_string(),
            entry.reuse_count,
            entry.refetch_count,
            entry
                .creation_time
                .into_datetime_utc()
                .ok()
                .map(|value| value.to_rfc3339()),
            entry
                .data_size
                .map(|size| usize::try_from(size.max(0)).unwrap_or(0)),
        )
    };
    let stream_readers = lazy_entry
        .stream_readers()
        .context("opening Chrome cache entry streams")?;
    let mut header_bytes = Vec::new();
    let mut body_stream_index = None;
    let mut body_size = None;
    let mut body_head = None;
    let mut stream_errors = Vec::new();
    for (stream_index, reader_result) in stream_readers.into_iter().enumerate() {
        let Some(&stream_size) = stream_sizes.get(stream_index) else {
            continue;
        };
        if stream_size == 0 {
            continue;
        }
        let reader = match reader_result {
            Ok(reader) => reader,
            Err(err) => {
                if stream_errors.len() < CHROME_CACHE_PARSER_ERROR_LIMIT {
                    stream_errors.push(format!("stream {stream_index}: {err}"));
                }
                continue;
            }
        };
        if stream_index == 0 {
            header_bytes = read_chrome_cache_stream_prefix(
                reader,
                stream_size,
                CHROME_CACHE_HEADER_PARSE_BYTES,
            )
            .with_context(|| format!("reading Chrome cache header stream {entry_index}"))?;
        } else if body_stream_index.is_none() {
            let head = read_chrome_cache_stream_prefix(reader, stream_size, CONTENT_INDEX_BYTES)
                .with_context(|| format!("reading Chrome cache body stream {entry_index}"))?;
            body_stream_index = Some(stream_index);
            body_size = Some(stream_size);
            body_head = Some(head);
        }
    }
    Ok(ChromeCacheParsedEntry {
        entry_index,
        cache_key,
        hash,
        state,
        reuse_count,
        refetch_count,
        creation_time_utc,
        stream_sizes,
        header_bytes,
        body_stream_index,
        body_size,
        body_head,
        stream_errors,
    })
}

fn read_chrome_cache_stream_prefix(
    reader: Box<dyn Read>,
    stream_size: usize,
    limit: usize,
) -> Result<Vec<u8>> {
    let mut bytes = Vec::new();
    reader
        .take(stream_size.min(limit) as u64)
        .read_to_end(&mut bytes)
        .context("reading Chrome cache stream")?;
    Ok(bytes)
}

fn read_chrome_cache_entry_body_bytes(
    entry: &EntryForBytes,
    offset: u64,
    length: usize,
) -> Result<Option<EntryBytes>> {
    if entry.metadata_json["artifact_kind"].as_str() != Some("browser_cache_entry")
        || entry.metadata_json["browser_cache_format"].as_str() != Some("blockfile")
    {
        return Ok(None);
    }
    let Some(entry_index) = entry.metadata_json["cache_entry_index"].as_u64() else {
        return Ok(None);
    };
    let Some(stream_index) = entry.metadata_json["cache_body_stream_index"].as_u64() else {
        return Ok(None);
    };
    let cache_path = Path::new(&entry.source_path);
    let cache = ChromeCache::from_path(cache_path.to_path_buf()).with_context(|| {
        format!(
            "opening Chrome blockfile cache for body read {}",
            cache_path.display()
        )
    })?;
    let mut entries = cache
        .entries()
        .with_context(|| format!("reading Chrome cache index {}", cache_path.display()))?;
    let lazy_entry = entries
        .nth(usize::try_from(entry_index).context("cache entry index exceeds usize")?)
        .with_context(|| format!("Chrome cache entry {entry_index} is no longer available"))?;
    let stream_readers = lazy_entry
        .stream_readers()
        .context("opening Chrome cache entry streams")?;
    let reader = stream_readers
        .into_iter()
        .nth(usize::try_from(stream_index).context("cache stream index exceeds usize")?)
        .with_context(|| format!("Chrome cache stream {stream_index} is not available"))?
        .context("opening Chrome cache body stream")?;
    let total_size = entry
        .metadata_json
        .get("cache_body_size_bytes")
        .and_then(|value| value.as_u64())
        .or_else(|| entry.size_bytes.and_then(|value| u64::try_from(value).ok()))
        .unwrap_or(0);
    let bytes = read_from_chrome_cache_stream(reader, offset, length, total_size)?;
    let bytes_read = bytes.len();
    Ok(Some(EntryBytes {
        entry_id: entry.entry_id,
        evidence_id: entry.evidence_id,
        logical_path: entry.logical_path.clone(),
        offset,
        requested_length: length,
        bytes_read,
        total_size,
        eof: offset.saturating_add(bytes_read as u64) >= total_size,
        bytes,
    }))
}

fn read_from_chrome_cache_stream(
    mut reader: Box<dyn Read>,
    offset: u64,
    length: usize,
    total_size: u64,
) -> Result<Vec<u8>> {
    let mut remaining_skip = offset.min(total_size);
    let mut skip_buffer = [0_u8; 8192];
    while remaining_skip > 0 {
        let want = usize::try_from(remaining_skip)
            .unwrap_or(usize::MAX)
            .min(skip_buffer.len());
        let read = reader
            .read(&mut skip_buffer[..want])
            .context("skipping Chrome cache body bytes")?;
        if read == 0 {
            return Ok(Vec::new());
        }
        remaining_skip = remaining_skip.saturating_sub(read as u64);
    }
    let remaining = total_size.saturating_sub(offset.min(total_size));
    let want = usize::try_from(remaining).unwrap_or(usize::MAX).min(length);
    let mut bytes = Vec::new();
    reader
        .take(want as u64)
        .read_to_end(&mut bytes)
        .context("reading Chrome cache body bytes")?;
    Ok(bytes)
}

fn parse_chrome_cache_http_metadata(header_bytes: &[u8]) -> ChromeCacheHttpMetadata {
    let mut metadata = ChromeCacheHttpMetadata::default();
    if header_bytes.is_empty() {
        return metadata;
    }
    let text = String::from_utf8_lossy(header_bytes);
    let start = text.find("HTTP/").unwrap_or(0);
    let normalized = text[start..].replace(['\0', '\r'], "\n");
    let mut saw_status = false;
    for raw_line in normalized.lines() {
        let line = raw_line.trim_matches(|ch: char| ch.is_control()).trim();
        if line.is_empty() {
            if saw_status {
                break;
            }
            continue;
        }
        if line.starts_with("HTTP/") {
            metadata.status_line = Some(line.chars().take(240).collect());
            metadata.status_code = line
                .split_whitespace()
                .nth(1)
                .and_then(|value| value.parse::<i64>().ok());
            saw_status = true;
            continue;
        }
        let Some((key, value)) = line.split_once(':') else {
            continue;
        };
        let key = key.trim();
        if !is_http_header_name(key) {
            continue;
        }
        let value = normalize_email_header_value(value);
        if value.is_empty() {
            continue;
        }
        metadata
            .headers
            .entry(key.to_ascii_lowercase())
            .and_modify(|existing| {
                existing.push_str("; ");
                existing.push_str(&value);
            })
            .or_insert(value);
    }
    metadata
}

fn is_http_header_name(value: &str) -> bool {
    !value.is_empty()
        && value
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || byte == b'-')
}

fn chrome_cache_header_value(headers: &BTreeMap<String, String>, key: &str) -> Option<String> {
    headers
        .get(&key.to_ascii_lowercase())
        .map(|value| normalize_email_header_value(value))
        .filter(|value| !value.is_empty())
}

fn chrome_cache_entry_state_label(state: BlockCacheEntryState) -> &'static str {
    match state {
        BlockCacheEntryState::Normal => "normal",
        BlockCacheEntryState::Evicted => "evicted",
        BlockCacheEntryState::Doomed => "doomed",
        BlockCacheEntryState::Unknown => "unknown",
    }
}

fn chrome_cache_root_logical_path(display_name: &str) -> String {
    format!("/Browser Cache/{}", sanitize_logical_segment(display_name))
}

fn chrome_cache_entry_logical_path(
    root_logical_path: &str,
    host: &str,
    hash_hex: &str,
    entry_index: usize,
    used_paths: &mut HashSet<String>,
) -> String {
    let host = sanitize_logical_segment(host);
    let hash = sanitize_logical_segment(hash_hex);
    let mut logical_path = format!("{root_logical_path}/{host}/{entry_index:08}-{hash}.record");
    if used_paths.insert(logical_path.clone()) {
        return logical_path;
    }
    let mut suffix = 1_usize;
    loop {
        logical_path =
            format!("{root_logical_path}/{host}/{entry_index:08}-{hash}-{suffix}.record");
        if used_paths.insert(logical_path.clone()) {
            return logical_path;
        }
        suffix = suffix.saturating_add(1);
    }
}

fn chrome_cache_parser_scope_text() -> &'static str {
    "Chromium blockfile HTTP disk cache only: index plus data_N files parsed as one folder-level evidence unit when the evidence path is the Cache directory itself; Simple Cache, Code Cache, GPUCache, deleted/evicted recovery, full body decompression, and long out-of-band cache keys are deferred"
}

fn process_file_evidence(
    conn: &Connection,
    case_id: i64,
    evidence: &EvidenceForProcessing,
    job_id: i64,
    max_entries: usize,
) -> Result<(usize, bool)> {
    let path = PathBuf::from(&evidence.source_path);
    let metadata = fs::metadata(&path)
        .with_context(|| format!("reading file evidence metadata {}", path.display()))?;
    if !metadata.is_file() {
        bail!("file evidence path is no longer a file: {}", path.display());
    }
    if is_standalone_mft_evidence_candidate(&path, &evidence.display_name) {
        return process_standalone_mft_evidence(conn, case_id, evidence, job_id, max_entries);
    }
    if is_registry_hive_evidence_candidate(&path, &evidence.display_name) {
        return process_registry_hive_evidence(conn, case_id, evidence, job_id, max_entries);
    }
    if is_evtx_evidence_candidate(&path, &evidence.display_name) {
        return process_evtx_event_log_evidence(conn, case_id, evidence, job_id, max_entries);
    }
    if extension_lower(&evidence.display_name)
        .or_else(|| extension_lower(path.to_string_lossy().as_ref()))
        .as_deref()
        .is_some_and(is_pff_store_extension)
    {
        return process_pst_mailbox_evidence(conn, case_id, evidence, job_id, max_entries);
    }
    let logical_path = format!("/{}", evidence.display_name);
    let mut metadata_value = serde_json::json!({
        "local_relative_path": evidence.display_name,
        "source_path_exact": evidence.display_name,
    });
    let truncated = annotate_email_metadata_for_path(
        &mut metadata_value,
        &path,
        &logical_path,
        &evidence.display_name,
        metadata.len(),
    );
    add_entry_category(
        &mut metadata_value,
        &logical_path,
        &evidence.display_name,
        "file",
    );
    let content_head = local_file_content_head(&path, &metadata_value, "file");
    upsert_filesystem_entry_with_content(
        conn,
        case_id,
        evidence.id,
        &logical_path,
        &evidence.display_name,
        "file",
        Some(i64::try_from(metadata.len()).context("file size exceeds i64")?),
        &metadata_value.to_string(),
        job_id,
        content_head.as_deref(),
    )?;
    Ok((1, truncated))
}

fn process_standalone_mft_evidence(
    conn: &Connection,
    case_id: i64,
    evidence: &EvidenceForProcessing,
    job_id: i64,
    max_entries: usize,
) -> Result<(usize, bool)> {
    let path = PathBuf::from(&evidence.source_path);
    let mut parser = mft::MftParser::from_path(&path)
        .with_context(|| format!("opening standalone MFT {}", path.display()))?;
    let record_count = parser.get_entry_count();
    let limit = record_count.min(max_entries as u64);
    let mut indexed = 0_usize;
    let mut omitted_records = 0_u64;
    let mut partially_parsed_records = 0_u64;
    progress::progress_set_unit("MFT records");
    progress::progress_set_total(Some(record_count));
    for record_number in 0..limit {
        let current_object = format!("$MFT record {record_number}");
        progress::progress_current(current_object.clone());
        let entry = match parser.get_entry(record_number) {
            Ok(entry) => entry,
            Err(error) => {
                omitted_records = omitted_records.saturating_add(1);
                progress::progress_error(Some(current_object.clone()));
                progress::progress_skip(Some(current_object.clone()));
                progress::progress_advance(current_object);
                if omitted_records <= 16 {
                    eprintln!(
                        "standalone MFT record {record_number} could not be parsed and was omitted: {error}"
                    );
                }
                continue;
            }
        };
        if !entry.header.is_valid() {
            progress::progress_skip(Some(current_object.clone()));
            progress::progress_advance(current_object);
            continue;
        }
        let in_use = entry.is_allocated();
        let is_directory = entry.is_dir();
        let sequence_number = entry.header.sequence;
        let best_name = entry.find_best_name_attribute();
        let name = best_name
            .as_ref()
            .map(|attr| attr.name.clone())
            .unwrap_or_else(|| format!("MFT record {record_number}"));
        let entry_kind = if is_directory { "directory" } else { "file" };
        let mut record_partial = false;
        let (reconstructed, path_reconstruction_error) =
            match parser.get_full_path_for_entry(&entry) {
                Ok(path) => (path, None),
                Err(error) => {
                    record_partial = true;
                    progress::progress_error(Some(current_object.clone()));
                    (None, Some(error.to_string()))
                }
            };
        let parent_status = if let Some(file_name) = best_name.as_ref() {
            match parser.get_entry(file_name.parent.entry) {
                Ok(parent) if parent.header.sequence == file_name.parent.sequence => "resolved",
                Ok(_) => "parent sequence mismatch",
                Err(_) => "missing parent",
            }
        } else {
            "missing file name"
        };
        let reconstructed_text = reconstructed
            .as_ref()
            .map(|value| value.to_string_lossy().replace('\\', "/"));
        let path_reconstruction_status = if path_reconstruction_error.is_some() {
            "path parser error"
        } else {
            parent_status
        };
        let logical_path = reconstructed_text
            .as_ref()
            .filter(|value| !value.is_empty() && parent_status == "resolved")
            .map(|value| {
                format!(
                    "/Reconstructed filesystem/{}",
                    value.trim_start_matches('/')
                )
            })
            .unwrap_or_else(|| {
                format!(
                    "/{}/{}-{}",
                    if in_use {
                        "Orphaned records"
                    } else {
                        "Deleted records"
                    },
                    record_number,
                    sanitize_logical_segment(&name)
                )
            });
        let mut attributes = Vec::new();
        let mut attribute_parse_error_count = 0_usize;
        let mut attribute_parse_errors = Vec::new();
        for attribute in entry.iter_attributes() {
            match attribute {
                Ok(attribute) => attributes.push(attribute),
                Err(error) => {
                    attribute_parse_error_count = attribute_parse_error_count.saturating_add(1);
                    if attribute_parse_errors.len() < 8 {
                        attribute_parse_errors.push(error.to_string());
                    }
                }
            }
        }
        if attribute_parse_error_count > 0 {
            record_partial = true;
            progress::progress_error(Some(current_object.clone()));
        }
        let standard = attributes
            .iter()
            .find_map(|attribute| attribute.data.clone().into_standard_info());
        let data_attributes = attributes
            .iter()
            .filter(|attribute| {
                attribute.header.type_code == mft::attribute::MftAttributeType::DATA
            })
            .collect::<Vec<_>>();
        let default_data = data_attributes
            .iter()
            .find(|attribute| attribute.header.name.is_empty());
        let (data_size, allocated_size, data_resident) = default_data
            .map(|attribute| match &attribute.header.residential_header {
                mft::attribute::header::ResidentialHeader::Resident(header) => (
                    u64::from(header.data_size),
                    u64::from(header.data_size),
                    true,
                ),
                mft::attribute::header::ResidentialHeader::NonResident(header) => {
                    (header.file_size, header.allocated_length, false)
                }
            })
            .unwrap_or((
                best_name.as_ref().map(|v| v.logical_size).unwrap_or(0),
                best_name.as_ref().map(|v| v.physical_size).unwrap_or(0),
                false,
            ));
        let alternate_data_streams = data_attributes
            .iter()
            .filter(|attribute| !attribute.header.name.is_empty())
            .map(|attribute| serde_json::json!({
                "name": attribute.header.name,
                "resident": matches!(attribute.header.residential_header, mft::attribute::header::ResidentialHeader::Resident(_)),
            }))
            .collect::<Vec<_>>();
        let record_size = u64::from(entry.header.total_entry_size);
        let metadata = serde_json::json!({
            "artifact_kind": if in_use { "ntfs_mft_record" } else { "deleted_file_record" },
            "filesystem_parser": "mft crate 0.7.0",
            "virtual_filesystem": "standalone_mft_reconstruction",
            "source_path_exact": evidence.display_name,
            "ntfs_file_record_number": record_number,
            "ntfs_parent_record_number": best_name.as_ref().map(|v| v.parent.entry),
            "ntfs_parent_sequence_number": best_name.as_ref().map(|v| v.parent.sequence),
            "ntfs_sequence_number": sequence_number,
            "ntfs_hard_link_count": entry.header.hard_link_count,
            "mft_record_logical_offset": record_number * record_size,
            "mft_record_physical_offset": record_number * record_size,
            "mft_record_size": record_size,
            "mft_fixup_valid": entry.valid_fixup,
            "mft_path_reconstruction_status": path_reconstruction_status,
            "mft_reconstructed_path": reconstructed_text,
            "mft_path_reconstruction_error": path_reconstruction_error,
            "mft_attribute_parse_error_count": attribute_parse_error_count,
            "mft_attribute_parse_errors": attribute_parse_errors,
            "mft_attribute_parse_errors_omitted": attribute_parse_error_count.saturating_sub(8),
            "ntfs_allocated_size": allocated_size,
            "ntfs_data_size": data_size,
            "ntfs_default_data_resident": data_resident,
            "ntfs_alternate_data_streams": alternate_data_streams,
            "ntfs_standard_creation_time_utc": standard.as_ref().map(|v| v.created.to_string()),
            "ntfs_standard_modification_time_utc": standard.as_ref().map(|v| v.modified.to_string()),
            "ntfs_standard_mft_record_modification_time_utc": standard.as_ref().map(|v| v.mft_modified.to_string()),
            "ntfs_standard_access_time_utc": standard.as_ref().map(|v| v.accessed.to_string()),
            "ntfs_creation_time_utc": best_name.as_ref().map(|v| v.created.to_string()),
            "ntfs_modification_time_utc": best_name.as_ref().map(|v| v.modified.to_string()),
            "ntfs_mft_record_modification_time_utc": best_name.as_ref().map(|v| v.mft_modified.to_string()),
            "ntfs_access_time_utc": best_name.as_ref().map(|v| v.accessed.to_string()),
            "ntfs_filename_namespace": best_name.as_ref().map(|v| format!("{:?}", v.namespace)),
            "recovery_source": if in_use { serde_json::Value::Null } else { serde_json::json!("standalone_ntfs_mft") },
        });
        let size = (!is_directory).then(|| i64::try_from(data_size).unwrap_or(i64::MAX));
        if in_use {
            upsert_filesystem_entry(
                conn,
                case_id,
                evidence.id,
                &logical_path,
                &name,
                entry_kind,
                size,
                &metadata.to_string(),
                job_id,
            )?;
        } else {
            upsert_deleted_filesystem_entry_with_content(
                conn,
                case_id,
                evidence.id,
                &logical_path,
                &name,
                entry_kind,
                size,
                &metadata.to_string(),
                job_id,
                None,
            )?;
        }
        indexed += 1;
        if record_partial {
            partially_parsed_records = partially_parsed_records.saturating_add(1);
        }
    }
    if record_count > limit {
        progress::progress_truncated(format!(
            "standalone MFT processing stopped at examiner-requested record limit {limit} of {record_count}"
        ));
    }
    if partially_parsed_records > 0 {
        progress::progress_truncated(format!(
            "{partially_parsed_records} standalone MFT record(s) had parser or path/attribute omissions"
        ));
    }
    if omitted_records > 0 {
        progress::progress_truncated(format!(
            "{omitted_records} standalone MFT record(s) could not be parsed and were omitted; {} individual console diagnostic(s) omitted",
            omitted_records.saturating_sub(16)
        ));
    }
    Ok((
        indexed,
        record_count > limit || partially_parsed_records > 0 || omitted_records > 0,
    ))
}

fn process_folder_evidence(
    conn: &Connection,
    case_id: i64,
    evidence: &EvidenceForProcessing,
    job_id: i64,
    max_entries: usize,
) -> Result<(usize, bool)> {
    let root = PathBuf::from(&evidence.source_path);
    if !root.is_dir() {
        bail!(
            "folder evidence path is no longer a directory: {}",
            root.display()
        );
    }
    if has_chromium_blockfile_cache_layout(&root) {
        return process_chromium_blockfile_cache_evidence(
            conn,
            case_id,
            evidence,
            job_id,
            max_entries,
        );
    }

    let mut indexed = 0_usize;
    let mut truncated = false;
    let mut stack = vec![root.clone()];
    while let Some(folder) = stack.pop() {
        let mut children = fs::read_dir(&folder)
            .with_context(|| format!("reading evidence folder {}", folder.display()))?
            .collect::<std::result::Result<Vec<_>, _>>()
            .with_context(|| format!("listing evidence folder {}", folder.display()))?;
        children.sort_by_key(|entry| entry.path());

        for child in children {
            if indexed >= max_entries {
                return Ok((indexed, true));
            }
            let child_path = child.path();
            let metadata = fs::symlink_metadata(&child_path).with_context(|| {
                format!("reading evidence entry metadata {}", child_path.display())
            })?;
            let relative = child_path
                .strip_prefix(&root)
                .with_context(|| format!("building logical path for {}", child_path.display()))?;
            let logical_path = logical_path_from_relative(relative);
            let name = child_path
                .file_name()
                .and_then(|value| value.to_str())
                .unwrap_or("")
                .to_string();
            let file_type = metadata.file_type();
            let (entry_kind, size_bytes, mut metadata_value, descend) = if file_type.is_symlink() {
                (
                    "symlink",
                    None,
                    serde_json::json!({ "symlink": true }),
                    false,
                )
            } else if file_type.is_dir() {
                ("directory", None, serde_json::json!({}), true)
            } else if file_type.is_file() {
                (
                    "file",
                    Some(i64::try_from(metadata.len()).context("file size exceeds i64")?),
                    serde_json::json!({}),
                    false,
                )
            } else {
                ("other", None, serde_json::json!({}), false)
            };
            if file_type.is_file() {
                truncated |= annotate_email_metadata_for_path(
                    &mut metadata_value,
                    &child_path,
                    &logical_path,
                    &name,
                    metadata.len(),
                );
            }
            if let Some(object) = metadata_value.as_object_mut() {
                let exact_relative = logical_path.trim_start_matches('/').to_string();
                object.insert(
                    "local_relative_path".to_string(),
                    serde_json::json!(exact_relative),
                );
                object.insert(
                    "source_path_exact".to_string(),
                    serde_json::json!(exact_relative),
                );
                object.insert(
                    "created_utc".to_string(),
                    optional_system_time_json(metadata.created().ok()),
                );
                object.insert(
                    "modified_utc".to_string(),
                    optional_system_time_json(metadata.modified().ok()),
                );
                object.insert(
                    "accessed_utc".to_string(),
                    optional_system_time_json(metadata.accessed().ok()),
                );
            }
            add_entry_category(&mut metadata_value, &logical_path, &name, entry_kind);
            let content_head = local_file_content_head(&child_path, &metadata_value, entry_kind);

            upsert_filesystem_entry_with_content(
                conn,
                case_id,
                evidence.id,
                &logical_path,
                &name,
                entry_kind,
                size_bytes,
                &metadata_value.to_string(),
                job_id,
                content_head.as_deref(),
            )?;
            indexed += 1;
            if descend {
                stack.push(child_path);
            }
        }
    }

    Ok((indexed, truncated))
}

fn process_image_evidence(
    conn: &Connection,
    case_id: i64,
    evidence: &EvidenceForProcessing,
    job_id: i64,
    max_entries: usize,
) -> Result<(usize, bool)> {
    let path = PathBuf::from(&evidence.source_path);
    progress::progress_current(evidence.source_path.clone());
    if !path.is_file() {
        bail!(
            "image evidence path is no longer a file: {}",
            path.display()
        );
    }

    let mut opened = open_disk_image(&path)?;
    let source_metadata = fs::metadata(&path)
        .with_context(|| format!("reading image evidence metadata {}", path.display()))?;
    let source_info = source_artifact_metadata(&path, "Disk Image");
    let mut indexed = 0_usize;
    let mut truncated = false;

    conn.execute(
        "DELETE FROM filesystem_entries WHERE case_id = ?1 AND evidence_id = ?2",
        params![case_id, evidence.id],
    )?;

    let mut container_metadata = serde_json::json!({
        "artifact_kind": "disk_image_container",
        "container_format": opened.format,
        "decoded_size_bytes": opened.decoded_size,
        "source_size_bytes": source_metadata.len(),
        "source_path": evidence.source_path,
        "parser": "disk-forensic",
        "supported_formats": ["e01", "vmdk", "vhdx", "vhd", "vdi", "raw", "dd", "img"],
        "filesystem_browsing_status": "partition discovery only; filesystem parsers are pending",
    });
    merge_json_object(&mut container_metadata, &source_info);
    insert_image_record(
        conn,
        case_id,
        evidence.id,
        "/Image Analysis/Container.record",
        "Container",
        Some(i64::try_from(opened.decoded_size).unwrap_or(i64::MAX)),
        &container_metadata,
        job_id,
    )?;
    indexed += 1;
    if indexed >= max_entries {
        return Ok((indexed, true));
    }

    match disk_forensic::analyse_disk(&mut opened.reader, opened.decoded_size) {
        Ok(report) => {
            let scheme = format!("{:?}", report.scheme());
            let layout = disk_forensic::layout::from_report(
                &report,
                &evidence.display_name,
                opened.decoded_size,
            );
            let text_report = disk_forensic::report::text_report(&report);
            let report_metadata = serde_json::json!({
                "artifact_kind": "disk_partition_report",
                "container_format": opened.format,
                "partition_scheme": scheme,
                "decoded_size_bytes": opened.decoded_size,
                "logical_sector_size": layout.logical_sector_size,
                "physical_sector_size": layout.physical_sector_size,
                "partition_count": layout.partitions.len(),
                "has_anomalies": report.has_anomalies(),
                "container_finding_count": opened.container_finding_count,
                "text_report": text_report,
            });
            insert_image_record(
                conn,
                case_id,
                evidence.id,
                "/Image Analysis/Partitioning.report",
                "Partitioning",
                None,
                &report_metadata,
                job_id,
            )?;
            indexed += 1;
            if indexed >= max_entries {
                return Ok((indexed, true));
            }

            for (index, partition) in layout.partitions.iter().enumerate() {
                if indexed >= max_entries {
                    truncated = true;
                    break;
                }
                let name = partition
                    .label
                    .as_deref()
                    .filter(|value| !value.trim().is_empty())
                    .unwrap_or(&partition.name);
                let logical_path = format!(
                    "/Image Analysis/Partitions/{:03}-{}.record",
                    index + 1,
                    sanitize_logical_segment(name)
                );
                let volume_prefix = format!(
                    "/Image Analysis/Volumes/{:03}-{}",
                    index + 1,
                    sanitize_logical_segment(name)
                );
                progress::progress_set_volume(Some(format!("Partition {}: {}", index + 1, name)));
                progress::progress_current(logical_path.clone());
                let detected_filesystem =
                    detect_volume_filesystem_at(&mut *opened.reader, partition.start_offset)?;
                let bitlocker_locked = detected_filesystem == Some(BITLOCKER_LOCKED_FILESYSTEM);
                let bitlocker_inspection = if bitlocker_locked {
                    bitlocker_inspection_at(
                        &mut *opened.reader,
                        partition.start_offset,
                        Some(partition.size_bytes),
                    )?
                } else {
                    None
                };
                let filesystem_metadata = if bitlocker_locked {
                    Some(BITLOCKER_LOCKED_FILESYSTEM)
                } else {
                    partition.filesystem.as_deref()
                };
                let can_parse_fat = !bitlocker_locked
                    && (detected_filesystem == Some("FAT")
                        || is_supported_fat_partition(
                            partition.partition_type.as_deref(),
                            partition.filesystem.as_deref(),
                        ));
                let can_parse_ntfs = !bitlocker_locked
                    && (detected_filesystem == Some("NTFS")
                        || is_supported_ntfs_partition(
                            partition.partition_type.as_deref(),
                            partition.filesystem.as_deref(),
                        ));
                let can_parse_ext = !bitlocker_locked && detected_filesystem == Some("EXT");
                let filesystem_parser = if bitlocker_locked {
                    "locked"
                } else if can_parse_fat {
                    "fatfs"
                } else if can_parse_ntfs {
                    "ntfs"
                } else if can_parse_ext {
                    "ext4"
                } else {
                    "pending"
                };
                let filesystem_browsing_status = if bitlocker_locked {
                    bitlocker_status_message(bitlocker_inspection.as_ref())
                } else if can_parse_fat {
                    "FAT parser attempted; parsed entries appear under /Image Analysis/Volumes"
                } else if can_parse_ntfs {
                    "NTFS parser attempted; parsed entries appear under /Image Analysis/Volumes"
                } else if can_parse_ext {
                    "ext parser attempted; parsed entries appear under /Image Analysis/Volumes"
                } else {
                    "pending filesystem parser"
                };
                let volume_entry_prefix = if can_parse_fat || can_parse_ntfs || can_parse_ext {
                    Some(volume_prefix.as_str())
                } else {
                    None
                };
                let mut metadata = serde_json::json!({
                    "artifact_kind": "disk_partition",
                    "container_format": opened.format,
                    "partition_scheme": scheme,
                    "index": index + 1,
                    "name": partition.name,
                    "label": partition.label,
                    "partition_type": partition.partition_type,
                    "partition_reported_filesystem": partition.filesystem,
                    "filesystem": filesystem_metadata,
                    "detected_filesystem": detected_filesystem,
                    "start_offset": partition.start_offset,
                    "size_bytes": partition.size_bytes,
                    "end_offset_exclusive": partition.start_offset.saturating_add(partition.size_bytes),
                    "logical_sector_size": layout.logical_sector_size,
                    "physical_sector_size": layout.physical_sector_size,
                    "filesystem_parser": filesystem_parser,
                    "filesystem_browsing_status": filesystem_browsing_status,
                    "volume_entry_prefix": volume_entry_prefix,
                });
                if bitlocker_locked {
                    merge_json_object(
                        &mut metadata,
                        &bitlocker_metadata_value(bitlocker_inspection.as_ref()),
                    );
                }
                insert_image_record(
                    conn,
                    case_id,
                    evidence.id,
                    &logical_path,
                    name,
                    Some(i64::try_from(partition.size_bytes).unwrap_or(i64::MAX)),
                    &metadata,
                    job_id,
                )?;
                indexed += 1;
                if can_parse_fat && indexed < max_entries {
                    match process_fat_partition_entries(
                        conn,
                        case_id,
                        evidence.id,
                        job_id,
                        &mut *opened.reader,
                        partition.start_offset,
                        partition.size_bytes,
                        &volume_prefix,
                        name,
                        index + 1,
                        &mut indexed,
                        max_entries,
                    ) {
                        Ok(fat_truncated) => truncated |= fat_truncated,
                        Err(err) => {
                            if indexed >= max_entries {
                                truncated = true;
                            } else {
                                let signature_confirmed = detected_filesystem == Some("FAT");
                                let reason = format!(
                                    "FAT parser stopped on partition {} before completing the volume: {err}",
                                    index + 1
                                );
                                progress::progress_error(Some(volume_prefix.clone()));
                                progress::progress_skip(Some(volume_prefix.clone()));
                                if signature_confirmed {
                                    progress::progress_truncated(reason.clone());
                                    truncated = true;
                                }
                                insert_image_record(
                                    conn,
                                    case_id,
                                    evidence.id,
                                    &format!("{volume_prefix}/Parser Error.record"),
                                    "Parser Error",
                                    None,
                                    &serde_json::json!({
                                        "artifact_kind": "filesystem_parser_error",
                                        "filesystem_parser": "fatfs",
                                        "partition_index": index + 1,
                                        "error": err.to_string(),
                                        "signature_confirmed": signature_confirmed,
                                        "probe_only": !signature_confirmed,
                                    }),
                                    job_id,
                                )?;
                                indexed += 1;
                            }
                        }
                    }
                } else if can_parse_ntfs && indexed < max_entries {
                    match process_ntfs_partition_entries(
                        conn,
                        case_id,
                        evidence.id,
                        job_id,
                        &mut *opened.reader,
                        partition.start_offset,
                        partition.size_bytes,
                        &volume_prefix,
                        name,
                        index + 1,
                        &mut indexed,
                        max_entries,
                    ) {
                        Ok(ntfs_truncated) => truncated |= ntfs_truncated,
                        Err(err) => {
                            if indexed >= max_entries {
                                truncated = true;
                            } else {
                                let signature_confirmed = detected_filesystem == Some("NTFS");
                                let reason = format!(
                                    "NTFS parser stopped on partition {} before completing the volume: {err}",
                                    index + 1
                                );
                                progress::progress_error(Some(volume_prefix.clone()));
                                progress::progress_skip(Some(volume_prefix.clone()));
                                if signature_confirmed {
                                    progress::progress_truncated(reason.clone());
                                    truncated = true;
                                }
                                insert_image_record(
                                    conn,
                                    case_id,
                                    evidence.id,
                                    &format!("{volume_prefix}/Parser Error.record"),
                                    "Parser Error",
                                    None,
                                    &serde_json::json!({
                                        "artifact_kind": "filesystem_parser_error",
                                        "filesystem_parser": "ntfs",
                                        "partition_index": index + 1,
                                        "error": err.to_string(),
                                        "signature_confirmed": signature_confirmed,
                                        "probe_only": !signature_confirmed,
                                    }),
                                    job_id,
                                )?;
                                indexed += 1;
                            }
                        }
                    }
                } else if can_parse_ext && indexed < max_entries {
                    match process_ext_partition_entries(
                        conn,
                        case_id,
                        evidence.id,
                        job_id,
                        &evidence.source_path,
                        partition.start_offset,
                        partition.size_bytes,
                        &volume_prefix,
                        name,
                        index + 1,
                        &mut indexed,
                        max_entries,
                    ) {
                        Ok(ext_truncated) => truncated |= ext_truncated,
                        Err(err) => {
                            if indexed >= max_entries {
                                truncated = true;
                            } else {
                                let signature_confirmed = detected_filesystem == Some("EXT");
                                let reason = format!(
                                    "ext parser stopped on partition {} before completing the volume: {err}",
                                    index + 1
                                );
                                progress::progress_error(Some(volume_prefix.clone()));
                                progress::progress_skip(Some(volume_prefix.clone()));
                                if signature_confirmed {
                                    progress::progress_truncated(reason.clone());
                                    truncated = true;
                                }
                                insert_image_record(
                                    conn,
                                    case_id,
                                    evidence.id,
                                    &format!("{volume_prefix}/Parser Error.record"),
                                    "Parser Error",
                                    None,
                                    &serde_json::json!({
                                        "artifact_kind": "filesystem_parser_error",
                                        "filesystem_parser": "ext4",
                                        "partition_index": index + 1,
                                        "error": err.to_string(),
                                        "signature_confirmed": signature_confirmed,
                                        "probe_only": !signature_confirmed,
                                    }),
                                    job_id,
                                )?;
                                indexed += 1;
                            }
                        }
                    }
                } else if (can_parse_fat || can_parse_ntfs || can_parse_ext)
                    && indexed >= max_entries
                {
                    truncated = true;
                } else if !can_parse_fat
                    && !can_parse_ntfs
                    && !can_parse_ext
                    && indexed < max_entries
                {
                    // btrfs is not yet browsable; if its superblock is present,
                    // record the volume with parsed metadata (pending walk).
                    if let Some(info) =
                        read_btrfs_superblock(&mut *opened.reader, partition.start_offset)?
                    {
                        record_btrfs_volume(
                            conn,
                            case_id,
                            evidence.id,
                            job_id,
                            partition.start_offset,
                            partition.size_bytes,
                            &volume_prefix,
                            name,
                            index + 1,
                            &info,
                            &mut indexed,
                        )?;
                    }
                }
            }

            let mut whole_volume_recognized = false;
            if layout.partitions.is_empty() && indexed < max_entries {
                let whole_volume = process_whole_volume_fallback(
                    conn,
                    case_id,
                    evidence.id,
                    job_id,
                    &mut *opened.reader,
                    &evidence.source_path,
                    opened.decoded_size,
                    &opened.format,
                    Some(&scheme),
                    &mut indexed,
                    max_entries,
                )?;
                truncated |= whole_volume.truncated;
                whole_volume_recognized = whole_volume.recognized;
            }

            // A partitionless image with a valid filesystem at byte zero is a
            // whole-volume acquisition, not one giant unpartitioned gap. The
            // fallback has already walked it, so scanning every sector inside
            // that NTFS/FAT/ext/btrfs volume would only rediscover signatures
            // embedded in ordinary file data as false lost partitions.
            if indexed < max_entries && (!layout.partitions.is_empty() || !whole_volume_recognized)
            {
                let declared: Vec<(u64, u64)> = layout
                    .partitions
                    .iter()
                    .map(|partition| (partition.start_offset, partition.size_bytes))
                    .collect();
                // The whole-image fallback already probed offset 0.
                let skip: &[u64] = if declared.is_empty() { &[0] } else { &[] };
                truncated |= scan_lost_partitions(
                    conn,
                    case_id,
                    evidence.id,
                    job_id,
                    &mut *opened.reader,
                    &evidence.source_path,
                    opened.decoded_size,
                    &declared,
                    skip,
                    declared.len(),
                    &mut indexed,
                    max_entries,
                )?;
            }
        }
        Err(err) => {
            let metadata = serde_json::json!({
                "artifact_kind": "disk_partition_report",
                "container_format": opened.format,
                "decoded_size_bytes": opened.decoded_size,
                "status": "partition scheme not recognized",
                "error": err.to_string(),
            });
            insert_image_record(
                conn,
                case_id,
                evidence.id,
                "/Image Analysis/Partitioning.report",
                "Partitioning",
                None,
                &metadata,
                job_id,
            )?;
            indexed += 1;
            let mut whole_volume_recognized = false;
            if indexed < max_entries {
                let whole_volume = process_whole_volume_fallback(
                    conn,
                    case_id,
                    evidence.id,
                    job_id,
                    &mut *opened.reader,
                    &evidence.source_path,
                    opened.decoded_size,
                    &opened.format,
                    None,
                    &mut indexed,
                    max_entries,
                )?;
                truncated |= whole_volume.truncated;
                whole_volume_recognized = whole_volume.recognized;
            } else {
                truncated = true;
            }
            if indexed < max_entries && !whole_volume_recognized {
                // No partition table at all (e.g. wiped/zeroed sector 0):
                // sweep the whole disk for orphaned boot sectors. Offset 0 was
                // already probed by the fallback.
                truncated |= scan_lost_partitions(
                    conn,
                    case_id,
                    evidence.id,
                    job_id,
                    &mut *opened.reader,
                    &evidence.source_path,
                    opened.decoded_size,
                    &[],
                    &[0],
                    0,
                    &mut indexed,
                    max_entries,
                )?;
            }
        }
    }

    Ok((indexed, truncated))
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct WholeVolumeProcessResult {
    truncated: bool,
    recognized: bool,
}

struct OpenedDiskImage {
    format: String,
    decoded_size: u64,
    reader: Box<dyn disk_forensic::container::ReadSeek>,
    container_finding_count: usize,
}

/// A cursor over one immutable EWF decoder shared by concurrent evidence
/// readers. Each worker owns only its cursor position; the potentially large
/// chunk table and bounded decompression cache live once in `EwfReader`.
/// `EwfReader::read_at` is positioned and synchronizes its cache internally.
struct SharedEwfCursor {
    reader: Arc<ewf::EwfReader>,
    position: u64,
}

impl Read for SharedEwfCursor {
    fn read(&mut self, buffer: &mut [u8]) -> io::Result<usize> {
        let read = self
            .reader
            .read_at(buffer, self.position)
            .map_err(io::Error::other)?;
        self.position = self
            .position
            .checked_add(u64::try_from(read).map_err(io::Error::other)?)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "read position overflow"))?;
        Ok(read)
    }
}

impl Seek for SharedEwfCursor {
    fn seek(&mut self, position: SeekFrom) -> io::Result<u64> {
        let next = match position {
            SeekFrom::Start(value) => i128::from(value),
            SeekFrom::End(value) => i128::from(self.reader.total_size()) + i128::from(value),
            SeekFrom::Current(value) => i128::from(self.position) + i128::from(value),
        };
        if !(0..=i128::from(u64::MAX)).contains(&next) {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "seek position is outside the u64 range",
            ));
        }
        self.position = next as u64;
        Ok(self.position)
    }
}

static SHARED_EWF_READERS: OnceLock<Mutex<HashMap<PathBuf, Weak<ewf::EwfReader>>>> =
    OnceLock::new();

fn shared_ewf_reader(path: &Path) -> Result<Arc<ewf::EwfReader>> {
    let key = fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf());
    let cache = SHARED_EWF_READERS.get_or_init(|| Mutex::new(HashMap::new()));
    let mut cache = cache
        .lock()
        .map_err(|_| anyhow!("shared EWF reader cache lock was poisoned"))?;
    if let Some(reader) = cache.get(&key).and_then(Weak::upgrade) {
        return Ok(reader);
    }

    // Keep the lock while opening so simultaneous workers cannot each build a
    // duplicate multi-million-entry chunk index for the same acquisition.
    let reader = Arc::new(
        ewf::EwfReader::open(path)
            .with_context(|| format!("decoding EWF image {}", path.display()))?,
    );
    cache.retain(|_, reader| reader.strong_count() > 0);
    cache.insert(key, Arc::downgrade(&reader));
    Ok(reader)
}

fn has_ewf_signature(path: &Path) -> Result<bool> {
    const EVF2_SIGNATURE: [u8; 8] = [0x45, 0x56, 0x46, 0x32, 0x0d, 0x0a, 0x81, 0x00];
    const LEF2_SIGNATURE: [u8; 8] = [0x4c, 0x45, 0x46, 0x32, 0x0d, 0x0a, 0x81, 0x00];

    let mut file = fs::File::open(path)
        .with_context(|| format!("opening image signature from {}", path.display()))?;
    let mut signature = [0_u8; 8];
    match file.read_exact(&mut signature) {
        Ok(()) => Ok(matches!(
            signature,
            ewf::EVF_SIGNATURE | EVF2_SIGNATURE | LEF2_SIGNATURE
        )),
        Err(error) if error.kind() == io::ErrorKind::UnexpectedEof => Ok(false),
        Err(error) => {
            Err(error).with_context(|| format!("reading image signature from {}", path.display()))
        }
    }
}

/// Discovers a split raw acquisition (image.001, image.002, ...) starting from
/// its first numeric segment. Returns None when `path` is not the `.001`-style
/// first segment or has no siblings. Like the EWF reader, a gap in the
/// sequence is an error rather than a silently partial image.
fn split_raw_segments(path: &Path) -> Result<Option<Vec<(PathBuf, u64)>>> {
    let Some(ext) = path.extension().and_then(|value| value.to_str()) else {
        return Ok(None);
    };
    if ext.len() < 2 || !ext.chars().all(|ch| ch.is_ascii_digit()) {
        return Ok(None);
    }
    let width = ext.len();
    let stem = path
        .to_string_lossy()
        .strip_suffix(ext)
        .map(str::to_string)
        .unwrap_or_default();
    if ext.parse::<u64>().unwrap_or(0) != 1 {
        // Only treat this as a split set when its first segment exists; other
        // numeric extensions (e.g. report.2024) stay ordinary raw files.
        let first = PathBuf::from(format!("{stem}{:0width$}", 1_u64));
        if first.is_file() {
            bail!(
                "split raw evidence must be added from its first segment {}: got {}",
                first.display(),
                path.display()
            );
        }
        return Ok(None);
    }
    let mut segments = Vec::new();
    let mut number: u64 = 1;
    loop {
        let candidate = PathBuf::from(format!("{stem}{number:0width$}"));
        let Ok(metadata) = fs::metadata(&candidate) else {
            break;
        };
        if !metadata.is_file() {
            break;
        }
        segments.push((candidate, metadata.len()));
        number += 1;
    }
    // A sibling segment past the last sequential number means a gap in the
    // set; refuse to open rather than presenting a truncated disk.
    if let Some(parent) = path.parent() {
        let prefix = Path::new(&stem)
            .file_name()
            .map(|value| value.to_string_lossy().into_owned())
            .unwrap_or_default();
        for entry in fs::read_dir(parent).into_iter().flatten().flatten() {
            let name = entry.file_name().to_string_lossy().into_owned();
            if let Some(suffix) = name.strip_prefix(&prefix) {
                if suffix.len() == width && suffix.chars().all(|ch| ch.is_ascii_digit()) {
                    let found: u64 = suffix.parse().unwrap_or(0);
                    if found > segments.len() as u64 {
                        bail!(
                            "split raw image has a segment gap: found segment {found} but segment {} is missing",
                            segments.len() + 1
                        );
                    }
                }
            }
        }
    }
    if segments.len() < 2 {
        return Ok(None);
    }
    Ok(Some(segments))
}

/// Presents ordered split raw segments as one continuous read/seek stream.
struct SplitRawReader {
    /// (open file, absolute start offset, length) per segment.
    segments: Vec<(fs::File, u64, u64)>,
    total_size: u64,
    position: u64,
}

impl SplitRawReader {
    fn open(paths: &[(PathBuf, u64)]) -> Result<Self> {
        let mut segments = Vec::with_capacity(paths.len());
        let mut offset = 0_u64;
        for (path, len) in paths {
            let file = fs::File::open(path)
                .with_context(|| format!("opening split raw segment {}", path.display()))?;
            segments.push((file, offset, *len));
            offset = offset
                .checked_add(*len)
                .context("split raw image exceeds u64 size")?;
        }
        Ok(Self {
            segments,
            total_size: offset,
            position: 0,
        })
    }
}

impl Read for SplitRawReader {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        if buf.is_empty() || self.position >= self.total_size {
            return Ok(0);
        }
        let position = self.position;
        let segment = self
            .segments
            .iter_mut()
            .find(|(_, start, len)| position >= *start && position < *start + *len);
        let Some((file, start, len)) = segment else {
            return Ok(0);
        };
        let within = position - *start;
        let remaining = (*len - within).min(buf.len() as u64) as usize;
        file.seek(SeekFrom::Start(within))?;
        let read = file.read(&mut buf[..remaining])?;
        self.position += read as u64;
        Ok(read)
    }
}

impl Seek for SplitRawReader {
    fn seek(&mut self, pos: SeekFrom) -> io::Result<u64> {
        let target = match pos {
            SeekFrom::Start(offset) => Some(offset),
            SeekFrom::End(delta) => self.total_size.checked_add_signed(delta),
            SeekFrom::Current(delta) => self.position.checked_add_signed(delta),
        };
        match target {
            Some(offset) => {
                self.position = offset;
                Ok(offset)
            }
            None => Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "seek before start of split raw image",
            )),
        }
    }
}

/// A browsable volume within a disk image, discovered without indexing.
#[derive(Debug, Serialize)]
pub struct LiveVolume {
    /// Deprecated compatibility alias for `volume_index_zero_based`.
    pub index: usize,
    pub volume_index_zero_based: usize,
    /// Human partition number when this volume came from a partition table;
    /// whole-image filesystems have no partition number.
    pub partition_number_one_based: Option<usize>,
    pub name: String,
    pub filesystem: String,
    pub start_offset: u64,
    pub size_bytes: u64,
    pub browsable: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub bitlocker: Option<LiveBitLockerInfo>,
}

#[derive(Debug, Clone, Serialize)]
pub struct LiveBitLockerInfo {
    pub status: String,
    pub metadata_state: String,
    pub variant: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub encryption_method: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub encryption_method_raw: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub decrypt_supported: Option<bool>,
    pub can_unlock_with_recovery_key: bool,
    pub can_unlock_with_password: bool,
    pub tpm_only: bool,
    pub protectors: Vec<LiveBitLockerProtector>,
}

#[derive(Debug, Clone, Serialize)]
pub struct LiveBitLockerProtector {
    pub raw: u16,
    pub raw_hex: String,
    pub kind: String,
}

pub enum BitLockerUnlockCredential<'a> {
    RecoveryKey(&'a str),
    Password(&'a str),
}

impl std::fmt::Debug for BitLockerUnlockCredential<'_> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::RecoveryKey(_) => {
                f.write_str("BitLockerUnlockCredential::RecoveryKey(<redacted>)")
            }
            Self::Password(_) => f.write_str("BitLockerUnlockCredential::Password(<redacted>)"),
        }
    }
}

/// One entry returned while browsing a directory live from the image.
#[derive(Debug, Serialize)]
pub struct LiveEntry {
    pub name: String,
    pub is_dir: bool,
    pub size_bytes: Option<i64>,
    pub created_utc: Option<String>,
    pub modified_utc: Option<String>,
    pub accessed_utc: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub ntfs_file_record_number: Option<u64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub mft_record_logical_offset: Option<u64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub mft_record_physical_offset: Option<u64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub file_data_logical_offset: Option<u64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub file_data_physical_offset: Option<u64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub ntfs_mft_record_modification_time_utc: Option<String>,
    #[serde(skip_serializing_if = "is_false")]
    pub symlink: bool,
}

fn is_false(value: &bool) -> bool {
    !*value
}

/// Lists the browsable volumes of a disk image (partitions or whole-image),
/// detecting each volume's filesystem. No files are indexed - this only reads
/// the partition table and volume boot sectors, so it is fast even for huge
/// disks. This is the entry point for live browsing.
pub fn list_image_volumes(image_path: &Path) -> Result<Vec<LiveVolume>> {
    let mut opened = open_disk_image(image_path)?;
    let mut volumes = Vec::new();
    if let Ok(report) = disk_forensic::analyse_disk(&mut opened.reader, opened.decoded_size) {
        let layout = disk_forensic::layout::from_report(&report, "image", opened.decoded_size);
        for partition in &layout.partitions {
            let filesystem = live_volume_filesystem(&mut *opened.reader, partition.start_offset)?;
            let browsable = matches!(filesystem.as_str(), "NTFS" | "FAT" | "EXT");
            let bitlocker = if filesystem == BITLOCKER_LOCKED_FILESYSTEM {
                bitlocker_inspection_at(
                    &mut *opened.reader,
                    partition.start_offset,
                    Some(partition.size_bytes),
                )?
                .as_ref()
                .map(live_bitlocker_info)
            } else {
                None
            };
            let label = partition
                .label
                .as_deref()
                .filter(|value| !value.trim().is_empty())
                .unwrap_or(&partition.name);
            volumes.push(LiveVolume {
                index: volumes.len(),
                volume_index_zero_based: volumes.len(),
                partition_number_one_based: Some(volumes.len() + 1),
                name: format!(
                    "{:03}-{}",
                    volumes.len() + 1,
                    sanitize_logical_segment(label)
                ),
                filesystem,
                start_offset: partition.start_offset,
                size_bytes: partition.size_bytes,
                browsable,
                bitlocker,
            });
        }
    }
    if volumes.is_empty() {
        let filesystem = live_volume_filesystem(&mut *opened.reader, 0)?;
        if filesystem != "unknown" {
            let browsable = matches!(filesystem.as_str(), "NTFS" | "FAT" | "EXT");
            let bitlocker = if filesystem == BITLOCKER_LOCKED_FILESYSTEM {
                bitlocker_inspection_at(&mut *opened.reader, 0, Some(opened.decoded_size))?
                    .as_ref()
                    .map(live_bitlocker_info)
            } else {
                None
            };
            volumes.push(LiveVolume {
                index: 0,
                volume_index_zero_based: 0,
                partition_number_one_based: None,
                name: "whole-image".to_string(),
                filesystem,
                start_offset: 0,
                size_bytes: opened.decoded_size,
                browsable,
                bitlocker,
            });
        }
    }
    Ok(volumes)
}

fn live_volume_filesystem(
    reader: &mut dyn disk_forensic::container::ReadSeek,
    start_offset: u64,
) -> Result<String> {
    if let Some(filesystem) = detect_volume_filesystem_at(reader, start_offset)? {
        return Ok(filesystem.to_string());
    }
    if read_btrfs_superblock(reader, start_offset)?.is_some() {
        return Ok("BTRFS".to_string());
    }
    Ok("unknown".to_string())
}

fn bitlocker_inspection_at(
    reader: &mut dyn disk_forensic::container::ReadSeek,
    start_offset: u64,
    size_bytes: Option<u64>,
) -> Result<Option<bitlocker_decrypt::BitLockerInspection>> {
    let len = size_bytes.unwrap_or_else(|| u64::MAX.saturating_sub(start_offset));
    let mut slice = PartitionSlice::new(reader, start_offset, len);
    bitlocker_decrypt::inspect_reader(&mut slice).context("inspecting BitLocker FVE metadata")
}

fn live_bitlocker_info(inspection: &bitlocker_decrypt::BitLockerInspection) -> LiveBitLockerInfo {
    let encryption_method = inspection
        .encryption_method
        .map(|method| method.description);
    LiveBitLockerInfo {
        status: inspection.status_message().to_string(),
        metadata_state: bitlocker_metadata_state_label(inspection.metadata_state).to_string(),
        variant: bitlocker_variant_label(inspection.variant).to_string(),
        encryption_method: encryption_method.map(str::to_string),
        encryption_method_raw: inspection
            .encryption_method
            .map(|method| format!("0x{:04x}", method.raw)),
        decrypt_supported: inspection
            .encryption_method
            .map(|method| method.decrypt_supported),
        can_unlock_with_recovery_key: inspection.can_unlock_with_recovery_key(),
        can_unlock_with_password: inspection.can_unlock_with_password(),
        tpm_only: inspection.is_tpm_only(),
        protectors: inspection
            .protectors
            .iter()
            .map(|protector| LiveBitLockerProtector {
                raw: protector.raw,
                raw_hex: format!("0x{:04x}", protector.raw),
                kind: protector.kind.label().to_string(),
            })
            .collect(),
    }
}

fn bitlocker_status_message(
    inspection: Option<&bitlocker_decrypt::BitLockerInspection>,
) -> &'static str {
    inspection
        .map(bitlocker_decrypt::BitLockerInspection::status_message)
        .unwrap_or(BITLOCKER_LOCKED_STATUS)
}

fn bitlocker_metadata_value(
    inspection: Option<&bitlocker_decrypt::BitLockerInspection>,
) -> serde_json::Value {
    let bitlocker = inspection
        .map(live_bitlocker_info)
        .and_then(|info| serde_json::to_value(info).ok())
        .unwrap_or(serde_json::Value::Null);
    serde_json::json!({
        "bitlocker": bitlocker,
        "bitlocker_credential_storage": "not persisted; recovery key/password must be supplied per decrypt session",
    })
}

fn bitlocker_metadata_state_label(
    state: bitlocker_decrypt::BitLockerMetadataState,
) -> &'static str {
    match state {
        bitlocker_decrypt::BitLockerMetadataState::Parsed => "parsed",
        bitlocker_decrypt::BitLockerMetadataState::HeaderOnly => "header-only",
    }
}

fn bitlocker_variant_label(variant: bitlocker_decrypt::BitLockerVariant) -> &'static str {
    match variant {
        bitlocker_decrypt::BitLockerVariant::WindowsVista => "Windows Vista",
        bitlocker_decrypt::BitLockerVariant::Windows7OrLater => "Windows 7 or later",
        bitlocker_decrypt::BitLockerVariant::BitLockerToGo => "BitLocker To Go",
    }
}

fn sort_live_entries(entries: &mut [LiveEntry]) {
    entries.sort_by(|left, right| {
        (right.is_dir as u8)
            .cmp(&(left.is_dir as u8))
            .then_with(|| {
                left.name
                    .to_ascii_lowercase()
                    .cmp(&right.name.to_ascii_lowercase())
            })
    });
}

/// Lists the immediate children of one directory in one volume, read live from
/// the image. `dir_path` is volume-relative ("" or "/" is the volume root).
pub fn list_image_directory(
    image_path: &Path,
    volume_index: usize,
    dir_path: &str,
) -> Result<Vec<LiveEntry>> {
    let volumes = list_image_volumes(image_path)?;
    let volume = volumes
        .get(volume_index)
        .with_context(|| format!("volume index {volume_index} out of range"))?;
    let relative = dir_path.trim_matches('/');
    let mut entries = match volume.filesystem.as_str() {
        "NTFS" => {
            list_ntfs_directory(image_path, volume.start_offset, volume.size_bytes, relative)?
        }
        "FAT" => list_fat_directory(image_path, volume.start_offset, volume.size_bytes, relative)?,
        "EXT" => list_ext_directory(image_path, volume.start_offset, relative)?,
        other => bail!("live browsing is not supported for {other} volumes"),
    };
    sort_live_entries(&mut entries);
    Ok(entries)
}

pub fn list_bitlocker_ntfs_directory(
    image_path: &Path,
    volume_index: usize,
    credential: BitLockerUnlockCredential<'_>,
    dir_path: &str,
) -> Result<Vec<LiveEntry>> {
    let volumes = list_image_volumes(image_path)?;
    let volume = volumes
        .get(volume_index)
        .with_context(|| format!("volume index {volume_index} out of range"))?;
    ensure_bitlocker_locked_volume(volume)?;
    let relative = dir_path.trim_matches('/');

    let mut opened = open_disk_image(image_path)?;
    let slice = PartitionSlice::new(&mut *opened.reader, volume.start_offset, volume.size_bytes);
    let mut decrypted = bitlocker_decrypt::unlock_reader(slice, bitlocker_credential(credential)?)
        .with_context(|| {
            format!(
                "unlocking BitLocker volume {} at offset {}",
                volume.name, volume.start_offset
            )
        })?;
    let mut entries = list_ntfs_directory_from_reader(&mut decrypted, relative, None)
        .context("browsing decrypted BitLocker NTFS volume")?;
    sort_live_entries(&mut entries);
    Ok(entries)
}

pub fn read_bitlocker_ntfs_file_bytes(
    image_path: &Path,
    volume_index: usize,
    credential: BitLockerUnlockCredential<'_>,
    file_path: &str,
    offset: u64,
    length: usize,
) -> Result<(Vec<u8>, u64)> {
    let length = length.min(LIVE_BYTES_MAX_LEN);
    let volumes = list_image_volumes(image_path)?;
    let volume = volumes
        .get(volume_index)
        .with_context(|| format!("volume index {volume_index} out of range"))?;
    ensure_bitlocker_locked_volume(volume)?;
    let relative = file_path.trim_matches('/');

    let mut opened = open_disk_image(image_path)?;
    let slice = PartitionSlice::new(&mut *opened.reader, volume.start_offset, volume.size_bytes);
    let mut decrypted = bitlocker_decrypt::unlock_reader(slice, bitlocker_credential(credential)?)
        .with_context(|| {
            format!(
                "unlocking BitLocker volume {} at offset {}",
                volume.name, volume.start_offset
            )
        })?;
    read_ntfs_path_bytes_from_reader(&mut decrypted, relative, offset, length)
        .context("reading decrypted BitLocker NTFS file")
}

fn ensure_bitlocker_locked_volume(volume: &LiveVolume) -> Result<()> {
    if volume.filesystem != BITLOCKER_LOCKED_FILESYSTEM {
        bail!(
            "volume {} is {}, not a locked BitLocker volume",
            volume.index,
            volume.filesystem
        );
    }
    Ok(())
}

fn bitlocker_credential(
    credential: BitLockerUnlockCredential<'_>,
) -> Result<bitlocker_decrypt::BitLockerCredential> {
    match credential {
        BitLockerUnlockCredential::RecoveryKey(recovery_key) => {
            bitlocker_decrypt::BitLockerCredential::recovery_key(recovery_key)
                .context("validating BitLocker recovery key")
        }
        BitLockerUnlockCredential::Password(password) => {
            Ok(bitlocker_decrypt::BitLockerCredential::password(password))
        }
    }
}

fn list_ntfs_directory(
    image_path: &Path,
    start_offset: u64,
    size_bytes: u64,
    relative: &str,
) -> Result<Vec<LiveEntry>> {
    let mut opened = open_disk_image(image_path)?;
    let mut slice = PartitionSlice::new(&mut *opened.reader, start_offset, size_bytes);
    list_ntfs_directory_from_reader(&mut slice, relative, Some(start_offset))
}

fn list_ntfs_directory_from_reader<T: Read + Seek>(
    fs: &mut T,
    relative: &str,
    physical_base: Option<u64>,
) -> Result<Vec<LiveEntry>> {
    let ntfs = ntfs::Ntfs::new(fs).context("opening NTFS volume")?;
    let mut record = ntfs
        .root_directory(fs)
        .context("opening NTFS root directory")?
        .file_record_number();
    for component in relative.split('/').filter(|value| !value.is_empty()) {
        let children = collect_ntfs_dir_children(&ntfs, fs, record)?.children;
        let child = children
            .iter()
            .find(|child| child.is_directory && child.name.eq_ignore_ascii_case(component))
            .with_context(|| format!("directory not found: {component}"))?;
        record = child.file_record_number;
    }
    let children = collect_ntfs_dir_children(&ntfs, fs, record)?.children;
    Ok(children
        .into_iter()
        .map(|child| LiveEntry {
            ntfs_file_record_number: Some(child.file_record_number),
            mft_record_logical_offset: child.mft_record_logical_offset,
            mft_record_physical_offset: physical_base.and_then(|base| {
                child
                    .mft_record_logical_offset
                    .and_then(|offset| base.checked_add(offset))
            }),
            file_data_logical_offset: child.file_data_logical_offset,
            file_data_physical_offset: physical_base.and_then(|base| {
                child
                    .file_data_logical_offset
                    .and_then(|offset| base.checked_add(offset))
            }),
            ntfs_mft_record_modification_time_utc: child
                .standard_mft_record_modification_time_utc
                .or(child.mft_record_modification_time_utc),
            size_bytes: if child.is_directory {
                None
            } else {
                Some(i64::try_from(child.size_bytes).unwrap_or(i64::MAX))
            },
            created_utc: child.standard_creation_time_utc.or(child.creation_time_utc),
            modified_utc: child
                .standard_modification_time_utc
                .or(child.modification_time_utc),
            accessed_utc: child.standard_access_time_utc.or(child.access_time_utc),
            name: child.name,
            is_dir: child.is_directory,
            symlink: false,
        })
        .collect())
}

fn read_ntfs_path_bytes_from_reader<T: Read + Seek>(
    fs: &mut T,
    relative: &str,
    offset: u64,
    length: usize,
) -> Result<(Vec<u8>, u64)> {
    let ntfs = ntfs::Ntfs::new(&mut *fs).context("opening NTFS volume")?;
    let target = ntfs_file_child_for_relative_path(&ntfs, fs, relative)?;
    if target.is_directory {
        bail!("NTFS path is a directory, not a readable file: {relative}");
    }
    let total = target.size_bytes;
    let read_end = offset.saturating_add(length as u64);
    let read_len = usize::try_from(read_end).unwrap_or(usize::MAX);
    let bytes = read_ntfs_file_record_bytes(&ntfs, fs, target.file_record_number, read_len)?;
    let start = usize::try_from(offset)
        .unwrap_or(usize::MAX)
        .min(bytes.len());
    let end = start.saturating_add(length).min(bytes.len());
    Ok((bytes[start..end].to_vec(), total))
}

fn ntfs_file_child_for_relative_path<T: Read + Seek>(
    ntfs: &ntfs::Ntfs,
    fs: &mut T,
    relative: &str,
) -> Result<NtfsDirChild> {
    let mut record = ntfs
        .root_directory(fs)
        .context("opening NTFS root directory")?
        .file_record_number();
    let components: Vec<&str> = relative
        .split('/')
        .filter(|value| !value.is_empty())
        .collect();
    let Some((file_name, dir_components)) = components.split_last() else {
        bail!("no file path given");
    };
    for component in dir_components {
        let children = collect_ntfs_dir_children(ntfs, fs, record)?.children;
        let child = children
            .iter()
            .find(|child| child.is_directory && child.name.eq_ignore_ascii_case(component))
            .with_context(|| format!("directory not found: {component}"))?;
        record = child.file_record_number;
    }
    let children = collect_ntfs_dir_children(ntfs, fs, record)?.children;
    children
        .into_iter()
        .find(|child| child.name.eq_ignore_ascii_case(file_name))
        .with_context(|| format!("file not found: {file_name}"))
}

fn list_fat_directory(
    image_path: &Path,
    start_offset: u64,
    size_bytes: u64,
    relative: &str,
) -> Result<Vec<LiveEntry>> {
    let mut opened = open_disk_image(image_path)?;
    let slice = PartitionSlice::new(&mut *opened.reader, start_offset, size_bytes);
    let fs = fatfs::FileSystem::new(slice, fatfs::FsOptions::new())
        .with_context(|| format!("opening FAT volume at offset {start_offset}"))?;
    let root = fs.root_dir();
    let dir = if relative.is_empty() {
        root
    } else {
        root.open_dir(relative)
            .with_context(|| format!("opening FAT directory {relative}"))?
    };
    let mut entries = Vec::new();
    for entry in dir.iter() {
        let entry = entry.context("reading FAT directory entry")?;
        let name = entry.file_name();
        if name == "." || name == ".." {
            continue;
        }
        entries.push(LiveEntry {
            is_dir: entry.is_dir(),
            size_bytes: if entry.is_dir() {
                None
            } else {
                Some(i64::try_from(entry.len()).unwrap_or(i64::MAX))
            },
            created_utc: fat_datetime_iso(entry.created()),
            modified_utc: fat_datetime_iso(entry.modified()),
            accessed_utc: fat_date_iso(entry.accessed()),
            ntfs_file_record_number: None,
            mft_record_logical_offset: None,
            mft_record_physical_offset: None,
            file_data_logical_offset: None,
            file_data_physical_offset: None,
            ntfs_mft_record_modification_time_utc: None,
            name,
            symlink: false,
        });
    }
    Ok(entries)
}

fn fat_datetime_iso(value: fatfs::DateTime) -> Option<String> {
    if value.date.year == 0 {
        return None;
    }
    let base = format!(
        "{:04}-{:02}-{:02}T{:02}:{:02}:{:02}",
        value.date.year,
        value.date.month,
        value.date.day,
        value.time.hour,
        value.time.min,
        value.time.sec
    );
    // FAT creation times carry 10ms-resolution fractions; keep them rather
    // than silently rounding examiner-facing timestamps to whole seconds.
    Some(if value.time.millis != 0 {
        format!("{base}.{:03}Z", value.time.millis)
    } else {
        format!("{base}Z")
    })
}

fn fat_date_iso(value: fatfs::Date) -> Option<String> {
    if value.year == 0 {
        return None;
    }
    Some(format!(
        "{:04}-{:02}-{:02}",
        value.year, value.month, value.day
    ))
}

fn list_ext_directory(
    image_path: &Path,
    start_offset: u64,
    relative: &str,
) -> Result<Vec<LiveEntry>> {
    let fs = open_ext4_superblock(image_path, start_offset)?;
    let path = if relative.is_empty() {
        "/".to_string()
    } else {
        format!("/{relative}")
    };
    let children = ext4_list_dir(&fs, &path)?;
    let mut entries = Vec::with_capacity(children.len());
    for child in children {
        let size_bytes = i64::try_from(child.size).unwrap_or(i64::MAX);
        entries.push(LiveEntry {
            name: child.name,
            is_dir: child.is_dir,
            size_bytes: if child.is_dir { None } else { Some(size_bytes) },
            created_utc: child.btime_utc.or(child.ctime_utc),
            modified_utc: child.mtime_utc,
            accessed_utc: child.atime_utc,
            ntfs_file_record_number: None,
            mft_record_logical_offset: None,
            mft_record_physical_offset: None,
            file_data_logical_offset: None,
            file_data_physical_offset: None,
            ntfs_mft_record_modification_time_utc: None,
            symlink: child.is_symlink,
        });
    }
    Ok(entries)
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct LocalDirectoryCursor {
    pub name: String,
    pub is_dir: bool,
}

#[derive(Debug, Serialize)]
pub struct LocalDirectoryListing {
    pub entries: Vec<LiveEntry>,
    pub total_entries: usize,
    pub next_cursor: Option<LocalDirectoryCursor>,
    /// True when this page has another page. This is retained for API
    /// compatibility; it no longer means the directory itself was omitted.
    pub truncated: bool,
}

#[derive(Debug)]
struct LocalLiveEvidence {
    source_kind: String,
    source_path: PathBuf,
    display_name: String,
}

const LIVE_BYTES_MAX_LEN: usize = 8 * 1024 * 1024;
const RAW_FIND_CHUNK_BYTES: usize = 4 * 1024 * 1024;
const RAW_FIND_MAX_SCAN_BYTES: u64 = 256 * 1024 * 1024;

fn image_evidence_path(case_path: &Path, evidence_id: i64) -> Result<PathBuf> {
    let conn = open_existing_case(case_path)?;
    let case_id = active_case_id(&conn)?;
    let (source_kind, source_path): (String, String) = conn
        .query_row(
            "SELECT source_kind, source_path
             FROM evidence_sources
             WHERE case_id = ?1 AND id = ?2",
            params![case_id, evidence_id],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()?
        .with_context(|| format!("evidence {evidence_id} not found"))?;
    if source_kind != "image" {
        bail!("raw image bytes are only available for image evidence, not {source_kind}");
    }
    Ok(PathBuf::from(source_path))
}

fn read_local_live_evidence(case_path: &Path, evidence_id: i64) -> Result<LocalLiveEvidence> {
    let conn = open_existing_case(case_path)?;
    let case_id = active_case_id(&conn)?;
    let source = conn
        .query_row(
            "SELECT source_kind, source_path, display_name
             FROM evidence_sources
             WHERE case_id = ?1 AND id = ?2",
            params![case_id, evidence_id],
            |row| {
                Ok(LocalLiveEvidence {
                    source_kind: row.get(0)?,
                    source_path: PathBuf::from(row.get::<_, String>(1)?),
                    display_name: row.get(2)?,
                })
            },
        )
        .optional()?
        .with_context(|| format!("evidence {evidence_id} not found"))?;
    if source.source_kind != "folder" && source.source_kind != "file" {
        bail!(
            "local live browsing supports folder/file evidence, not {}",
            source.source_kind
        );
    }
    Ok(source)
}

fn split_live_relative_path(relative_path: &str) -> Result<Vec<String>> {
    if Path::new(relative_path)
        .components()
        .any(|component| matches!(component, Component::Prefix(_)))
    {
        bail!("relative path must stay inside the evidence root");
    }
    let normalized = relative_path.replace('\\', "/");
    let trimmed = normalized.trim_matches('/');
    let mut parts = Vec::new();
    for part in trimmed.split('/') {
        if part.is_empty() || part == "." {
            continue;
        }
        if part == ".." {
            bail!("relative path escapes evidence root: '..' is not allowed");
        }
        parts.push(part.to_string());
    }
    Ok(parts)
}

fn ensure_under_evidence_root(root: &Path, candidate: &Path) -> Result<PathBuf> {
    let canonical = candidate
        .canonicalize()
        .with_context(|| format!("resolving evidence path {}", candidate.display()))?;
    if !canonical.starts_with(root) {
        bail!("relative path escapes evidence root");
    }
    Ok(canonical)
}

fn resolve_local_folder_path(
    source_path: &Path,
    relative_path: &str,
) -> Result<(PathBuf, PathBuf)> {
    let root = source_path
        .canonicalize()
        .with_context(|| format!("resolving evidence root {}", source_path.display()))?;
    if !root.is_dir() {
        bail!(
            "folder evidence path is no longer a directory: {}",
            root.display()
        );
    }

    let mut candidate = root.clone();
    for part in split_live_relative_path(relative_path)? {
        candidate.push(&part);
        let metadata = fs::symlink_metadata(&candidate)
            .with_context(|| format!("reading evidence path {}", candidate.display()))?;
        if metadata.file_type().is_symlink() {
            if candidate
                .canonicalize()
                .map(|canonical| !canonical.starts_with(&root))
                .unwrap_or(true)
            {
                bail!("relative path escapes evidence root through a symlink");
            }
            bail!(
                "live browse does not follow symlinks: {}",
                candidate.display()
            );
        }
    }
    let canonical = ensure_under_evidence_root(&root, &candidate)?;
    Ok((root, canonical))
}

fn resolve_single_file_path(source: &LocalLiveEvidence, relative_path: &str) -> Result<PathBuf> {
    let file = source
        .source_path
        .canonicalize()
        .with_context(|| format!("resolving evidence file {}", source.source_path.display()))?;
    if !file.is_file() {
        bail!("file evidence path is no longer a file: {}", file.display());
    }
    let parts = split_live_relative_path(relative_path)?;
    if parts.is_empty() {
        return Ok(file);
    }
    let file_name = file
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or("");
    if parts.len() == 1 && (parts[0] == file_name || parts[0] == source.display_name) {
        return Ok(file);
    }
    bail!("single-file evidence exposes only the attached file");
}

fn resolve_local_live_file_path(
    source: &LocalLiveEvidence,
    relative_path: &str,
) -> Result<PathBuf> {
    match source.source_kind.as_str() {
        "folder" => {
            let (_root, path) = resolve_local_folder_path(&source.source_path, relative_path)?;
            Ok(path)
        }
        "file" => resolve_single_file_path(source, relative_path),
        other => bail!("local live byte reading is not supported for {other} evidence"),
    }
}

fn system_time_rfc3339(value: Option<std::time::SystemTime>) -> Option<String> {
    value.map(|time| DateTime::<Utc>::from(time).to_rfc3339())
}

/// Converts a `fatfs` DOS date (no time component - FAT last-accessed dates
/// are date-only) to RFC 3339. A DOS date of zero decodes to an invalid
/// calendar date (month/day 0), which `NaiveDate::from_ymd_opt` correctly
/// rejects, so "unset" naturally becomes `None` with no extra sentinel check.
fn fatfs_date_to_rfc3339(date: &fatfs::Date) -> Option<String> {
    chrono::NaiveDate::from_ymd_opt(
        i32::from(date.year),
        u32::from(date.month),
        u32::from(date.day),
    )
    .map(|naive| {
        DateTime::<Utc>::from_naive_utc_and_offset(naive.and_time(chrono::NaiveTime::MIN), Utc)
            .to_rfc3339()
    })
}

/// Converts a `fatfs` DOS date+time to RFC 3339. Same zero-date handling as
/// `fatfs_date_to_rfc3339`.
fn fatfs_datetime_to_rfc3339(value: &fatfs::DateTime) -> Option<String> {
    let naive_date = chrono::NaiveDate::from_ymd_opt(
        i32::from(value.date.year),
        u32::from(value.date.month),
        u32::from(value.date.day),
    )?;
    let naive_time = chrono::NaiveTime::from_hms_milli_opt(
        u32::from(value.time.hour),
        u32::from(value.time.min),
        u32::from(value.time.sec),
        u32::from(value.time.millis),
    )?;
    Some(
        DateTime::<Utc>::from_naive_utc_and_offset(naive_date.and_time(naive_time), Utc)
            .to_rfc3339(),
    )
}

fn local_live_entry(name: String, metadata: fs::Metadata) -> Result<LiveEntry> {
    let file_type = metadata.file_type();
    let symlink = file_type.is_symlink();
    let is_dir = !symlink && file_type.is_dir();
    let size_bytes = if is_dir {
        None
    } else {
        Some(i64::try_from(metadata.len()).context("local live entry size exceeds i64")?)
    };
    Ok(LiveEntry {
        name,
        is_dir,
        size_bytes,
        created_utc: system_time_rfc3339(metadata.created().ok()),
        modified_utc: system_time_rfc3339(metadata.modified().ok()),
        accessed_utc: system_time_rfc3339(metadata.accessed().ok()),
        ntfs_file_record_number: None,
        mft_record_logical_offset: None,
        mft_record_physical_offset: None,
        file_data_logical_offset: None,
        file_data_physical_offset: None,
        ntfs_mft_record_modification_time_utc: None,
        symlink,
    })
}

fn local_entry_order(
    left_is_dir: bool,
    left_name: &str,
    right_is_dir: bool,
    right_name: &str,
) -> std::cmp::Ordering {
    (right_is_dir as u8)
        .cmp(&(left_is_dir as u8))
        .then_with(|| {
            left_name
                .to_ascii_lowercase()
                .cmp(&right_name.to_ascii_lowercase())
        })
        .then_with(|| left_name.cmp(right_name))
}

fn local_entry_sort(left: &LiveEntry, right: &LiveEntry) -> std::cmp::Ordering {
    local_entry_order(left.is_dir, &left.name, right.is_dir, &right.name)
}

pub fn list_local_directory(
    case_path: &Path,
    evidence_id: i64,
    relative_path: &str,
) -> Result<LocalDirectoryListing> {
    // Compatibility/full-list API: zero means no page-size bound. The UI uses
    // `list_local_directory_page` so it never needs to retain the full folder.
    list_local_directory_page(case_path, evidence_id, relative_path, None, 0)
}

/// Reads one stable, sorted page of a local live directory. Each page scan
/// retains at most roughly twice the requested page size, so a directory with
/// millions of children does not require a million-entry in-memory vector.
/// The source is deliberately read live and is not indexed or snapshotted.
pub fn list_local_directory_page(
    case_path: &Path,
    evidence_id: i64,
    relative_path: &str,
    after: Option<&LocalDirectoryCursor>,
    limit: usize,
) -> Result<LocalDirectoryListing> {
    let source = read_local_live_evidence(case_path, evidence_id)?;
    if source.source_kind == "file" {
        let file = resolve_single_file_path(&source, relative_path)?;
        let metadata = fs::symlink_metadata(&file)
            .with_context(|| format!("reading evidence file metadata {}", file.display()))?;
        let name = file
            .file_name()
            .and_then(|value| value.to_str())
            .unwrap_or(&source.display_name)
            .to_string();
        return Ok(LocalDirectoryListing {
            entries: vec![local_live_entry(name, metadata)?],
            total_entries: 1,
            next_cursor: None,
            truncated: false,
        });
    }

    let (_root, dir_path) = resolve_local_folder_path(&source.source_path, relative_path)?;
    let metadata = fs::symlink_metadata(&dir_path)
        .with_context(|| format!("reading evidence directory metadata {}", dir_path.display()))?;
    if metadata.file_type().is_symlink() {
        bail!(
            "live browse does not follow symlinks: {}",
            dir_path.display()
        );
    }
    if !metadata.is_dir() {
        bail!("local live path is not a directory: {}", dir_path.display());
    }

    let take = if limit == 0 { usize::MAX } else { limit };
    let lookahead = take.saturating_add(1);
    let trim_threshold = lookahead.saturating_mul(2);
    let mut entries = Vec::with_capacity(lookahead.min(4_096));
    let mut total_entries = 0_usize;
    let read_dir = fs::read_dir(&dir_path)
        .with_context(|| format!("reading evidence directory {}", dir_path.display()))?;
    for child in read_dir {
        let child = child.with_context(|| format!("reading entry in {}", dir_path.display()))?;
        let child_path = child.path();
        let metadata = fs::symlink_metadata(&child_path)
            .with_context(|| format!("reading evidence entry metadata {}", child_path.display()))?;
        let name = child
            .file_name()
            .to_str()
            .map(str::to_string)
            .unwrap_or_else(|| child.file_name().to_string_lossy().into_owned());
        let entry = local_live_entry(name, metadata)?;
        total_entries = total_entries.saturating_add(1);
        if after.is_some_and(|cursor| {
            local_entry_order(entry.is_dir, &entry.name, cursor.is_dir, &cursor.name)
                != std::cmp::Ordering::Greater
        }) {
            continue;
        }
        entries.push(entry);
        if entries.len() > trim_threshold {
            entries.sort_by(local_entry_sort);
            entries.truncate(lookahead);
        }
    }
    entries.sort_by(local_entry_sort);
    let has_more = entries.len() > take;
    entries.truncate(take);
    let next_cursor = if has_more {
        entries.last().map(|last| LocalDirectoryCursor {
            name: last.name.clone(),
            is_dir: last.is_dir,
        })
    } else {
        None
    };
    Ok(LocalDirectoryListing {
        entries,
        total_entries,
        next_cursor,
        truncated: has_more,
    })
}

/// Reads a file's bytes live from a volume by path (for the byte viewer during
/// live browsing, before anything is indexed).
/// Reads a bounded window of a file's bytes live from a volume by path, and
/// returns (window, total_file_size) for the byte viewer.
pub fn read_image_directory_bytes(
    image_path: &Path,
    volume_index: usize,
    file_path: &str,
    offset: u64,
    length: usize,
) -> Result<(Vec<u8>, u64)> {
    let length = length.min(LIVE_BYTES_MAX_LEN);
    let volumes = list_image_volumes(image_path)?;
    let volume = volumes
        .get(volume_index)
        .with_context(|| format!("volume index {volume_index} out of range"))?;
    let relative = file_path.trim_matches('/');
    match volume.filesystem.as_str() {
        "EXT" => {
            let fs = open_ext4_superblock(image_path, volume.start_offset)?;
            let data = ext4_read_file_bytes(&fs, &format!("/{relative}"))?;
            let total = data.len() as u64;
            let start = (offset as usize).min(data.len());
            let end = start.saturating_add(length).min(data.len());
            Ok((data[start..end].to_vec(), total))
        }
        "FAT" => {
            let mut opened = open_disk_image(image_path)?;
            let slice =
                PartitionSlice::new(&mut *opened.reader, volume.start_offset, volume.size_bytes);
            let fs = fatfs::FileSystem::new(slice, fatfs::FsOptions::new())
                .context("opening FAT volume")?;
            let mut file = fs
                .root_dir()
                .open_file(relative)
                .with_context(|| format!("opening FAT file {relative}"))?;
            let total = file.seek(SeekFrom::End(0))?;
            file.seek(SeekFrom::Start(offset))?;
            // fatfs returns at most one cluster per read call; fill the whole
            // window or the request truncates at ~4 KiB.
            let mut buffer = vec![0_u8; length];
            let mut filled = 0_usize;
            while filled < buffer.len() {
                let read = file.read(&mut buffer[filled..])?;
                if read == 0 {
                    break;
                }
                filled += read;
            }
            buffer.truncate(filled);
            Ok((buffer, total))
        }
        "NTFS" => {
            let mut opened = open_disk_image(image_path)?;
            let mut slice =
                PartitionSlice::new(&mut *opened.reader, volume.start_offset, volume.size_bytes);
            let ntfs = ntfs::Ntfs::new(&mut slice).context("opening NTFS volume")?;
            let mut record = ntfs
                .root_directory(&mut slice)
                .context("opening NTFS root directory")?
                .file_record_number();
            let components: Vec<&str> = relative.split('/').filter(|v| !v.is_empty()).collect();
            let Some((file_name, dir_components)) = components.split_last() else {
                bail!("no file path given");
            };
            for component in dir_components {
                let children = collect_ntfs_dir_children(&ntfs, &mut slice, record)?.children;
                let child = children
                    .iter()
                    .find(|child| child.is_directory && child.name.eq_ignore_ascii_case(component))
                    .with_context(|| format!("directory not found: {component}"))?;
                record = child.file_record_number;
            }
            let children = collect_ntfs_dir_children(&ntfs, &mut slice, record)?.children;
            let target = children
                .iter()
                .find(|child| !child.is_directory && child.name.eq_ignore_ascii_case(file_name))
                .with_context(|| format!("file not found: {file_name}"))?;
            let total = target.size_bytes;
            let bytes = read_ntfs_file_record_bytes(
                &ntfs,
                &mut slice,
                target.file_record_number,
                offset.saturating_add(length as u64) as usize,
            )?;
            let start = (offset as usize).min(bytes.len());
            let end = start.saturating_add(length).min(bytes.len());
            Ok((bytes[start..end].to_vec(), total))
        }
        other => bail!("live byte reading is not supported for {other} volumes"),
    }
}

/// Reads a bounded decoded-device byte window from image evidence. The offset
/// is absolute in the decoded disk stream, so EWF, VHD/VDI, and split raw
/// sources are presented as the examiner-visible device bytes.
pub fn read_image_raw_bytes(
    case_path: &Path,
    evidence_id: i64,
    offset: u64,
    length: usize,
) -> Result<(Vec<u8>, u64)> {
    let image_path = image_evidence_path(case_path, evidence_id)?;
    let mut opened = open_disk_image(&image_path)?;
    let total_size = opened.decoded_size;
    let read_offset = offset.min(total_size);
    opened
        .reader
        .seek(SeekFrom::Start(read_offset))
        .with_context(|| format!("seeking decoded image bytes at offset {read_offset}"))?;
    let mut buffer = Vec::new();
    opened
        .reader
        .take(length.min(LIVE_BYTES_MAX_LEN) as u64)
        .read_to_end(&mut buffer)
        .with_context(|| format!("reading decoded image bytes at offset {read_offset}"))?;
    Ok((buffer, total_size))
}

pub fn find_in_image_raw(
    case_path: &Path,
    evidence_id: i64,
    start_offset: u64,
    query: &str,
    kind: RawFindKind,
) -> Result<ImageRawFindResult> {
    find_in_image_raw_with_limits(
        case_path,
        evidence_id,
        start_offset,
        query,
        kind,
        RAW_FIND_CHUNK_BYTES,
        RAW_FIND_MAX_SCAN_BYTES,
    )
}

fn find_in_image_raw_with_limits(
    case_path: &Path,
    evidence_id: i64,
    start_offset: u64,
    query: &str,
    kind: RawFindKind,
    chunk_size: usize,
    scan_cap: u64,
) -> Result<ImageRawFindResult> {
    let patterns = raw_find_patterns(query, kind)?;
    let max_pattern_len = patterns
        .iter()
        .map(RawFindPattern::byte_len)
        .max()
        .unwrap_or(0);
    if max_pattern_len == 0 {
        bail!("raw find query cannot be empty");
    }
    if max_pattern_len as u64 > scan_cap {
        bail!("raw find query is larger than the per-call scan cap");
    }
    let chunk_size = chunk_size.max(1);
    let image_path = image_evidence_path(case_path, evidence_id)?;
    let mut opened = open_disk_image(&image_path)?;
    let total_size = opened.decoded_size;
    let mut read_offset = start_offset.min(total_size);
    if read_offset >= total_size {
        return Ok(ImageRawFindResult {
            match_offset: None,
            match_length: None,
            scanned_to: total_size,
            next_scan_offset: total_size,
            eof: true,
        });
    }

    let scan_end = read_offset.saturating_add(scan_cap).min(total_size);
    let overlap_len = max_pattern_len.saturating_sub(1);
    let mut tail = Vec::new();
    let mut min_match_start = read_offset;

    while read_offset < scan_end {
        let read_len = usize::try_from(scan_end.saturating_sub(read_offset))
            .unwrap_or(usize::MAX)
            .min(chunk_size);
        opened
            .reader
            .seek(SeekFrom::Start(read_offset))
            .with_context(|| format!("seeking decoded image bytes at offset {read_offset}"))?;
        let mut chunk = Vec::new();
        opened
            .reader
            .by_ref()
            .take(read_len as u64)
            .read_to_end(&mut chunk)
            .with_context(|| format!("reading decoded image bytes at offset {read_offset}"))?;
        if chunk.is_empty() {
            break;
        }

        let buffer_start = read_offset.saturating_sub(tail.len() as u64);
        let mut buffer = Vec::with_capacity(tail.len() + chunk.len());
        buffer.extend_from_slice(&tail);
        buffer.extend_from_slice(&chunk);
        let read_end = read_offset.saturating_add(chunk.len() as u64);
        let min_index = usize::try_from(min_match_start.saturating_sub(buffer_start))
            .unwrap_or(usize::MAX)
            .min(buffer.len());

        if let Some((match_index, match_length)) =
            find_raw_patterns_in_buffer(&buffer, min_index, &patterns)
        {
            let match_offset = buffer_start.saturating_add(match_index as u64);
            return Ok(ImageRawFindResult {
                match_offset: Some(match_offset),
                match_length: Some(match_length),
                scanned_to: read_end,
                next_scan_offset: match_offset.saturating_add(1),
                eof: read_end >= total_size,
            });
        }

        read_offset = read_end;
        min_match_start = min_match_start.max(read_end.saturating_sub(overlap_len as u64));
        if overlap_len == 0 {
            tail.clear();
        } else if buffer.len() > overlap_len {
            tail = buffer[buffer.len() - overlap_len..].to_vec();
        } else {
            tail = buffer;
        }
    }

    let eof = read_offset >= total_size;
    let next_scan_offset = if eof {
        total_size
    } else {
        read_offset.saturating_sub(overlap_len as u64)
    };
    Ok(ImageRawFindResult {
        match_offset: None,
        match_length: None,
        scanned_to: read_offset,
        next_scan_offset,
        eof,
    })
}

enum RawFindPattern {
    Exact(Vec<u8>),
    AsciiCaseInsensitive(Vec<u8>),
    Utf16LeCaseInsensitive(Vec<u16>),
}

impl RawFindPattern {
    fn byte_len(&self) -> usize {
        match self {
            Self::Exact(bytes) | Self::AsciiCaseInsensitive(bytes) => bytes.len(),
            Self::Utf16LeCaseInsensitive(units) => units.len().saturating_mul(2),
        }
    }

    fn find_in(&self, haystack: &[u8]) -> Option<usize> {
        match self {
            Self::Exact(bytes) => find_exact_bytes(haystack, bytes),
            Self::AsciiCaseInsensitive(bytes) => find_ascii_case_insensitive_bytes(haystack, bytes),
            Self::Utf16LeCaseInsensitive(units) => {
                find_utf16_ascii_case_insensitive_bytes(haystack, units, true)
            }
        }
    }
}

fn raw_find_patterns(query: &str, kind: RawFindKind) -> Result<Vec<RawFindPattern>> {
    let query = query.trim();
    if query.is_empty() {
        bail!("raw find query cannot be empty");
    }
    match kind {
        RawFindKind::Hex => {
            let raw = strip_hex_query_prefix(query).unwrap_or(query);
            Ok(vec![RawFindPattern::Exact(parse_hex_pattern(raw)?)])
        }
        RawFindKind::Text => Ok(vec![
            RawFindPattern::AsciiCaseInsensitive(query.as_bytes().to_vec()),
            RawFindPattern::Utf16LeCaseInsensitive(query.encode_utf16().collect()),
        ]),
    }
}

fn find_raw_patterns_in_buffer(
    buffer: &[u8],
    min_index: usize,
    patterns: &[RawFindPattern],
) -> Option<(usize, usize)> {
    let search = buffer.get(min_index..)?;
    let mut best: Option<(usize, usize)> = None;
    for pattern in patterns {
        let Some(relative) = pattern.find_in(search) else {
            continue;
        };
        let absolute = min_index.saturating_add(relative);
        let length = pattern.byte_len();
        if best
            .as_ref()
            .is_none_or(|(best_offset, _)| absolute < *best_offset)
        {
            best = Some((absolute, length));
        }
    }
    best
}

pub fn read_local_evidence_bytes(
    case_path: &Path,
    evidence_id: i64,
    relative_path: &str,
    offset: u64,
    length: usize,
) -> Result<(Vec<u8>, u64)> {
    let source = read_local_live_evidence(case_path, evidence_id)?;
    let path = resolve_local_live_file_path(&source, relative_path)?;
    let metadata = fs::symlink_metadata(&path)
        .with_context(|| format!("reading evidence file metadata {}", path.display()))?;
    if metadata.file_type().is_symlink() {
        bail!(
            "live byte reading does not follow symlinks: {}",
            path.display()
        );
    }
    if !metadata.is_file() {
        bail!("local live path is not a file: {}", path.display());
    }
    let total = metadata.len();
    let mut file = fs::File::open(&path)
        .with_context(|| format!("opening evidence file {}", path.display()))?;
    file.seek(SeekFrom::Start(offset))
        .with_context(|| format!("seeking evidence file {}", path.display()))?;
    let mut buffer = Vec::new();
    file.take(length.min(LIVE_BYTES_MAX_LEN) as u64)
        .read_to_end(&mut buffer)
        .with_context(|| format!("reading evidence file {}", path.display()))?;
    Ok((buffer, total))
}

#[derive(Debug, Clone, Serialize)]
pub struct LiveExportResult {
    pub output_path: String,
    pub bytes_written: u64,
    pub total_size: u64,
    pub sha256_hex: String,
}

/// Safety ceiling for live (un-indexed) file export. A partial copy would look
/// complete on disk, so oversized files fail loudly instead of truncating.
const LIVE_EXPORT_MAX_BYTES: u64 = 1024 * 1024 * 1024;

pub fn export_local_file(
    case_path: &Path,
    evidence_id: i64,
    relative_path: &str,
    output_path: &Path,
) -> Result<LiveExportResult> {
    let source = read_local_live_evidence(case_path, evidence_id)?;
    let path = resolve_local_live_file_path(&source, relative_path)?;
    let metadata = fs::symlink_metadata(&path)
        .with_context(|| format!("reading evidence file metadata {}", path.display()))?;
    if metadata.file_type().is_symlink() {
        bail!("live export does not follow symlinks: {}", path.display());
    }
    if !metadata.is_file() {
        bail!("local live path is not a file: {}", path.display());
    }
    let total_size = metadata.len();
    if total_size > LIVE_EXPORT_MAX_BYTES {
        bail!(
            "file is {total_size} bytes; live export is capped at {LIVE_EXPORT_MAX_BYTES} bytes - process the evidence to export it"
        );
    }
    if let Some(parent) = output_path.parent() {
        fs::create_dir_all(parent)
            .with_context(|| format!("creating export folder {}", parent.display()))?;
    }

    let mut source_file = fs::File::open(&path)
        .with_context(|| format!("opening evidence file {}", path.display()))?;
    let mut output = AtomicOutput::create(output_path)
        .with_context(|| format!("creating exported file {}", output_path.display()))?;
    let mut hasher = Sha256::new();
    let mut buffer = vec![0_u8; 1024 * 1024];
    let mut bytes_written = 0_u64;
    loop {
        let read = source_file
            .read(&mut buffer)
            .with_context(|| format!("reading evidence file {}", path.display()))?;
        if read == 0 {
            break;
        }
        if bytes_written.saturating_add(read as u64) > LIVE_EXPORT_MAX_BYTES {
            bail!(
                "file is larger than live export cap ({LIVE_EXPORT_MAX_BYTES} bytes): {}",
                path.display()
            );
        }
        output
            .write_all(&buffer[..read])
            .with_context(|| format!("writing exported file {}", output_path.display()))?;
        hasher.update(&buffer[..read]);
        bytes_written += read as u64;
    }
    if bytes_written != total_size {
        bail!(
            "source size changed during export (expected {total_size} bytes, read {bytes_written}); no final output was published"
        );
    }
    output
        .commit()
        .with_context(|| format!("publishing exported file {}", output_path.display()))?;

    Ok(LiveExportResult {
        output_path: output_path.display().to_string(),
        bytes_written,
        total_size,
        sha256_hex: format!("{:x}", hasher.finalize()),
    })
}

/// Copy one file directly from an attached disk image without indexing while
/// hashing the written bytes. The caller records the
/// audit event via `record_live_export`.
pub fn export_image_file(
    image_path: &Path,
    volume_index: usize,
    file_path: &str,
    output_path: &Path,
) -> Result<LiveExportResult> {
    let volumes = list_image_volumes(image_path)?;
    let volume = volumes
        .get(volume_index)
        .with_context(|| format!("volume index {volume_index} out of range"))?;
    let relative = file_path.trim_matches('/');

    let bytes: Vec<u8> = match volume.filesystem.as_str() {
        "EXT" => {
            let fs = open_ext4_superblock(image_path, volume.start_offset)?;
            ext4_read_file_bytes(&fs, &format!("/{relative}"))?
        }
        "FAT" => {
            let mut opened = open_disk_image(image_path)?;
            let slice =
                PartitionSlice::new(&mut *opened.reader, volume.start_offset, volume.size_bytes);
            let fs = fatfs::FileSystem::new(slice, fatfs::FsOptions::new())
                .context("opening FAT volume")?;
            let mut file = fs
                .root_dir()
                .open_file(relative)
                .with_context(|| format!("opening FAT file {relative}"))?;
            let total = file.seek(SeekFrom::End(0))?;
            if total > LIVE_EXPORT_MAX_BYTES {
                bail!(
                    "file is {total} bytes; live export is capped at {LIVE_EXPORT_MAX_BYTES} bytes - process the evidence to export it"
                );
            }
            file.seek(SeekFrom::Start(0))?;
            let mut data = Vec::with_capacity(total as usize);
            file.read_to_end(&mut data)?;
            data
        }
        "NTFS" => {
            let mut opened = open_disk_image(image_path)?;
            let mut slice =
                PartitionSlice::new(&mut *opened.reader, volume.start_offset, volume.size_bytes);
            let ntfs = ntfs::Ntfs::new(&mut slice).context("opening NTFS volume")?;
            let mut record = ntfs
                .root_directory(&mut slice)
                .context("opening NTFS root directory")?
                .file_record_number();
            let components: Vec<&str> = relative.split('/').filter(|v| !v.is_empty()).collect();
            let Some((file_name, dir_components)) = components.split_last() else {
                bail!("no file path given");
            };
            for component in dir_components {
                let children = collect_ntfs_dir_children(&ntfs, &mut slice, record)?.children;
                let child = children
                    .iter()
                    .find(|child| child.is_directory && child.name.eq_ignore_ascii_case(component))
                    .with_context(|| format!("directory not found: {component}"))?;
                record = child.file_record_number;
            }
            let children = collect_ntfs_dir_children(&ntfs, &mut slice, record)?.children;
            let target = children
                .iter()
                .find(|child| !child.is_directory && child.name.eq_ignore_ascii_case(file_name))
                .with_context(|| format!("file not found: {file_name}"))?;
            if target.size_bytes > LIVE_EXPORT_MAX_BYTES {
                bail!(
                    "file is {} bytes; live export is capped at {LIVE_EXPORT_MAX_BYTES} bytes - process the evidence to export it",
                    target.size_bytes
                );
            }
            read_ntfs_file_record_bytes(
                &ntfs,
                &mut slice,
                target.file_record_number,
                target.size_bytes as usize,
            )?
        }
        other => bail!("live export is not supported for {other} volumes"),
    };

    if bytes.len() as u64 > LIVE_EXPORT_MAX_BYTES {
        bail!(
            "file is {} bytes; live export is capped at {LIVE_EXPORT_MAX_BYTES} bytes - process the evidence to export it",
            bytes.len()
        );
    }
    if let Some(parent) = output_path.parent() {
        fs::create_dir_all(parent)
            .with_context(|| format!("creating export folder {}", parent.display()))?;
    }
    write_new_file_atomically(output_path, &bytes)
        .with_context(|| format!("writing exported file {}", output_path.display()))?;
    let mut hasher = Sha256::new();
    hasher.update(&bytes);
    let sha256_hex = format!("{:x}", hasher.finalize());
    Ok(LiveExportResult {
        output_path: output_path.display().to_string(),
        bytes_written: bytes.len() as u64,
        total_size: bytes.len() as u64,
        sha256_hex,
    })
}

#[derive(Debug, Clone, Serialize)]
pub struct LiveTreeExportResult {
    pub output_dir: String,
    pub manifest_path: String,
    pub files_exported: u64,
    pub bytes_written: u64,
    pub directories_visited: u64,
    pub skipped: Vec<String>,
    pub skipped_count: u64,
    pub oversized_files_skipped: u64,
    pub protective_file_size_limit_bytes: u64,
    pub file_limit: Option<usize>,
    pub file_limit_reached: bool,
    pub truncated: bool,
}

const LIVE_TREE_EXPORT_MAX_SKIP_NOTES: usize = 100;
/// Corrupt directory cycles must not grow paths forever after removal of the
/// old breadth caps. This is a path-depth/cycle guard, not a directory-count
/// limit: any number of sibling directories remain traversable.
const LIVE_TREE_MAX_PATH_DEPTH: usize = 1_024;

fn normalize_optional_file_limit(max_files: Option<usize>) -> Option<usize> {
    max_files.filter(|limit| *limit != 0)
}

fn file_limit_allows(processed: u64, max_files: Option<usize>) -> bool {
    max_files
        .map(|limit| processed < u64::try_from(limit).unwrap_or(u64::MAX))
        .unwrap_or(true)
}

fn live_tree_depth_allowed(relative_parts: &[String]) -> bool {
    relative_parts.len() <= LIVE_TREE_MAX_PATH_DEPTH
}

struct TreeExportSink {
    output_root: PathBuf,
    canonical_output_root: Option<PathBuf>,
    manifest: String,
    files: u64,
    bytes: u64,
    dirs: u64,
    skipped: Vec<String>,
    skipped_count: u64,
    oversized_files_skipped: u64,
    max_files: Option<usize>,
    file_limit_reached: bool,
    truncated: bool,
    written: HashSet<PathBuf>,
}

impl TreeExportSink {
    fn new(output_root: &Path, max_files: Option<usize>) -> Self {
        Self::new_with_size_header(output_root, max_files, "size_bytes")
    }

    fn new_with_size_header(
        output_root: &Path,
        max_files: Option<usize>,
        size_header: &str,
    ) -> Self {
        Self {
            output_root: output_root.to_path_buf(),
            canonical_output_root: None,
            manifest: format!("relative_path,{size_header},sha256\r\n"),
            files: 0,
            bytes: 0,
            dirs: 0,
            skipped: Vec::new(),
            skipped_count: 0,
            oversized_files_skipped: 0,
            max_files: normalize_optional_file_limit(max_files),
            file_limit_reached: false,
            truncated: false,
            written: HashSet::new(),
        }
    }

    fn file_budget_left(&self) -> bool {
        file_limit_allows(self.files, self.max_files)
    }

    fn prepare_output_root(&mut self) -> Result<()> {
        fs::create_dir_all(&self.output_root)
            .with_context(|| format!("creating export folder {}", self.output_root.display()))?;
        let metadata = fs::symlink_metadata(&self.output_root).with_context(|| {
            format!(
                "reading export-folder metadata {}",
                self.output_root.display()
            )
        })?;
        if metadata.file_type().is_symlink() || !metadata.is_dir() {
            bail!(
                "export root must be a real directory, not a link or another file type: {}",
                self.output_root.display()
            );
        }
        self.canonical_output_root =
            Some(self.output_root.canonicalize().with_context(|| {
                format!("resolving export folder {}", self.output_root.display())
            })?);
        Ok(())
    }

    fn mark_file_limit_reached(&mut self) {
        self.file_limit_reached = true;
        self.truncated = true;
    }

    fn skip(&mut self, note: String) {
        self.skipped_count = self.skipped_count.saturating_add(1);
        self.truncated = true;
        if self.skipped.len() < LIVE_TREE_EXPORT_MAX_SKIP_NOTES {
            self.skipped.push(note);
        }
    }

    fn skip_oversized(&mut self, logical_path: &str, size: u64) {
        self.oversized_files_skipped = self.oversized_files_skipped.saturating_add(1);
        self.skip(format!(
            "{logical_path}: {size} bytes exceeds the protective per-file live export limit of {LIVE_EXPORT_MAX_BYTES} bytes"
        ));
    }

    fn unique_output_path(&mut self, rel_parts: &[String]) -> Result<PathBuf> {
        let canonical_root = self
            .canonical_output_root
            .as_ref()
            .context("export root was not prepared")?;
        let mut target = self.output_root.clone();
        let Some((file_name, directory_parts)) = rel_parts.split_last() else {
            bail!("exported file has no relative path components");
        };
        for part in directory_parts {
            target.push(sanitize_logical_segment(part));
            match fs::symlink_metadata(&target) {
                Ok(metadata) => {
                    if metadata.file_type().is_symlink() || !metadata.is_dir() {
                        bail!(
                            "export path component must be a real directory: {}",
                            target.display()
                        );
                    }
                }
                Err(error) if error.kind() == io::ErrorKind::NotFound => {
                    fs::create_dir(&target)
                        .with_context(|| format!("creating export folder {}", target.display()))?;
                }
                Err(error) => {
                    return Err(error).with_context(|| {
                        format!("reading export-folder metadata {}", target.display())
                    });
                }
            }
            let canonical = target
                .canonicalize()
                .with_context(|| format!("resolving export folder {}", target.display()))?;
            if !canonical.starts_with(canonical_root) {
                bail!(
                    "export path escaped the selected output directory: {}",
                    target.display()
                );
            }
        }
        target.push(sanitize_logical_segment(file_name));
        let mut unique = target.clone();
        let mut suffix = 2;
        while unique.exists() || !self.written.insert(unique.clone()) {
            unique = target.with_file_name(format!(
                "{}-{}",
                target
                    .file_name()
                    .map(|n| n.to_string_lossy().into_owned())
                    .unwrap_or_else(|| "file".to_string()),
                suffix
            ));
            suffix += 1;
        }
        if let Some(parent) = unique.parent() {
            let canonical = parent
                .canonicalize()
                .with_context(|| format!("resolving export folder {}", parent.display()))?;
            if !canonical.starts_with(canonical_root) {
                bail!(
                    "export destination escaped the selected output directory: {}",
                    unique.display()
                );
            }
        }
        Ok(unique)
    }

    fn append_manifest_row(&mut self, output_path: &Path, size: u64, sha256_hex: &str) {
        let rel = output_path
            .strip_prefix(&self.output_root)
            .unwrap_or(output_path)
            .display()
            .to_string();
        self.manifest.push_str(&format!(
            "\"{}\",{},{}\r\n",
            rel.replace('"', "\"\""),
            size,
            sha256_hex
        ));
    }

    fn write_file(&mut self, rel_parts: &[String], bytes: &[u8]) -> Result<()> {
        if bytes.len() as u64 > LIVE_EXPORT_MAX_BYTES {
            self.skip_oversized(&local_tree_note_path(rel_parts), bytes.len() as u64);
            return Ok(());
        }
        let unique = self.unique_output_path(rel_parts)?;
        write_new_file_atomically(&unique, bytes)
            .with_context(|| format!("writing exported file {}", unique.display()))?;
        let mut hasher = Sha256::new();
        hasher.update(bytes);
        let sha = format!("{:x}", hasher.finalize());
        self.append_manifest_row(&unique, bytes.len() as u64, &sha);
        self.files += 1;
        self.bytes += bytes.len() as u64;
        Ok(())
    }

    fn write_file_from_path(
        &mut self,
        rel_parts: &[String],
        source_path: &Path,
        expected_size: u64,
    ) -> Result<()> {
        if expected_size > LIVE_EXPORT_MAX_BYTES {
            self.skip_oversized(&local_tree_note_path(rel_parts), expected_size);
            return Ok(());
        }
        let unique = self.unique_output_path(rel_parts)?;
        let mut source = fs::File::open(source_path)
            .with_context(|| format!("opening evidence file {}", source_path.display()))?;
        let mut output = AtomicOutput::create(&unique)
            .with_context(|| format!("creating exported file {}", unique.display()))?;
        let mut hasher = Sha256::new();
        let mut buffer = vec![0_u8; 1024 * 1024];
        let mut written = 0_u64;
        loop {
            let read = source
                .read(&mut buffer)
                .with_context(|| format!("reading evidence file {}", source_path.display()))?;
            if read == 0 {
                break;
            }
            if written.saturating_add(read as u64) > LIVE_EXPORT_MAX_BYTES {
                self.skip_oversized(
                    &local_tree_note_path(rel_parts),
                    written.saturating_add(read as u64),
                );
                return Ok(());
            }
            output
                .write_all(&buffer[..read])
                .with_context(|| format!("writing exported file {}", unique.display()))?;
            hasher.update(&buffer[..read]);
            written += read as u64;
        }
        if written != expected_size {
            self.skip(format!(
                "{}: size changed during export (expected {}, read {}); no output was published",
                source_path.display(),
                expected_size,
                written
            ));
            return Ok(());
        }
        output
            .commit()
            .with_context(|| format!("publishing exported file {}", unique.display()))?;
        let sha = format!("{:x}", hasher.finalize());
        self.append_manifest_row(&unique, written, &sha);
        self.files += 1;
        self.bytes += written;
        Ok(())
    }

    fn finish(mut self) -> Result<LiveTreeExportResult> {
        if self.canonical_output_root.is_none() {
            self.prepare_output_root()?;
        }
        let mut manifest_path = self.output_root.join("kdft-manifest.csv");
        let mut suffix = 2_u64;
        while manifest_path.exists() || self.written.contains(&manifest_path) {
            manifest_path = self.output_root.join(format!("kdft-manifest-{suffix}.csv"));
            suffix = suffix.saturating_add(1);
        }
        write_new_file_atomically(&manifest_path, self.manifest.as_bytes())
            .with_context(|| format!("writing manifest {}", manifest_path.display()))?;
        if self.skipped_count > self.skipped.len() as u64 {
            self.skipped.push(format!(
                "... and {} more skipped items",
                self.skipped_count - self.skipped.len() as u64
            ));
        }
        Ok(LiveTreeExportResult {
            output_dir: self.output_root.display().to_string(),
            manifest_path: manifest_path.display().to_string(),
            files_exported: self.files,
            bytes_written: self.bytes,
            directories_visited: self.dirs,
            skipped: self.skipped,
            skipped_count: self.skipped_count,
            oversized_files_skipped: self.oversized_files_skipped,
            protective_file_size_limit_bytes: LIVE_EXPORT_MAX_BYTES,
            file_limit: self.max_files,
            file_limit_reached: self.file_limit_reached,
            truncated: self.truncated,
        })
    }
}

/// Recursive live export: copy a whole directory out of an attached disk
/// image (no indexing), preserving the folder structure under `output_root`
/// and writing a `kdft-manifest.csv` with per-file SHA-256. The filesystem is
/// opened once. `None`/`Some(0)` means unlimited files; a positive examiner
/// limit is honored exactly. Oversized or unreadable files are skipped and
/// make the result explicitly partial with bounded diagnostic samples.
pub fn export_image_tree(
    image_path: &Path,
    volume_index: usize,
    dir_path: &str,
    output_root: &Path,
    max_files: Option<usize>,
) -> Result<LiveTreeExportResult> {
    let volumes = list_image_volumes(image_path)?;
    let volume = volumes
        .get(volume_index)
        .with_context(|| format!("volume index {volume_index} out of range"))?;
    let relative = dir_path.trim_matches('/').to_string();
    let mut sink = TreeExportSink::new(output_root, max_files);
    sink.prepare_output_root()?;

    match volume.filesystem.as_str() {
        "EXT" => {
            let fs = open_ext4_superblock(image_path, volume.start_offset)?;
            let start = if relative.is_empty() {
                "/".to_string()
            } else {
                format!("/{relative}")
            };
            let mut stack: Vec<(String, Vec<String>)> = vec![(start, Vec::new())];
            let mut seen_directory_inodes = HashSet::new();
            seen_directory_inodes.insert(ext4_resolve_inode(&fs, &stack[0].0)?.number);
            while let Some((ext_path, rel_parts)) = stack.pop() {
                if !sink.file_budget_left() {
                    sink.mark_file_limit_reached();
                    break;
                }
                sink.dirs += 1;
                let children = match ext4_list_dir(&fs, &ext_path) {
                    Ok(children) => children,
                    Err(err) => {
                        sink.skip(format!("{ext_path}: {err}"));
                        continue;
                    }
                };
                for child in children {
                    if !sink.file_budget_left() {
                        sink.mark_file_limit_reached();
                        break;
                    }
                    let child_path = if ext_path == "/" {
                        format!("/{}", child.name)
                    } else {
                        format!("{ext_path}/{}", child.name)
                    };
                    let mut child_rel = rel_parts.clone();
                    child_rel.push(child.name.clone());
                    if child.is_dir {
                        if !live_tree_depth_allowed(&child_rel) {
                            sink.skip(format!(
                                "{child_path}: directory depth exceeds the {LIVE_TREE_MAX_PATH_DEPTH}-component corruption/cycle guard"
                            ));
                            continue;
                        }
                        if !seen_directory_inodes.insert(child.inode_number) {
                            sink.skip(format!(
                                "{child_path}: repeated ext directory inode {} skipped to prevent a cycle",
                                child.inode_number
                            ));
                            continue;
                        }
                        stack.push((child_path, child_rel));
                        continue;
                    }
                    if child.size > LIVE_EXPORT_MAX_BYTES {
                        sink.skip_oversized(&child_path, child.size);
                        continue;
                    }
                    match ext4_read_file_bytes(&fs, &child_path) {
                        Ok(bytes) => sink.write_file(&child_rel, &bytes)?,
                        Err(err) => sink.skip(format!("{child_path}: {err}")),
                    }
                }
            }
        }
        "FAT" => {
            let mut opened = open_disk_image(image_path)?;
            let slice =
                PartitionSlice::new(&mut *opened.reader, volume.start_offset, volume.size_bytes);
            let fs = fatfs::FileSystem::new(slice, fatfs::FsOptions::new())
                .context("opening FAT volume")?;
            let root = fs.root_dir();
            let mut stack: Vec<(String, Vec<String>)> = vec![(relative.clone(), Vec::new())];
            while let Some((fat_path, rel_parts)) = stack.pop() {
                if !sink.file_budget_left() {
                    sink.mark_file_limit_reached();
                    break;
                }
                sink.dirs += 1;
                let dir = if fat_path.is_empty() {
                    root.clone()
                } else {
                    match root.open_dir(&fat_path) {
                        Ok(dir) => dir,
                        Err(err) => {
                            sink.skip(format!("{fat_path}: {err}"));
                            continue;
                        }
                    }
                };
                for entry in dir.iter() {
                    if !sink.file_budget_left() {
                        sink.mark_file_limit_reached();
                        break;
                    }
                    let entry = match entry {
                        Ok(entry) => entry,
                        Err(err) => {
                            sink.skip(format!(
                                "{fat_path}: FAT directory entry could not be read: {err}"
                            ));
                            continue;
                        }
                    };
                    let name = entry.file_name();
                    if name == "." || name == ".." {
                        continue;
                    }
                    let child_path = if fat_path.is_empty() {
                        name.clone()
                    } else {
                        format!("{fat_path}/{name}")
                    };
                    let mut child_rel = rel_parts.clone();
                    child_rel.push(name.clone());
                    if entry.is_dir() {
                        if !live_tree_depth_allowed(&child_rel) {
                            sink.skip(format!(
                                "{child_path}: directory depth exceeds the {LIVE_TREE_MAX_PATH_DEPTH}-component corruption/cycle guard"
                            ));
                            continue;
                        }
                        stack.push((child_path, child_rel));
                        continue;
                    }
                    if entry.len() > LIVE_EXPORT_MAX_BYTES {
                        sink.skip_oversized(&child_path, entry.len());
                        continue;
                    }
                    let mut file = entry.to_file();
                    let mut bytes = Vec::with_capacity(entry.len() as usize);
                    match file.read_to_end(&mut bytes) {
                        Ok(_) => sink.write_file(&child_rel, &bytes)?,
                        Err(err) => sink.skip(format!("{child_path}: {err}")),
                    }
                }
            }
        }
        "NTFS" => {
            let mut opened = open_disk_image(image_path)?;
            let mut slice =
                PartitionSlice::new(&mut *opened.reader, volume.start_offset, volume.size_bytes);
            let ntfs = ntfs::Ntfs::new(&mut slice).context("opening NTFS volume")?;
            let mut record = ntfs
                .root_directory(&mut slice)
                .context("opening NTFS root directory")?
                .file_record_number();
            for component in relative.split('/').filter(|v| !v.is_empty()) {
                let children = collect_ntfs_dir_children(&ntfs, &mut slice, record)?.children;
                let child = children
                    .iter()
                    .find(|child| child.is_directory && child.name.eq_ignore_ascii_case(component))
                    .with_context(|| format!("directory not found: {component}"))?;
                record = child.file_record_number;
            }
            let mut stack: Vec<(u64, Vec<String>)> = vec![(record, Vec::new())];
            let mut seen_records: HashSet<u64> = HashSet::new();
            while let Some((dir_record, rel_parts)) = stack.pop() {
                if !sink.file_budget_left() {
                    sink.mark_file_limit_reached();
                    break;
                }
                if !seen_records.insert(dir_record) {
                    sink.skip(format!(
                        "NTFS directory record {dir_record} was already visited and was skipped to prevent a cycle"
                    ));
                    continue;
                }
                sink.dirs += 1;
                let children = match collect_ntfs_dir_children(&ntfs, &mut slice, dir_record) {
                    Ok(result) => {
                        for diagnostic in result.diagnostics.iter().take(8) {
                            sink.skip(format!("record {dir_record}: {diagnostic}"));
                        }
                        result.children
                    }
                    Err(err) => {
                        sink.skip(format!("record {dir_record}: {err}"));
                        continue;
                    }
                };
                for child in children {
                    if !sink.file_budget_left() {
                        sink.mark_file_limit_reached();
                        break;
                    }
                    let mut child_rel = rel_parts.clone();
                    child_rel.push(child.name.clone());
                    if child.is_directory {
                        if !live_tree_depth_allowed(&child_rel) {
                            sink.skip(format!(
                                "{}: directory depth exceeds the {LIVE_TREE_MAX_PATH_DEPTH}-component corruption/cycle guard",
                                child.name
                            ));
                            continue;
                        }
                        stack.push((child.file_record_number, child_rel));
                        continue;
                    }
                    if child.size_bytes > LIVE_EXPORT_MAX_BYTES {
                        sink.skip_oversized(&child.name, child.size_bytes);
                        continue;
                    }
                    match read_ntfs_file_record_bytes(
                        &ntfs,
                        &mut slice,
                        child.file_record_number,
                        child.size_bytes as usize,
                    ) {
                        Ok(bytes) => sink.write_file(&child_rel, &bytes)?,
                        Err(err) => sink.skip(format!("{}: {err}", child.name)),
                    }
                }
            }
        }
        other => bail!("live export is not supported for {other} volumes"),
    }

    sink.finish()
}

fn local_tree_note_path(parts: &[String]) -> String {
    if parts.is_empty() {
        "/".to_string()
    } else {
        format!("/{}", parts.join("/"))
    }
}

pub fn export_local_tree(
    case_path: &Path,
    evidence_id: i64,
    dir_path: &str,
    output_root: &Path,
    max_files: Option<usize>,
) -> Result<LiveTreeExportResult> {
    let source = read_local_live_evidence(case_path, evidence_id)?;
    if source.source_kind != "folder" {
        bail!("recursive live export is only available for folder evidence");
    }
    let (root, start) = resolve_local_folder_path(&source.source_path, dir_path)?;
    let metadata = fs::symlink_metadata(&start)
        .with_context(|| format!("reading evidence directory metadata {}", start.display()))?;
    if metadata.file_type().is_symlink() {
        bail!("live export does not follow symlinks: {}", start.display());
    }
    if !metadata.is_dir() {
        bail!("local live path is not a directory: {}", start.display());
    }

    let mut sink = TreeExportSink::new_with_size_header(output_root, max_files, "size");
    sink.prepare_output_root()?;
    let mut stack: Vec<(PathBuf, Vec<String>)> = vec![(start, Vec::new())];
    let mut seen_directories: HashSet<PathBuf> = HashSet::new();
    while let Some((dir, rel_parts)) = stack.pop() {
        if !sink.file_budget_left() {
            sink.mark_file_limit_reached();
            break;
        }
        let canonical_dir = match ensure_under_evidence_root(&root, &dir) {
            Ok(canonical) => canonical,
            Err(err) => {
                sink.skip(format!("{}: {err:#}", local_tree_note_path(&rel_parts)));
                continue;
            }
        };
        if !seen_directories.insert(canonical_dir.clone()) {
            sink.skip(format!(
                "{}: canonical directory was already visited and was skipped to prevent a cycle",
                local_tree_note_path(&rel_parts)
            ));
            continue;
        }
        let metadata = match fs::symlink_metadata(&canonical_dir) {
            Ok(metadata) => metadata,
            Err(err) => {
                sink.skip(format!("{}: {err}", local_tree_note_path(&rel_parts)));
                continue;
            }
        };
        if metadata.file_type().is_symlink() {
            sink.skip(format!(
                "{}: symlink skipped",
                local_tree_note_path(&rel_parts)
            ));
            continue;
        }
        if !metadata.is_dir() {
            sink.skip(format!(
                "{}: not a directory",
                local_tree_note_path(&rel_parts)
            ));
            continue;
        }
        sink.dirs += 1;
        let read_dir = match fs::read_dir(&canonical_dir) {
            Ok(read_dir) => read_dir,
            Err(err) => {
                sink.skip(format!("{}: {err}", local_tree_note_path(&rel_parts)));
                continue;
            }
        };
        for child in read_dir {
            if !sink.file_budget_left() {
                sink.mark_file_limit_reached();
                break;
            }
            let child = match child {
                Ok(child) => child,
                Err(err) => {
                    sink.skip(format!("{}: {err}", local_tree_note_path(&rel_parts)));
                    continue;
                }
            };
            let child_path = child.path();
            let name = child
                .file_name()
                .to_str()
                .map(str::to_string)
                .unwrap_or_else(|| child.file_name().to_string_lossy().into_owned());
            let mut child_rel = rel_parts.clone();
            child_rel.push(name);
            let child_note = local_tree_note_path(&child_rel);
            let metadata = match fs::symlink_metadata(&child_path) {
                Ok(metadata) => metadata,
                Err(err) => {
                    sink.skip(format!("{child_note}: {err}"));
                    continue;
                }
            };
            let file_type = metadata.file_type();
            if file_type.is_symlink() {
                sink.skip(format!("{child_note}: symlink skipped"));
                continue;
            }
            if file_type.is_dir() {
                if !live_tree_depth_allowed(&child_rel) {
                    sink.skip(format!(
                        "{child_note}: directory depth exceeds the {LIVE_TREE_MAX_PATH_DEPTH}-component corruption/cycle guard"
                    ));
                    continue;
                }
                match ensure_under_evidence_root(&root, &child_path) {
                    Ok(canonical) => stack.push((canonical, child_rel)),
                    Err(err) => sink.skip(format!("{child_note}: {err:#}")),
                }
                continue;
            }
            if !file_type.is_file() {
                sink.skip(format!("{child_note}: unsupported file type"));
                continue;
            }
            let size = metadata.len();
            if size > LIVE_EXPORT_MAX_BYTES {
                sink.skip_oversized(&child_note, size);
                continue;
            }
            let canonical = match ensure_under_evidence_root(&root, &child_path) {
                Ok(canonical) => canonical,
                Err(err) => {
                    sink.skip(format!("{child_note}: {err:#}"));
                    continue;
                }
            };
            if let Err(err) = sink.write_file_from_path(&child_rel, &canonical, size) {
                sink.skip(format!("{child_note}: {err:#}"));
            }
        }
        if sink.file_limit_reached {
            break;
        }
    }

    sink.finish()
}

/// Compatibility value for callers that used the former recursive-bookmark
/// default. Zero now means unlimited; there is no hidden default ceiling.
pub const RECURSIVE_FOLDER_BOOKMARK_DEFAULT_LIMIT: usize = 0;
/// Compatibility value for callers that used the former hard ceiling. Zero
/// now means unlimited; only a positive examiner-supplied value is a limit.
pub const RECURSIVE_FOLDER_BOOKMARK_LIMIT: usize = 0;

pub struct LiveTreeFileRef {
    pub relative_path: String,
    pub name: String,
    pub size_bytes: u64,
    pub created_utc: Option<String>,
    pub modified_utc: Option<String>,
    pub accessed_utc: Option<String>,
}

pub struct LiveTreeListResult {
    pub files: Vec<LiveTreeFileRef>,
    pub directories_visited: u64,
    pub skipped: Vec<String>,
    pub skipped_count: u64,
    pub file_limit: Option<usize>,
    pub file_limit_reached: bool,
    pub truncated: bool,
}

struct TreeListSink {
    files: Vec<LiveTreeFileRef>,
    dirs: u64,
    skipped: Vec<String>,
    skipped_count: u64,
    max_files: Option<usize>,
    file_limit_reached: bool,
    truncated: bool,
}

impl TreeListSink {
    fn new(max_files: usize) -> Self {
        Self {
            files: Vec::new(),
            dirs: 0,
            skipped: Vec::new(),
            skipped_count: 0,
            max_files: (max_files != 0).then_some(max_files),
            file_limit_reached: false,
            truncated: false,
        }
    }

    fn file_budget_left(&self) -> bool {
        file_limit_allows(self.files.len() as u64, self.max_files)
    }

    fn mark_file_limit_reached(&mut self) {
        self.file_limit_reached = true;
        self.truncated = true;
    }

    fn skip(&mut self, note: String) {
        self.skipped_count = self.skipped_count.saturating_add(1);
        self.truncated = true;
        if self.skipped.len() < LIVE_TREE_EXPORT_MAX_SKIP_NOTES {
            self.skipped.push(note);
        }
    }

    fn push(
        &mut self,
        rel_parts: &[String],
        size_bytes: u64,
        created_utc: Option<String>,
        modified_utc: Option<String>,
        accessed_utc: Option<String>,
    ) {
        let relative_path = rel_parts.join("/");
        let name = rel_parts.last().cloned().unwrap_or_default();
        self.files.push(LiveTreeFileRef {
            relative_path,
            name,
            size_bytes,
            created_utc,
            modified_utc,
            accessed_utc,
        });
    }

    fn finish(mut self) -> LiveTreeListResult {
        if self.skipped_count > self.skipped.len() as u64 {
            self.skipped.push(format!(
                "... and {} more skipped items",
                self.skipped_count - self.skipped.len() as u64
            ));
        }
        LiveTreeListResult {
            files: self.files,
            directories_visited: self.dirs,
            skipped: self.skipped,
            skipped_count: self.skipped_count,
            file_limit: self.max_files,
            file_limit_reached: self.file_limit_reached,
            truncated: self.truncated,
        }
    }
}

/// Recursively lists files under `dir_path` in one volume of a disk image, read
/// live (no indexing). Mirrors `export_image_tree`'s per-filesystem walk but
/// never reads file content - used to bulk-create bookmark items for
/// "Bookmark folder (recursive)" in live browse without the cost/side-effect of
/// a real export. `max_files == 0` is unlimited; positive values are explicit
/// examiner limits.
pub fn list_image_tree_files(
    image_path: &Path,
    volume_index: usize,
    dir_path: &str,
    max_files: usize,
) -> Result<LiveTreeListResult> {
    let volumes = list_image_volumes(image_path)?;
    let volume = volumes
        .get(volume_index)
        .with_context(|| format!("volume index {volume_index} out of range"))?;
    let relative = dir_path.trim_matches('/').to_string();
    let mut sink = TreeListSink::new(max_files);

    match volume.filesystem.as_str() {
        "EXT" => {
            let fs = open_ext4_superblock(image_path, volume.start_offset)?;
            let start = if relative.is_empty() {
                "/".to_string()
            } else {
                format!("/{relative}")
            };
            let mut stack: Vec<(String, Vec<String>)> = vec![(start, Vec::new())];
            let mut seen_directory_inodes = HashSet::new();
            seen_directory_inodes.insert(ext4_resolve_inode(&fs, &stack[0].0)?.number);
            while let Some((ext_path, rel_parts)) = stack.pop() {
                if !sink.file_budget_left() {
                    sink.mark_file_limit_reached();
                    break;
                }
                sink.dirs += 1;
                let children = match ext4_list_dir(&fs, &ext_path) {
                    Ok(children) => children,
                    Err(err) => {
                        sink.skip(format!("{ext_path}: {err}"));
                        continue;
                    }
                };
                for child in children {
                    if !sink.file_budget_left() {
                        sink.mark_file_limit_reached();
                        break;
                    }
                    let child_path = if ext_path == "/" {
                        format!("/{}", child.name)
                    } else {
                        format!("{ext_path}/{}", child.name)
                    };
                    let mut child_rel = rel_parts.clone();
                    child_rel.push(child.name.clone());
                    if child.is_dir {
                        if !live_tree_depth_allowed(&child_rel) {
                            sink.skip(format!(
                                "{child_path}: directory depth exceeds the {LIVE_TREE_MAX_PATH_DEPTH}-component corruption/cycle guard"
                            ));
                            continue;
                        }
                        if !seen_directory_inodes.insert(child.inode_number) {
                            sink.skip(format!(
                                "{child_path}: repeated ext directory inode {} skipped to prevent a cycle",
                                child.inode_number
                            ));
                            continue;
                        }
                        stack.push((child_path, child_rel));
                        continue;
                    }
                    sink.push(
                        &child_rel,
                        child.size,
                        child.btime_utc.or(child.ctime_utc),
                        child.mtime_utc,
                        child.atime_utc,
                    );
                }
            }
        }
        "FAT" => {
            let mut opened = open_disk_image(image_path)?;
            let slice =
                PartitionSlice::new(&mut *opened.reader, volume.start_offset, volume.size_bytes);
            let fs = fatfs::FileSystem::new(slice, fatfs::FsOptions::new())
                .context("opening FAT volume")?;
            let root = fs.root_dir();
            let mut stack: Vec<(String, Vec<String>)> = vec![(relative.clone(), Vec::new())];
            while let Some((fat_path, rel_parts)) = stack.pop() {
                if !sink.file_budget_left() {
                    sink.mark_file_limit_reached();
                    break;
                }
                sink.dirs += 1;
                let dir = if fat_path.is_empty() {
                    root.clone()
                } else {
                    match root.open_dir(&fat_path) {
                        Ok(dir) => dir,
                        Err(err) => {
                            sink.skip(format!("{fat_path}: {err}"));
                            continue;
                        }
                    }
                };
                for entry in dir.iter() {
                    if !sink.file_budget_left() {
                        sink.mark_file_limit_reached();
                        break;
                    }
                    let entry = match entry {
                        Ok(entry) => entry,
                        Err(err) => {
                            sink.skip(format!(
                                "{fat_path}: FAT directory entry could not be read: {err}"
                            ));
                            continue;
                        }
                    };
                    let name = entry.file_name();
                    if name == "." || name == ".." {
                        continue;
                    }
                    let child_path = if fat_path.is_empty() {
                        name.clone()
                    } else {
                        format!("{fat_path}/{name}")
                    };
                    let mut child_rel = rel_parts.clone();
                    child_rel.push(name.clone());
                    if entry.is_dir() {
                        if !live_tree_depth_allowed(&child_rel) {
                            sink.skip(format!(
                                "{child_path}: directory depth exceeds the {LIVE_TREE_MAX_PATH_DEPTH}-component corruption/cycle guard"
                            ));
                            continue;
                        }
                        stack.push((child_path, child_rel));
                        continue;
                    }
                    sink.push(
                        &child_rel,
                        entry.len(),
                        fatfs_datetime_to_rfc3339(&entry.created()),
                        fatfs_datetime_to_rfc3339(&entry.modified()),
                        fatfs_date_to_rfc3339(&entry.accessed()),
                    );
                }
            }
        }
        "NTFS" => {
            let mut opened = open_disk_image(image_path)?;
            let mut slice =
                PartitionSlice::new(&mut *opened.reader, volume.start_offset, volume.size_bytes);
            let ntfs = ntfs::Ntfs::new(&mut slice).context("opening NTFS volume")?;
            let mut record = ntfs
                .root_directory(&mut slice)
                .context("opening NTFS root directory")?
                .file_record_number();
            for component in relative.split('/').filter(|v| !v.is_empty()) {
                let children = collect_ntfs_dir_children(&ntfs, &mut slice, record)?.children;
                let child = children
                    .iter()
                    .find(|child| child.is_directory && child.name.eq_ignore_ascii_case(component))
                    .with_context(|| format!("directory not found: {component}"))?;
                record = child.file_record_number;
            }
            let mut stack: Vec<(u64, Vec<String>)> = vec![(record, Vec::new())];
            let mut seen_records: HashSet<u64> = HashSet::new();
            while let Some((dir_record, rel_parts)) = stack.pop() {
                if !sink.file_budget_left() {
                    sink.mark_file_limit_reached();
                    break;
                }
                if !seen_records.insert(dir_record) {
                    sink.skip(format!(
                        "NTFS directory record {dir_record} was already visited and was skipped to prevent a cycle"
                    ));
                    continue;
                }
                sink.dirs += 1;
                let children = match collect_ntfs_dir_children(&ntfs, &mut slice, dir_record) {
                    Ok(result) => {
                        for diagnostic in result.diagnostics.iter().take(8) {
                            sink.skip(format!("record {dir_record}: {diagnostic}"));
                        }
                        result.children
                    }
                    Err(err) => {
                        sink.skip(format!("record {dir_record}: {err}"));
                        continue;
                    }
                };
                for child in children {
                    if !sink.file_budget_left() {
                        sink.mark_file_limit_reached();
                        break;
                    }
                    let mut child_rel = rel_parts.clone();
                    child_rel.push(child.name.clone());
                    if child.is_directory {
                        if !live_tree_depth_allowed(&child_rel) {
                            sink.skip(format!(
                                "{}: directory depth exceeds the {LIVE_TREE_MAX_PATH_DEPTH}-component corruption/cycle guard",
                                child.name
                            ));
                            continue;
                        }
                        stack.push((child.file_record_number, child_rel));
                        continue;
                    }
                    sink.push(
                        &child_rel,
                        child.size_bytes,
                        child
                            .standard_creation_time_utc
                            .clone()
                            .or(child.creation_time_utc.clone()),
                        child
                            .standard_modification_time_utc
                            .clone()
                            .or(child.modification_time_utc.clone()),
                        child
                            .standard_access_time_utc
                            .clone()
                            .or(child.access_time_utc.clone()),
                    );
                }
            }
        }
        other => bail!("live browsing is not supported for {other} volumes"),
    }

    Ok(sink.finish())
}

/// Recursively lists files under `dir_path` for local-folder live evidence.
/// Mirrors `export_local_tree`'s walk but never reads file content. A zero
/// `max_files` is unlimited.
pub fn list_local_tree_files(
    case_path: &Path,
    evidence_id: i64,
    dir_path: &str,
    max_files: usize,
) -> Result<LiveTreeListResult> {
    let source = read_local_live_evidence(case_path, evidence_id)?;
    if source.source_kind != "folder" {
        bail!("recursive live listing is only available for folder evidence");
    }
    let (root, start) = resolve_local_folder_path(&source.source_path, dir_path)?;
    let metadata = fs::symlink_metadata(&start)
        .with_context(|| format!("reading evidence directory metadata {}", start.display()))?;
    if metadata.file_type().is_symlink() {
        bail!("live listing does not follow symlinks: {}", start.display());
    }
    if !metadata.is_dir() {
        bail!("local live path is not a directory: {}", start.display());
    }

    let start = ensure_under_evidence_root(&root, &start)
        .with_context(|| format!("resolving evidence directory {}", start.display()))?;
    let mut sink = TreeListSink::new(max_files);
    let mut stack: Vec<(PathBuf, Vec<String>)> = vec![(start.clone(), Vec::new())];
    let mut seen_directories = HashSet::new();
    seen_directories.insert(start);
    while let Some((dir, rel_parts)) = stack.pop() {
        if !sink.file_budget_left() {
            sink.mark_file_limit_reached();
            break;
        }
        let dir = match ensure_under_evidence_root(&root, &dir) {
            Ok(dir) => dir,
            Err(err) => {
                sink.skip(format!("{}: {err:#}", dir.display()));
                continue;
            }
        };
        let metadata = match fs::symlink_metadata(&dir) {
            Ok(metadata) => metadata,
            Err(err) => {
                sink.skip(format!("{}: {err}", dir.display()));
                continue;
            }
        };
        if metadata.file_type().is_symlink() {
            sink.skip(format!("{}: symbolic link not followed", dir.display()));
            continue;
        }
        if !metadata.is_dir() {
            sink.skip(format!("{}: expected a directory", dir.display()));
            continue;
        }
        sink.dirs += 1;
        let read_dir = match fs::read_dir(&dir) {
            Ok(read_dir) => read_dir,
            Err(err) => {
                sink.skip(format!("{}: {err}", dir.display()));
                continue;
            }
        };
        for child in read_dir {
            if !sink.file_budget_left() {
                sink.mark_file_limit_reached();
                break;
            }
            let child = match child {
                Ok(child) => child,
                Err(err) => {
                    sink.skip(format!(
                        "{}: directory entry could not be read: {err}",
                        dir.display()
                    ));
                    continue;
                }
            };
            let child_path = child.path();
            let name = child
                .file_name()
                .to_str()
                .map(str::to_string)
                .unwrap_or_else(|| child.file_name().to_string_lossy().into_owned());
            let mut child_rel = rel_parts.clone();
            child_rel.push(name);
            let child_note = child_rel.join("/");
            let metadata = match fs::symlink_metadata(&child_path) {
                Ok(metadata) => metadata,
                Err(err) => {
                    sink.skip(format!("{child_note}: {err}"));
                    continue;
                }
            };
            let file_type = metadata.file_type();
            if file_type.is_symlink() {
                sink.skip(format!("{child_note}: symbolic link not followed"));
                continue;
            }
            if file_type.is_dir() {
                if !live_tree_depth_allowed(&child_rel) {
                    sink.skip(format!(
                        "{child_note}: directory depth exceeds the {LIVE_TREE_MAX_PATH_DEPTH}-component corruption/cycle guard"
                    ));
                    continue;
                }
                match ensure_under_evidence_root(&root, &child_path) {
                    Ok(canonical) if seen_directories.insert(canonical.clone()) => {
                        stack.push((canonical, child_rel));
                    }
                    Ok(_) => sink.skip(format!(
                        "{child_note}: repeated canonical directory skipped to prevent a cycle"
                    )),
                    Err(err) => sink.skip(format!("{child_note}: {err:#}")),
                }
                continue;
            }
            if !file_type.is_file() {
                sink.skip(format!("{child_note}: unsupported file type"));
                continue;
            }
            sink.push(
                &child_rel,
                metadata.len(),
                system_time_rfc3339(metadata.created().ok()),
                system_time_rfc3339(metadata.modified().ok()),
                system_time_rfc3339(metadata.accessed().ok()),
            );
        }
        if sink.file_limit_reached {
            break;
        }
    }

    Ok(sink.finish())
}

#[derive(Debug, Serialize)]
pub struct RecursiveBookmarkResult {
    pub bookmark_id: i64,
    pub items_added: i64,
    pub total_candidates: i64,
    pub truncated: bool,
    pub skipped: Vec<String>,
    pub skipped_count: u64,
    pub file_limit: Option<usize>,
    pub file_limit_reached: bool,
    pub skipped_entry_ids: Vec<i64>,
}

/// Descendant (non-directory) entry ids under a folder's logical-path prefix,
/// bounded by `max_entries`. Backs "Bookmark folder (recursive)" in the
/// indexed Analyze view.
fn indexed_folder_descendant_entry_ids(
    conn: &Connection,
    case_id: i64,
    evidence_id: i64,
    folder_logical_path: &str,
    max_entries: usize,
) -> Result<(Vec<i64>, i64)> {
    let trimmed = folder_logical_path.trim().trim_end_matches('/');
    if !trimmed.is_empty() {
        let normalized = if trimmed.starts_with('/') {
            trimmed.to_string()
        } else {
            format!("/{trimmed}")
        };
        let exists: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM filesystem_entries
                 WHERE case_id = ?1 AND evidence_id = ?2 AND entry_kind = 'directory'
                   AND logical_path = ?3",
                params![case_id, evidence_id, normalized],
                |row| row.get(0),
            )
            .context("checking recursive bookmark folder exists")?;
        if exists == 0 {
            bail!("directory not found: {folder_logical_path}");
        }
    }
    let prefix = if folder_logical_path.ends_with('/') {
        folder_logical_path.to_string()
    } else {
        format!("{folder_logical_path}/")
    };
    let total: i64 = conn
        .query_row(
            "SELECT COUNT(*) FROM filesystem_entries
             WHERE case_id = ?1 AND evidence_id = ?2 AND entry_kind != 'directory'
               AND substr(logical_path, 1, length(?3)) = ?3",
            params![case_id, evidence_id, prefix],
            |row| row.get(0),
        )
        .context("counting descendant entries for recursive folder bookmark")?;
    let mut stmt = conn.prepare(
        "SELECT id FROM filesystem_entries
         WHERE case_id = ?1 AND evidence_id = ?2 AND entry_kind != 'directory'
           AND substr(logical_path, 1, length(?3)) = ?3
         ORDER BY logical_path, id
         LIMIT ?4",
    )?;
    let sql_limit = i64::try_from(max_entries).unwrap_or(i64::MAX);
    let ids = stmt
        .query_map(params![case_id, evidence_id, prefix, sql_limit], |row| {
            row.get::<_, i64>(0)
        })?
        .collect::<std::result::Result<Vec<_>, _>>()
        .context("listing descendant entries for recursive folder bookmark")?;
    Ok((ids, total))
}

/// "Bookmark folder (recursive)" for the indexed Analyze view: bulk-adds every
/// descendant file under `folder_logical_path` to `bookmark_id` in one
/// transaction (reuses `bulk_add_bookmark_items`, so this has the same ~ms/item
/// cost as the existing bulk-bookmark-selected fix, not the old N-HTTP-request
/// shape).
pub fn bookmark_indexed_folder_recursive(
    case_path: &Path,
    bookmark_id: i64,
    evidence_id: i64,
    folder_logical_path: &str,
    max_entries: usize,
) -> Result<RecursiveBookmarkResult> {
    // Zero is the public unlimited sentinel. A positive limit is an explicit
    // examiner request and is honored exactly; this function adds no ceiling.
    let file_limit = (max_entries != 0).then_some(max_entries);
    let max_entries = file_limit.unwrap_or(usize::MAX);
    let (entry_ids, total_candidates) = {
        let conn = open_existing_case(case_path)?;
        let case_id = active_case_id(&conn)?;
        ensure_evidence_source(&conn, case_id, evidence_id)?;
        indexed_folder_descendant_entry_ids(
            &conn,
            case_id,
            evidence_id,
            folder_logical_path,
            max_entries,
        )?
    };
    let truncated = total_candidates > entry_ids.len() as i64;
    let bulk = bulk_add_bookmark_items(case_path, bookmark_id, &entry_ids)?;
    Ok(RecursiveBookmarkResult {
        bookmark_id: bulk.bookmark_id,
        items_added: bulk.items_added,
        total_candidates,
        truncated,
        skipped: Vec::new(),
        skipped_count: 0,
        file_limit,
        file_limit_reached: truncated,
        skipped_entry_ids: bulk.skipped_entry_ids,
    })
}

/// Bulk-inserts one bookmark item per file from a recursive live-tree listing,
/// in a single transaction (same rationale as `bulk_add_bookmark_items` - avoid
/// N per-item DB round trips). Each item's `item_ref_json` includes `metadata`
/// and `size_bytes` up front so report rendering's `enrich_live_bookmark_item`
/// does not need to re-open the live source once per item.
fn live_volume_numbering(
    source_kind: &str,
    source_path: &str,
    requested_volume_index: usize,
) -> Result<(usize, Option<usize>)> {
    if source_kind != "image" {
        return Ok((requested_volume_index, None));
    }
    let volumes = list_image_volumes(Path::new(source_path))?;
    let volume = volumes
        .get(requested_volume_index)
        .with_context(|| format!("volume index {requested_volume_index} out of range"))?;
    Ok((
        volume.volume_index_zero_based,
        volume.partition_number_one_based,
    ))
}

#[allow(clippy::too_many_arguments)]
pub fn bulk_add_live_bookmark_items(
    case_path: &Path,
    bookmark_id: i64,
    evidence_id: i64,
    source_kind: &str,
    source_path: &str,
    volume: usize,
    volume_name: &str,
    filesystem: &str,
    files: &[LiveTreeFileRef],
) -> Result<BulkBookmarkItemsResult> {
    let (volume_index_zero_based, partition_number_one_based) =
        live_volume_numbering(source_kind, source_path, volume)?;
    let mut conn = open_existing_case(case_path)?;
    let case_id = active_case_id(&conn)?;
    let tx = conn.transaction_with_behavior(TransactionBehavior::Immediate)?;
    let actor = audit_actor(&tx, case_id)?;
    ensure_bookmark(&tx, case_id, bookmark_id)?;
    ensure_evidence_source(&tx, case_id, evidence_id)?;

    let mut next_order: i64 = tx.query_row(
        "SELECT COALESCE(MAX(item_order), 0) FROM bookmark_items WHERE bookmark_id = ?1",
        params![bookmark_id],
        |row| row.get(0),
    )?;
    let mut items_added: i64 = 0;
    for file in files {
        next_order = next_order.saturating_add(10);
        let logical_path = format!("[vol {volume}] {}", file.relative_path);
        let file_extension = file_extension_of(&file.name).unwrap_or_default();
        let item_ref_value = serde_json::json!({
            "kind": "live_file",
            "entry_kind": "file",
            "evidence_id": evidence_id,
            "logical_path": logical_path,
            "relative_path": file.relative_path,
            "display_name": file.name,
            "volume": volume,
            "volume_index_zero_based": volume_index_zero_based,
            "partition_number_one_based": partition_number_one_based,
            "path": file.relative_path,
            "volume_name": volume_name,
            "filesystem": filesystem,
            "size_bytes": file.size_bytes,
            "is_deleted": false,
            "symlink": false,
            "file_extension": file_extension,
            "created_utc": file.created_utc,
            "modified_utc": file.modified_utc,
            "accessed_utc": file.accessed_utc,
            "metadata": {
                "source_kind": source_kind,
                "source_path": source_path,
                "volume_index": volume,
                "volume_index_zero_based": volume_index_zero_based,
                "partition_number_one_based": partition_number_one_based,
            }
        });
        let data_preview = format!("Live file, {} bytes", file.size_bytes);
        let item_ref_json = item_ref_value.to_string();
        tx.execute(
            "INSERT INTO bookmark_items(
                 bookmark_id, evidence_id, entry_id, item_order, display_name, logical_path,
                 selection_offset, selection_length, data_preview, item_ref_json
             ) VALUES (?1, ?2, NULL, ?3, ?4, ?5, NULL, NULL, ?6, ?7)",
            params![
                bookmark_id,
                evidence_id,
                next_order,
                file.name,
                logical_path,
                data_preview,
                item_ref_json,
            ],
        )?;
        items_added += 1;
    }
    tx.execute(
        "INSERT INTO audit_events(case_id, event_type, actor, object_type, object_id, details_json)
         VALUES (?1, 'bookmark.item.bulk_add_live', ?2, 'bookmark', ?3,
                 json_object('items_added', ?4, 'source_kind', ?5,
                             'volume_index_zero_based', ?6,
                             'partition_number_one_based', ?7))",
        params![
            case_id,
            actor,
            bookmark_id,
            items_added,
            source_kind,
            i64::try_from(volume_index_zero_based).unwrap_or(i64::MAX),
            partition_number_one_based.and_then(|value| i64::try_from(value).ok()),
        ],
    )?;
    tx.commit()?;
    Ok(BulkBookmarkItemsResult {
        bookmark_id,
        items_added,
        skipped_entry_ids: Vec::new(),
    })
}

/// "Bookmark folder (recursive)" for live browse: walks the live tree (without
/// byte reads) then bulk-inserts one bookmark item per file found. Traversal is
/// unlimited unless the examiner supplied a positive file limit.
#[allow(clippy::too_many_arguments)]
pub fn bookmark_live_folder_recursive(
    case_path: &Path,
    bookmark_id: i64,
    evidence_id: i64,
    source_kind: &str,
    source_path: &str,
    volume: usize,
    volume_name: &str,
    filesystem: &str,
    listing: LiveTreeListResult,
) -> Result<RecursiveBookmarkResult> {
    let total_candidates = listing.files.len() as i64;
    let truncated = listing.truncated;
    let bulk = bulk_add_live_bookmark_items(
        case_path,
        bookmark_id,
        evidence_id,
        source_kind,
        source_path,
        volume,
        volume_name,
        filesystem,
        &listing.files,
    )?;
    Ok(RecursiveBookmarkResult {
        bookmark_id: bulk.bookmark_id,
        items_added: bulk.items_added,
        total_candidates,
        truncated,
        skipped: listing.skipped,
        skipped_count: listing.skipped_count,
        file_limit: listing.file_limit,
        file_limit_reached: listing.file_limit_reached,
        skipped_entry_ids: bulk.skipped_entry_ids,
    })
}

/// Audit trail for a recursive live folder export.
fn evidence_live_volume_numbering(
    conn: &Connection,
    case_id: i64,
    evidence_id: i64,
    requested_volume_index: usize,
) -> Result<(usize, Option<usize>)> {
    let (source_kind, source_path): (String, String) = conn
        .query_row(
            "SELECT source_kind, source_path FROM evidence_sources
             WHERE case_id = ?1 AND id = ?2",
            params![case_id, evidence_id],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .context("evidence source not found for live-volume audit")?;
    live_volume_numbering(&source_kind, &source_path, requested_volume_index)
}

pub fn record_live_tree_export(
    case_path: &Path,
    evidence_id: i64,
    volume_index: usize,
    dir_path: &str,
    result: &LiveTreeExportResult,
) -> Result<()> {
    let mut conn = open_existing_case(case_path)?;
    let case_id = active_case_id(&conn)?;
    let (volume_index_zero_based, partition_number_one_based) =
        evidence_live_volume_numbering(&conn, case_id, evidence_id, volume_index)?;
    let tx = conn.transaction_with_behavior(TransactionBehavior::Immediate)?;
    let actor = audit_actor(&tx, case_id)?;
    tx.execute(
        "INSERT INTO audit_events(case_id, event_type, actor, object_type, object_id, details_json)
         VALUES (?1, 'live.export_tree', ?2, 'evidence', ?3,
                 json_object('volume', ?4,
                             'volume_index_zero_based', ?5,
                             'partition_number_one_based', ?6,
                             'dir_path', ?7, 'output_dir', ?8,
                             'files_exported', ?9, 'bytes_written', ?10,
                             'skipped', ?11, 'oversized_files_skipped', ?12,
                             'protective_file_size_limit_bytes', ?13,
                             'file_limit', ?14, 'file_limit_reached', ?15,
                             'truncated', ?16, 'manifest_path', ?17))",
        params![
            case_id,
            actor,
            evidence_id,
            volume_index as i64,
            i64::try_from(volume_index_zero_based).unwrap_or(i64::MAX),
            partition_number_one_based.and_then(|value| i64::try_from(value).ok()),
            dir_path,
            result.output_dir,
            result.files_exported as i64,
            result.bytes_written as i64,
            result.skipped_count as i64,
            result.oversized_files_skipped as i64,
            i64::try_from(result.protective_file_size_limit_bytes).unwrap_or(i64::MAX),
            result
                .file_limit
                .and_then(|value| i64::try_from(value).ok()),
            result.file_limit_reached,
            result.truncated,
            result.manifest_path
        ],
    )?;
    tx.commit()?;
    Ok(())
}

