/// Result of comparing a file's header against the signature table.
struct SignatureFinding {
    /// One of: match, alias, mismatch, unknown, no_extension.
    status: &'static str,
    /// Detected type label, if any signature matched the header.
    detected_label: Option<&'static str>,
    detected_description: Option<&'static str>,
    detected_category: Option<&'static str>,
    /// Lowercase file extension parsed from the name (no dot), if present.
    extension: Option<String>,
    expected_label: Option<&'static str>,
    detection_basis: Option<&'static str>,
    mismatch_basis: Option<&'static str>,
    reason: Option<&'static str>,
}

struct DetectedFileType {
    label: &'static str,
    description: &'static str,
    category: &'static str,
    extensions: &'static [&'static str],
    basis: &'static str,
}

/// Parse the lowercase extension (without the dot) from a file name. Returns `None` for names with
/// no extension, names that are all extension (dotfiles like `.bashrc`), or NTFS ADS names where
/// the stream part follows a colon.
fn file_extension_of(name: &str) -> Option<String> {
    // For ADS rows like `file.txt:Zone.Identifier`, judge the base name before the stream colon.
    let base = name.split(':').next().unwrap_or(name);
    let dot = base.rfind('.')?;
    // A leading-dot name (dotfile) with no other dot has no real extension.
    if dot == 0 {
        return None;
    }
    let ext = &base[dot + 1..];
    if ext.is_empty() || ext.len() > 12 || !ext.chars().all(|c| c.is_ascii_alphanumeric()) {
        return None;
    }
    Some(ext.to_ascii_lowercase())
}

/// Detect a file's true type from its header bytes and compare against its extension.
#[cfg(test)]
fn evaluate_signature(name: &str, header: &[u8]) -> SignatureFinding {
    evaluate_signature_with_completeness(name, header, true)
}

fn evaluate_signature_with_completeness(
    name: &str,
    header: &[u8],
    window_complete: bool,
) -> SignatureFinding {
    let extension = file_extension_of(name);
    let catalog = FILE_SIGNATURES.iter().find(|signature| {
        if signature.label == "PDF" {
            return header
                .windows(signature.magic.len())
                .take(
                    1024_usize
                        .saturating_sub(signature.magic.len())
                        .saturating_add(1),
                )
                .any(|window| window == signature.magic);
        }
        let end = signature.offset.saturating_add(signature.magic.len());
        header.len() >= end && &header[signature.offset..end] == signature.magic
    });
    let detected = catalog
        .map(|signature| DetectedFileType {
            label: signature.label,
            description: signature.description,
            category: signature.category,
            extensions: signature.extensions,
            basis: "magic",
        })
        .or_else(|| {
            is_high_confidence_csv(header, window_complete).then_some(DetectedFileType {
                label: "CSV",
                description: "UTF-8 comma-delimited text with a consistent row structure",
                category: "Documents and Office",
                extensions: &["csv"],
                basis: "content_heuristic",
            })
        });
    let expected_label = extension
        .as_deref()
        .and_then(|value| (value == "pdf").then_some("PDF"));

    let status = match (&extension, detected.as_ref()) {
        (None, _) => "no_extension",
        (Some(ext), None) if ext == "pdf" && window_complete => "mismatch",
        (Some(_), None) => "unknown",
        (Some(ext), Some(detected)) => {
            if detected.extensions.contains(&ext.as_str()) {
                // Canonical extension for this format.
                if Some(ext.as_str()) == detected.extensions.first().copied() {
                    "match"
                } else {
                    // Legitimate alternate extension for the same container/format.
                    "alias"
                }
            } else if ext == "pdf" || detected.basis == "magic" {
                "mismatch"
            } else {
                // Text heuristics are deliberately not strict for arbitrary
                // names such as .dat or .txt.
                "unknown"
            }
        }
    };
    let mismatch_basis = match (status, detected.as_ref()) {
        ("mismatch", Some(_)) => Some("detected_type_conflicts_with_extension"),
        ("mismatch", None) => Some("expected_signature_absent"),
        _ => None,
    };
    let reason = match status {
        "match" => Some("detected content type matches the canonical extension"),
        "alias" => Some("detected content type permits this alternate extension"),
        "mismatch" if detected.is_some() => {
            Some("detected content type conflicts with the file extension")
        }
        "mismatch" => Some("the complete header window lacks the required PDF signature"),
        "unknown" if detected.is_some() => Some(
            "a non-strict content heuristic was detected but is not enforced for this extension",
        ),
        "unknown" => Some("no supported content signature was detected"),
        "no_extension" => Some("the file name has no comparable extension"),
        _ => None,
    };

    SignatureFinding {
        status,
        detected_label: detected.as_ref().map(|value| value.label),
        detected_description: detected.as_ref().map(|value| value.description),
        detected_category: detected.as_ref().map(|value| value.category),
        extension,
        expected_label,
        detection_basis: detected.as_ref().map(|value| value.basis),
        mismatch_basis,
        reason,
    }
}

fn is_high_confidence_csv(bytes: &[u8], sample_complete: bool) -> bool {
    let bytes = bytes.strip_prefix(&[0xEF, 0xBB, 0xBF]).unwrap_or(bytes);
    if bytes.is_empty()
        || bytes
            .iter()
            .any(|byte| *byte == 0 || (*byte < 0x20 && !matches!(*byte, b'\r' | b'\n' | b'\t')))
    {
        return false;
    }
    let Ok(text) = std::str::from_utf8(bytes) else {
        return false;
    };
    let final_line_complete = sample_complete || text.ends_with('\n') || text.ends_with('\r');
    let mut rows = text
        .lines()
        .filter(|line| !line.trim().is_empty())
        .collect::<Vec<_>>();
    if !final_line_complete {
        rows.pop();
    }
    if rows.len() < 3 {
        return false;
    }
    let Some(expected_fields) = csv_field_count(rows[0]) else {
        return false;
    };
    expected_fields >= 2
        && rows
            .iter()
            .skip(1)
            .all(|row| csv_field_count(row) == Some(expected_fields))
}

fn csv_field_count(line: &str) -> Option<usize> {
    let bytes = line.as_bytes();
    let mut quoted = false;
    let mut fields = 1_usize;
    let mut index = 0_usize;
    while index < bytes.len() {
        match bytes[index] {
            b'"' if quoted && bytes.get(index + 1) == Some(&b'"') => {
                index += 2;
                continue;
            }
            b'"' => quoted = !quoted,
            b',' if !quoted => fields = fields.saturating_add(1),
            _ => {}
        }
        index += 1;
    }
    (!quoted).then_some(fields)
}

fn enrich_entry_path_identity(entry: &FilesystemEntry, item_ref: &mut serde_json::Value) {
    let Some(object) = item_ref.as_object_mut() else {
        return;
    };
    object.insert(
        "internal_path_key".to_string(),
        serde_json::json!(entry.internal_path_key),
    );
    object.insert(
        "source_path_exact".to_string(),
        serde_json::json!(entry.source_path_exact),
    );
}

fn enrich_bookmark_partition_numbering(
    conn: &Connection,
    case_id: i64,
    evidence_id: Option<i64>,
    item_ref: &mut serde_json::Value,
) -> Result<()> {
    let Some(object) = item_ref.as_object_mut() else {
        return Ok(());
    };
    if object.contains_key("volume_index_zero_based")
        || object.contains_key("partition_number_one_based")
    {
        return Ok(());
    }
    let Some(requested_volume_index) = ["volume", "volume_index", "partition_index"]
        .into_iter()
        .find_map(|key| object.get(key).and_then(|value| value.as_u64()))
        .and_then(|value| usize::try_from(value).ok())
    else {
        return Ok(());
    };
    let Some(evidence_id) = evidence_id else {
        return Ok(());
    };
    let (source_kind, source_path): (String, String) = conn.query_row(
        "SELECT source_kind, source_path FROM evidence_sources
         WHERE case_id = ?1 AND id = ?2",
        params![case_id, evidence_id],
        |row| Ok((row.get(0)?, row.get(1)?)),
    )?;
    let (volume_index_zero_based, partition_number_one_based) =
        live_volume_numbering(&source_kind, &source_path, requested_volume_index)?;
    object.insert(
        "volume_index_zero_based".to_string(),
        serde_json::json!(volume_index_zero_based),
    );
    object.insert(
        "partition_number_one_based".to_string(),
        serde_json::json!(partition_number_one_based),
    );
    Ok(())
}

fn enrich_index_job_provenance(
    conn: &Connection,
    entry: &FilesystemEntry,
    item_ref: &mut serde_json::Value,
) -> Result<()> {
    let Some(job_id) = entry.discovered_by_job_id else {
        return Ok(());
    };
    let provenance = conn
        .query_row(
            "SELECT job_type, status,
                    CAST(COALESCE(
                        json_extract(parameters_json, '$.max_entries'),
                        json_extract(parameters_json, '$.max_visits')
                    ) AS INTEGER),
                    COALESCE(
                        CAST(json_extract(parameters_json, '$.entries_indexed') AS INTEGER),
                        (SELECT COUNT(*) FROM filesystem_entries
                         WHERE discovered_by_job_id = evidence_jobs.id)
                    ),
                    error
             FROM evidence_jobs
             WHERE id = ?1",
            params![job_id],
            |row| {
                Ok((
                    row.get::<_, String>(0)?,
                    row.get::<_, String>(1)?,
                    row.get::<_, Option<i64>>(2)?,
                    row.get::<_, Option<i64>>(3)?,
                    row.get::<_, Option<String>>(4)?,
                ))
            },
        )
        .optional()?;
    let Some((job_type, status, requested_limit, entries_indexed, reason)) = provenance else {
        return Ok(());
    };
    let Some(object) = item_ref.as_object_mut() else {
        return Ok(());
    };
    let coverage = processing_coverage_text(
        Some(&job_type),
        Some(&status),
        requested_limit,
        entries_indexed,
        reason.as_deref(),
    );
    object.insert("index_job_id".to_string(), serde_json::json!(job_id));
    object.insert(
        "index_job_type".to_string(),
        serde_json::json!(job_type.as_str()),
    );
    object.insert(
        "index_job_status".to_string(),
        serde_json::json!(status.as_str()),
    );
    object.insert(
        "index_requested_entry_limit".to_string(),
        serde_json::json!(requested_limit),
    );
    object.insert(
        "index_entries_indexed".to_string(),
        serde_json::json!(entries_indexed),
    );
    object.insert(
        "index_truncation_reason".to_string(),
        serde_json::json!(reason.as_deref()),
    );
    object.insert(
        "index_processing_coverage".to_string(),
        serde_json::json!(coverage),
    );
    Ok(())
}

fn apply_schema(conn: &Connection) -> Result<()> {
    conn.execute_batch(INITIAL_SCHEMA)
        .context("applying initial schema")?;
    conn.pragma_update(None, "application_id", KDFT_APPLICATION_ID)
        .context("marking the SQLite database as a KDFT case")?;
    apply_schema_migrations(conn)
}

fn apply_schema_migrations(conn: &Connection) -> Result<()> {
    ensure_filesystem_entries_content_head_column(conn)?;
    ensure_filesystem_entry_text_segments_table(conn)?;
    ensure_filesystem_entry_binary_blobs_table(conn)?;
    ensure_cases_metadata_columns(conn)?;
    ensure_evidence_hash_columns(conn)?;
    ensure_installed_resources_config_column(conn)?;
    ensure_filesystem_entries_indexes(conn)
}

fn ensure_filesystem_entry_text_segments_table(conn: &Connection) -> Result<()> {
    conn.execute_batch(
        "CREATE TABLE IF NOT EXISTS filesystem_entry_text_segments (
             entry_id INTEGER NOT NULL REFERENCES filesystem_entries(id) ON DELETE CASCADE,
             parser_name TEXT NOT NULL,
             segment_index INTEGER NOT NULL,
             part_name TEXT NOT NULL,
             content BLOB NOT NULL,
             content_encoding TEXT NOT NULL,
             PRIMARY KEY(entry_id, parser_name, segment_index)
         );
         CREATE INDEX IF NOT EXISTS ix_filesystem_entry_text_segments_entry
         ON filesystem_entry_text_segments(entry_id);",
    )
    .context("ensuring parser-derived filesystem text segment storage")
}

fn ensure_filesystem_entry_binary_blobs_table(conn: &Connection) -> Result<()> {
    conn.execute_batch(
        "CREATE TABLE IF NOT EXISTS filesystem_entry_binary_blobs (
             entry_id INTEGER PRIMARY KEY REFERENCES filesystem_entries(id) ON DELETE CASCADE,
             parser_name TEXT NOT NULL,
             blob_kind TEXT NOT NULL,
             content BLOB NOT NULL,
             sha256_hex TEXT NOT NULL,
             size_bytes INTEGER NOT NULL
         );",
    )
    .context("ensuring parser-derived filesystem binary blob storage")
}

fn ensure_installed_resources_config_column(conn: &Connection) -> Result<()> {
    // Preserve compatibility with early case databases while new databases
    // use the neutral `config_file_name` name. These legacy strings are used
    // only to recognize and migrate KDFT-owned seed data, never examiner data.
    let legacy_column = "encase_file_name";
    let legacy_versions = ["encase-6.11-baseline", "ecase-6.11-baseline"];
    let mut stmt = conn
        .prepare("PRAGMA table_info(installed_resources)")
        .context("reading installed_resources columns")?;
    let existing = stmt
        .query_map([], |row| row.get::<_, String>(1))?
        .collect::<std::result::Result<Vec<_>, _>>()
        .context("collecting installed_resources columns")?;
    if existing.iter().any(|column| column == legacy_column) {
        conn.execute(
            &format!(
                "ALTER TABLE installed_resources RENAME COLUMN {legacy_column} TO config_file_name"
            ),
            [],
        )
        .context("renaming installed_resources.config_file_name column")?;
    }
    // Refresh the tool-seeded resource rows (not examiner data) that older
    // cases created with the legacy vendor wording. Avoid an unconditional
    // UPDATE here: open_existing_case runs for read-only UI refreshes too, and
    // taking a write lock on every refresh can collide with concurrent tabs.
    let has_legacy_wording = conn
        .query_row(
            "SELECT EXISTS(
                SELECT 1 FROM installed_resources
                 WHERE version IN (?1, ?2)
                 LIMIT 1
             )",
            params![legacy_versions[0], legacy_versions[1]],
            |row| row.get::<_, i64>(0),
        )
        .context("checking seeded installed_resources wording")?
        != 0;
    if has_legacy_wording {
        conn.execute(
            "UPDATE installed_resources
             SET version = 'kdft-v1-baseline',
                 notes = CASE
                     WHEN resource_kind = 'report_template' THEN 'Built-in KDFT report template.'
                     ELSE 'Built-in KDFT configuration resource.'
                 END
             WHERE version IN (?1, ?2)",
            params![legacy_versions[0], legacy_versions[1]],
        )
        .context("refreshing seeded installed_resources wording")?;
    }
    Ok(())
}

fn ensure_filesystem_entries_indexes(conn: &Connection) -> Result<()> {
    // Per-evidence entry counts (report, dashboard) must not scan the wide
    // UNIQUE(evidence_id, logical_path) index on large cases.
    //
    // The parent/entry/job FK indexes make ON DELETE cascades linear: without
    // them, removing an evidence source with N indexed entries scans the whole
    // entries table once per deleted row (parent_id ON DELETE SET NULL) -
    // O(N^2), which on a 359k-entry case never finishes and holds the write
    // lock ("database is locked" for every other action).
    for (name, sql) in [
        (
            "ix_filesystem_entries_case_evidence",
            "CREATE INDEX ix_filesystem_entries_case_evidence
             ON filesystem_entries(case_id, evidence_id)",
        ),
        (
            "ix_filesystem_entries_parent",
            "CREATE INDEX ix_filesystem_entries_parent
             ON filesystem_entries(parent_id)",
        ),
        (
            "ix_filesystem_entries_job",
            "CREATE INDEX ix_filesystem_entries_job
             ON filesystem_entries(discovered_by_job_id)",
        ),
        (
            "ix_bookmark_items_entry",
            "CREATE INDEX ix_bookmark_items_entry
             ON bookmark_items(entry_id)",
        ),
    ] {
        if !sqlite_index_exists(conn, name)? {
            conn.execute(sql, [])
                .with_context(|| format!("creating SQLite index {name}"))?;
        }
    }
    Ok(())
}

fn sqlite_index_exists(conn: &Connection, name: &str) -> Result<bool> {
    conn.query_row(
        "SELECT EXISTS(
            SELECT 1 FROM sqlite_master
            WHERE type = 'index' AND name = ?1
            LIMIT 1
        )",
        params![name],
        |row| row.get::<_, i64>(0),
    )
    .map(|value| value != 0)
    .with_context(|| format!("checking SQLite index {name}"))
}

fn ensure_evidence_hash_columns(conn: &Connection) -> Result<()> {
    let mut stmt = conn
        .prepare("PRAGMA table_info(evidence_sources)")
        .context("reading evidence_sources columns")?;
    let existing = stmt
        .query_map([], |row| row.get::<_, String>(1))?
        .collect::<std::result::Result<Vec<_>, _>>()
        .context("collecting evidence_sources columns")?;
    for column in [
        "sha256_hex",
        "hashed_at",
        "sha256_scope",
        "acquisition_manifest_json",
    ] {
        if !existing.iter().any(|name| name == column) {
            conn.execute(
                &format!("ALTER TABLE evidence_sources ADD COLUMN {column} TEXT"),
                [],
            )
            .with_context(|| format!("adding evidence_sources.{column} column"))?;
        }
    }
    // Existing hashes retain their original semantics. Before this column was
    // added, hash_evidence always hashed decoded media for images and the file
    // bytes for ordinary file evidence. Backfill that known scope only; a
    // missing acquisition manifest stays NULL because those files were never
    // independently hashed by the old implementation.
    let needs_scope_backfill = conn
        .query_row(
            "SELECT EXISTS(
                 SELECT 1 FROM evidence_sources
                 WHERE sha256_hex IS NOT NULL AND sha256_scope IS NULL
                 LIMIT 1
             )",
            [],
            |row| row.get::<_, i64>(0),
        )
        .context("checking whether existing evidence hashes need a scope")?
        != 0;
    if needs_scope_backfill {
        conn.execute(
            "UPDATE evidence_sources
             SET sha256_scope = CASE source_kind
                 WHEN 'image' THEN 'logical_media'
                 WHEN 'file' THEN 'file'
                 ELSE NULL
             END
             WHERE sha256_hex IS NOT NULL AND sha256_scope IS NULL",
            [],
        )
        .context("backfilling the known scope of existing evidence hashes")?;
    }
    Ok(())
}

